window.KITAB_MBCL_DATA["lukas"] = {"edition":"MBCL","book":{"id":"lukas","nameBn":"লূক","chapters":24},"contentSha256":"0987b73109b5450466c93ca52bc4c86b482c64e2790bd4a6ac787300d1c55a11","chapters":{"1":[{"heading":"এই সিপারা লিখবার উদ্দেশ্য","v":1,"ve":2,"vl":"1-2","bn":"মাননীয় থিয়ফিল, আমাদের মধ্যে যে সব ঘটনা ঘটেছে তা যাঁরা প্রথম থেকে নিজের চোখে দেখেছেন ও আল্লাহ্‌র সুসংবাদ তবলিগ করেছেন, তাঁরা আমাদের কাছে সব কিছু জানিয়েছেন, আর তাঁদের কথামতই অনেকে সেই সব বিষয়গুলো পরপর লিখেছেন।"},{"v":3,"ve":3,"vl":"3","bn":"সেই সব বিষয় সম্বন্ধে প্রথম থেকে ভালভাবে খোঁজ-খবর নিয়ে আপনার জন্য তা একটা একটা করে লেখা আমিও ভাল মনে করলাম।"},{"v":4,"ve":4,"vl":"4","bn":"এর ফলে আপনি যা জেনেছেন তা সত্যি কি না জানতে পারবেন।"},{"heading":"হযরত ইয়াহিয়া (আঃ)-এর জন্মের বিষয়ে ভবিষ্যদ্বাণী","v":5,"ve":5,"vl":"5","bn":"হেরোদ যখন এহুদিয়া প্রদেশের বাদশাহ্‌ ছিলেন সেই সময়ে ইমাম অবিয়ের দলে জাকারিয়া নামে ইহুদীদের একজন ইমাম ছিলেন। তাঁর স্ত্রীর নাম ছিল এলিজাবেত। তিনিও ছিলেন ইমাম হারুনের একজন বংশধর।"},{"v":6,"ve":6,"vl":"6","bn":"তাঁরা দু’জনেই আল্লাহ্‌র চোখে ধার্মিক ছিলেন। মাবুদের সমস্ত হুকুম ও নিয়ম তাঁরা নিখুঁতভাবে পালন করতেন।"},{"v":7,"ve":7,"vl":"7","bn":"তাঁদের কোন ছেলেমেয়ে হয় নি কারণ এলিজাবেত বন্ধ্যা ছিলেন। এছাড়া তাঁদের বয়সও খুব বেশী হয়ে গিয়েছিল।"},{"v":8,"ve":8,"vl":"8","bn":"একবার নিজের দলের পালার সময় জাকারিয়া ইমাম হিসাবে আল্লাহ্‌র এবাদত-কাজ করছিলেন।"},{"v":9,"ve":9,"vl":"9","bn":"ইমামের কাজের চলতি নিয়ম অনুসারে গুলিবাঁট দ্বারা তাঁকেই বেছে নেওয়া হয়েছিল, যেন তিনি বায়তুল-মোকাদ্দসের পবিত্র স্থানে গিয়ে ধূপ জ্বালাতে পারেন।"},{"v":10,"ve":10,"vl":"10","bn":"ধূপ জ্বালাবার সময় বাইরে অনেক লোক মুনাজাত করছিল।"},{"v":11,"ve":11,"vl":"11","bn":"এমন সময় ধূপগাহের ডানদিকে মাবুদের একজন ফেরেশতা হঠাৎ এসে জাকারিয়াকে দেখা দিলেন।"},{"v":12,"ve":12,"vl":"12","bn":"ফেরেশতাকে দেখে তাঁর মন অস্থির হয়ে উঠল এবং তিনি ভয় পেলেন।"},{"v":13,"ve":13,"vl":"13","bn":"ফেরেশতা তাঁকে বললেন, “জাকারিয়া, ভয় কোরো না, কারণ আল্লাহ্‌ তোমার মুনাজাত শুনেছেন। তোমার স্ত্রী এলিজাবেতের একটি ছেলে হবে। তুমি তার নাম রেখো ইয়াহিয়া।"},{"v":14,"ve":14,"vl":"14","bn":"সে তোমার জীবনে মহা আনন্দের কারণ হবে এবং তার জন্মের দরুন আরও অনেকে আনন্দিত হবে,"},{"v":15,"ve":15,"vl":"15","bn":"কারণ মাবুদের চোখে সে মহান হবে। সে কখনও আংগুর-রস বা কোন রকম মদানো রস খাবে না এবং মায়ের গর্ভে থাকতেই সে পাক-রূহে পূর্ণ হবে।"},{"v":16,"ve":16,"vl":"16","bn":"বনি-ইসরাইলদের অনেককেই সে তাদের মাবুদ আল্লাহ্‌র কাছে ফিরিয়ে আনবে।"},{"v":17,"ve":17,"vl":"17","bn":"নবী ইলিয়াসের মত মনোভাব ও শক্তি নিয়ে সে মাবুদের আগে আসবে। সে পিতার মন সন্তানের দিকে ফিরাবে এবং অবাধ্য লোকদের মনের ভাব বদলে আল্লাহ্‌ভক্ত লোকদের মনের ভাবের মত করবে। এইভাবে সে মাবুদের জন্য এক দল লোককে সম্পূর্ণভাবে প্রস্তুত করবে।”"},{"v":18,"ve":18,"vl":"18","bn":"তখন জাকারিয়া ফেরেশতাকে বললেন, “কিভাবে আমি তা বুঝব? আমি তো বুড়ো হয়ে গেছি এবং আমার স্ত্রীর বয়সও অনেক বেশী হয়ে গেছে।”"},{"v":19,"ve":19,"vl":"19","bn":"ফেরেশতা তাঁকে বললেন, “আমার নাম জিবরাইল; আমি আল্লাহ্‌র সামনে দাঁড়িয়ে থাকি। তোমার সংগে কথা বলবার জন্য ও তোমাকে এই সুসংবাদ দেবার জন্য আল্লাহ্‌ আমাকে পাঠিয়েছেন।"},{"v":20,"ve":20,"vl":"20","bn":"দেখ, আমার কথা সময়মতই পূর্ণ হবে, কিন্তু তুমি আমার কথা বিশ্বাস কর নি বলে বোবা হয়ে থাকবে। যতদিন না এই সব ঘটে ততদিন তুমি কথা বলতে পারবে না।”"},{"v":21,"ve":21,"vl":"21","bn":"এদিকে লোকেরা জাকারিয়ার জন্য অপেক্ষা করছিল। বায়তুল-মোকাদ্দসের পবিত্র স্থানে তাঁর দেরি হচ্ছে দেখে তারা ভাবতে লাগল।"},{"v":22,"ve":22,"vl":"22","bn":"পরে জাকারিয়া যখন বের হয়ে আসলেন তখন লোকদের সংগে কথা বলতে পারলেন না। এতে লোকেরা বুঝতে পারল পবিত্র স্থানে তিনি কোন দর্শন পেয়েছেন। তিনি লোকদের কাছে ইশারায় কথা বলতে থাকলেন এবং বোবা হয়ে রইলেন।"},{"v":23,"ve":23,"vl":"23","bn":"ইমামের কাজের পালা শেষ হবার পরে জাকারিয়া বাড়ী চলে গেলেন।"},{"v":24,"ve":24,"vl":"24","bn":"এর পরে তাঁর স্ত্রী এলিজাবেত গর্ভবতী হলেন এবং পাঁচ মাস পর্যন্ত বাড়ী ছেড়ে বাইরে গেলেন না। তিনি বললেন,"},{"v":25,"ve":25,"vl":"25","bn":"“এটা মাবুদেরই কাজ। মানুষের কাছে আমার লজ্জা দূর করবার জন্য তিনি এখন আমার দিকে চোখ তুলে চেয়েছেন।”"},{"heading":"হযরত ঈসা মসীহের জন্মের বিষয়ে ভবিষ্যদ্বাণী","v":26,"ve":27,"vl":"26-27","bn":"এলিজাবেতের যখন ছয় মাসের গর্ভ তখন আল্লাহ্‌ গালীল প্রদেশের নাসরত গ্রামের মরিয়ম নামে একটি অবিবাহিতা সতী মেয়ের কাছে জিবরাইল ফেরেশতাকে পাঠালেন। বাদশাহ্‌ দাউদের বংশের ইউসুফ নামে একজন লোকের সংগে তাঁর বিয়ের কথাবার্তা ঠিক হয়েছিল।"},{"v":28,"ve":28,"vl":"28","bn":"ফেরেশতা মরিয়মের কাছে এসে তাঁকে সালাম জানিয়ে বললেন, “মাবুদ তোমার সংগে আছেন এবং তোমাকে অনেক দোয়া করেছেন।”"},{"v":29,"ve":29,"vl":"29","bn":"এই কথা শুনে মরিয়মের মন খুব অস্থির হয়ে উঠল। তিনি ভাবতে লাগলেন এই রকম সালামের মানে কি।"},{"v":30,"ve":30,"vl":"30","bn":"ফেরেশতা তাঁকে বললেন, “মরিয়ম, ভয় কোরো না, কারণ আল্লাহ্‌ তোমাকে খুব রহমত করেছেন।"},{"v":31,"ve":31,"vl":"31","bn":"শোন, তুমি গর্ভবতী হবে আর তোমার একটি ছেলে হবে। তুমি তাঁর নাম ঈসা রাখবে।"},{"v":32,"ve":32,"vl":"32","bn":"তিনি মহান হবেন। তাঁকে আল্লাহ্‌তা’লার পুত্র বলা হবে। মাবুদ আল্লাহ্‌ তাঁর পূর্বপুরুষ বাদশাহ্‌ দাউদের সিংহাসন তাঁকে দেবেন।"},{"v":33,"ve":33,"vl":"33","bn":"তিনি ইয়াকুবের বংশের লোকদের উপরে চিরকাল ধরে রাজত্ব করবেন। তাঁর রাজত্ব কখনও শেষ হবে না।”"},{"v":34,"ve":34,"vl":"34","bn":"তখন মরিয়ম ফেরেশতাকে বললেন, “এ কেমন করে হবে? আমার তো বিয়ে হয় নি।”"},{"v":35,"ve":35,"vl":"35","bn":"ফেরেশতা বললেন, “পাক-রূহ্‌ তোমার উপরে আসবেন এবং আল্লাহ্‌তা’লার শক্তির ছায়া তোমার উপরে পড়বে। এইজন্য যে পবিত্র সন্তান জন্মগ্রহণ করবেন তাঁকে ইব্‌নুল্লাহ্‌ বলা হবে।"},{"v":36,"ve":36,"vl":"36","bn":"দেখ, এই বুড়ো বয়সে তোমার আত্মীয়া এলিজাবেতের গর্ভেও ছেলের জন্ম হয়েছে। লোকে বলত তার ছেলেমেয়ে হবে না, কিন্তু এখন তার ছয় মাস চলছে।"},{"v":37,"ve":37,"vl":"37","bn":"আল্লাহ্‌র কাছে অসম্ভব বলে কোন কিছুই নেই।”"},{"v":38,"ve":38,"vl":"38","bn":"মরিয়ম বললেন, “আমি মাবুদের বাঁদী, আপনার কথামতই আমার উপর সব কিছু হোক।” এর পরে ফেরেশতা মরিয়মের কাছ থেকে চলে গেলেন।"},{"heading":"বিবি এলিজাবেতের ঘরে বিবি মরিয়ম","v":39,"ve":39,"vl":"39","bn":"তারপর মরিয়ম তাড়াতাড়ি করে এহুদিয়া প্রদেশের একটা গ্রামে গেলেন। গ্রামটা পাহাড়ী এলাকায় ছিল।"},{"v":40,"ve":40,"vl":"40","bn":"মরিয়ম সেখানে জাকারিয়ার বাড়ীতে ঢুকে এলিজাবেতকে সালাম জানালেন।"},{"v":41,"ve":42,"vl":"41-42","bn":"এলিজাবেত যখন মরিয়মের কথা শুনলেন তখন তাঁর গর্ভের শিশুটি নেচে উঠল। তিনি পাক-রূহে পূর্ণ হয়ে জোরে জোরে বললেন, “সমস্ত স্ত্রীলোকদের মধ্যে তুমি ধন্যা এবং তোমার যে সন্তান হবে সেই সন্তানও ধন্য।"},{"v":43,"ve":43,"vl":"43","bn":"আমার প্রভুর মা আমার কাছে এসেছেন, এ কেমন করে সম্ভব হল?"},{"v":44,"ve":44,"vl":"44","bn":"যখনই আমি তোমার কথা শুনলাম তখনই আমার গর্ভের শিশুটি আনন্দে নেচে উঠল।"},{"v":45,"ve":45,"vl":"45","bn":"তুমি ধন্যা, কারণ তুমি বিশ্বাস করেছ যে, মাবুদ তোমাকে যা বলেছেন তা পূর্ণ হবে।”"},{"v":46,"ve":46,"vl":"46","bn":"তখন মরিয়ম বললেন, “আমার হৃদয় মাবুদের প্রশংসা করছে;"},{"v":47,"ve":47,"vl":"47","bn":"আমার নাজাতদাতা আল্লাহ্‌কে নিয়ে আমার দিল আনন্দে ভরে উঠছে,"},{"v":48,"ve":48,"vl":"48","bn":"কারণ তাঁর এই সামান্যা বাঁদীর দিকে তিনি মনোযোগ দিয়েছেন। এখন থেকে সব লোক আমাকে ধন্যা বলবে,"},{"v":49,"ve":49,"vl":"49","bn":"কারণ শক্তিমান আল্লাহ্‌ আমার জন্য কত না মহৎ কাজ করেছেন। তিনি পবিত্র।"},{"v":50,"ve":50,"vl":"50","bn":"যারা তাঁকে ভয় করে তাদের প্রতি তিনি মমতা করেন, বংশের পর বংশ ধরেই করেন।"},{"v":51,"ve":51,"vl":"51","bn":"তিনি হাত বাড়িয়ে মহাশক্তির কাজ করেছেন; যাদের মন অহংকারে ভরা তাদের তিনি চারদিকে দূর করে দিয়েছেন।"},{"v":52,"ve":52,"vl":"52","bn":"সিংহাসন থেকে বাদশাহ্‌দের তিনি নামিয়ে দিয়েছেন, কিন্তু সাধারণ লোকদের তুলে ধরেছেন।"},{"v":53,"ve":53,"vl":"53","bn":"যাদের অভাব আছে, ভাল ভাল জিনিস দিয়ে তিনি তাদের অভাব পূরণ করেছেন, কিন্তু ধনীদের খালি হাতে বিদায় করেছেন।"},{"v":54,"ve":55,"vl":"54-55","bn":"তিনি আমাদের পূর্বপুরুষদের কাছে যে ওয়াদা করেছিলেন, সেইমতই তিনি তাঁর গোলাম ইসরাইলকে সাহায্য করেছেন। ইব্রাহিম ও তাঁর বংশের লোকদের উপরে চিরকাল মমতা করবার কথা তিনি মনে রেখেছেন।”"},{"v":56,"ve":56,"vl":"56","bn":"প্রায় তিন মাস এলিজাবেতের কাছে থাকবার পর মরিয়ম নিজের বাড়ীতে ফিরে গেলেন।"},{"heading":"হযরত ইয়াহিয়া (আঃ)-এর জন্ম","v":57,"ve":57,"vl":"57","bn":"সময় পূর্ণ হলে পর এলিজাবেতের একটি ছেলে হল।"},{"v":58,"ve":58,"vl":"58","bn":"তাঁর উপর মাবুদের প্রচুর মমতার কথা শুনে প্রতিবেশীরা ও আত্মীয়রা তাঁর সংগে আনন্দ করতে লাগল।"},{"v":59,"ve":59,"vl":"59","bn":"ইহুদীদের নিয়ম মত আট দিনের দিন তারা ছেলেটির খৎনা করাবার কাজে যোগ দিতে আসল। তারা ছেলেটির নাম তার পিতার নামের মত জাকারিয়া রাখতে চাইল,"},{"v":60,"ve":60,"vl":"60","bn":"কিন্তু তার মা বললেন, “না, এর নাম ইয়াহিয়া রাখা হবে।”"},{"v":61,"ve":61,"vl":"61","bn":"তারা এলিজাবেতকে বলল, “আপনার আত্মীয়-স্বজনদের মধ্যে তো কারও ঐ নাম নেই।”"},{"v":62,"ve":62,"vl":"62","bn":"তারা ইশারা করে ছেলেটির পিতার কাছ থেকে জানতে চাইল তিনি কি নাম দিতে চান।"},{"v":63,"ve":63,"vl":"63","bn":"জাকারিয়া লিখবার জিনিস চেয়ে নিয়ে লিখলেন, “ওর নাম ইয়াহিয়া।” এতে তারা সবাই অবাক হল,"},{"v":64,"ve":64,"vl":"64","bn":"আর তখনই জাকারিয়ার মুখ ও জিভ্‌ খুলে গেল এবং তিনি কথা বলতে ও আল্লাহ্‌র প্রশংসা করতে লাগলেন।"},{"v":65,"ve":65,"vl":"65","bn":"এ দেখে প্রতিবেশীরা সবাই ভয় পেল, আর এহুদিয়ার সমস্ত পাহাড়ী এলাকার লোকেরা এই সব বিষয়ে বলাবলি করতে লাগল।"},{"v":66,"ve":66,"vl":"66","bn":"যারা এই সব কথা শুনল তারা প্রত্যেকেই মনে মনে তা ভাবতে লাগল আর বলল, “বড় হয়ে এই ছেলেটি তবে কি হবে!” তারা এই কথা বলল, কারণ মাবুদের শক্তি এই ছেলেটির উপর দেখা গিয়েছিল।"},{"heading":"হযরত জাকারিয়ার মুখে আল্লাহ্‌র প্রশংসা","v":67,"ve":67,"vl":"67","bn":"পরে ছেলেটির পিতা জাকারিয়া পাক-রূহে পূর্ণ হয়ে নবী হিসাবে এই কথা বলতে লাগলেন,"},{"v":68,"ve":68,"vl":"68","bn":"“ইসরাইলের মাবুদ আল্লাহ্‌র প্রশংসা হোক, কারণ তিনি তাঁর নিজের বান্দাদের দিকে মনোযোগ দিয়েছেন আর তাদের মুক্ত করেছেন।"},{"v":69,"ve":69,"vl":"69","bn":"তিনি আমাদের জন্য তাঁর গোলাম দাউদের বংশ থেকে একজন শক্তিশালী নাজাতদাতা তুলেছেন।"},{"v":70,"ve":70,"vl":"70","bn":"এই কথা তাঁর পবিত্র নবীদের মুখ দিয়ে তিনি অনেক দিন আগেই বলেছিলেন।"},{"v":71,"ve":71,"vl":"71","bn":"তিনি শত্রুদের হাত থেকে আর যারা ঘৃণা করে তাদের সকলের হাত থেকে আমাদের রক্ষা করেছেন।"},{"v":72,"ve":72,"vl":"72","bn":"তিনি আমাদের পূর্বপুরুষদের মমতা করবার জন্য আর তাঁর পবিত্র ব্যবস্থা, অর্থাৎ তাঁর কসম পূর্ণ করবার জন্য আমাদের রক্ষা করেছেন।"},{"v":73,"ve":75,"vl":"73-75","bn":"সেই কসম তিনি আমাদের পূর্বপুরুষ ইব্রাহিমের কাছে খেয়েছিলেন। তিনি শত্রুদের হাত থেকে আমাদের উদ্ধার করেছেন যেন যতদিন বেঁচে থাকি পবিত্র ও সৎভাবে তাঁর সামনে দাঁড়িয়ে নির্ভয়ে তাঁর এবাদত করতে পারি।"},{"v":76,"ve":76,"vl":"76","bn":"সন্তান আমার, তোমাকে আল্লাহ্‌তা’লার নবী বলা হবে, কারণ তুমি তাঁর পথ ঠিক করবার জন্য তাঁর আগে আগে চলবে।"},{"v":77,"ve":78,"vl":"77-78","bn":"তুমি তাঁর বান্দাদের জানাবে, কিভাবে আমাদের আল্লাহ্‌র মমতার দরুন গুনাহের মাফ পেয়ে নাজাত পাওয়া যায়। তাঁর মমতায় বেহেশত থেকে এক উঠন্ত সূর্য আমাদের উপর নেমে আসবেন,"},{"v":79,"ve":79,"vl":"79","bn":"যাতে অন্ধকারে ও মৃত্যুর ছায়ায় যারা বসে আছে তাদের নূর দিতে পারেন, আর শান্তির পথে আমাদের চালাতে পারেন।”"},{"v":80,"ve":80,"vl":"80","bn":"পরে ইয়াহিয়া বেড়ে উঠতে লাগলেন এবং দিলে শক্তিশালী হয়ে উঠতে থাকলেন। বনি-ইসরাইলদের সামনে খোলাখুলিভাবে উপস্থিতির আগ পর্যন্ত তিনি মরুভূমিতে ছিলেন।"}],"2":[{"heading":"হযরত ঈসা মসীহের জন্ম","v":1,"ve":1,"vl":"1","bn":"সেই সময়ে সম্রাট অগাস্টাস সিজার তাঁর রাজ্যের সব লোকদের নাম লেখাবার হুকুম দিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"সিরিয়ার শাসনকর্তা কুরীণিয়ের সময়ে এই প্রথমবার আদমশুমারীর জন্য নাম লেখানো হয়।"},{"v":3,"ve":3,"vl":"3","bn":"নাম লেখাবার জন্য প্রত্যেকে নিজের নিজের গ্রামে যেতে লাগল।"},{"v":4,"ve":6,"vl":"4-6","bn":"ইউসুফ ছিলেন বাদশাহ্‌ দাউদের বংশের লোক। বাদশাহ্‌ দাউদের জন্মস্থান ছিল এহুদিয়া প্রদেশের বেথেলহেম গ্রামে। তাই ইউসুফ নাম লেখাবার জন্য গালীল প্রদেশের নাসরত গ্রাম থেকে বেথেলহেম গ্রামে গেলেন। মরিয়মও তাঁর সংগে সেখানে গেলেন। এঁরই সংগে ইউসুফের বিয়ে ঠিক হয়েছিল। সেই সময় মরিয়ম গর্ভবতী ছিলেন এবং বেথেলহেমে থাকতেই তাঁর সন্তান জন্মের সময় এসে গেল।"},{"v":7,"ve":7,"vl":"7","bn":"সেখানে তাঁর প্রথম ছেলের জন্ম হল, আর তিনি ছেলেটিকে কাপড়ে জড়িয়ে যাবপাত্রে রাখলেন, কারণ হোটেলে তাঁদের জন্য কোন জায়গা ছিল না।"},{"heading":"ফেরেশতা ও রাখালেরা","v":8,"ve":8,"vl":"8","bn":"বেথেলহেমের কাছে মাঠের মধ্যে রাতের বেলায় রাখালেরা তাদের ভেড়ার পাল পাহারা দিচ্ছিল।"},{"v":9,"ve":9,"vl":"9","bn":"এমন সময় মাবুদের একজন ফেরেশতা হঠাৎ তাদের সামনে উপস্থিত হলেন। তখন মাবুদের মহিমা তাদের চারদিকে উজ্জ্বল হয়ে দেখা দিল। এতে রাখালেরা খুব ভয় পেল।"},{"v":10,"ve":10,"vl":"10","bn":"ফেরেশতা তাদের বললেন, “ভয় কোরো না, কারণ আমি তোমাদের কাছে খুব আনন্দের খবর এনেছি। এই আনন্দ সব লোকেরই জন্য।"},{"v":11,"ve":11,"vl":"11","bn":"আজ দাউদের গ্রামে তোমাদের নাজাতদাতা জন্মেছেন। তিনিই মসীহ্‌, তিনিই প্রভু।"},{"v":12,"ve":12,"vl":"12","bn":"এই কথা যে সত্যি তোমাদের কাছে তার চিহ্ন হল এই- তোমরা কাপড়ে জড়ানো এবং যাবপাত্রে শোয়ানো একটি শিশুকে দেখতে পাবে।”"},{"v":13,"ve":13,"vl":"13","bn":"এই সময় সেই ফেরেশতার সংগে হঠাৎ সেখানে আরও অনেক ফেরেশতাকে দেখা গেল। তাঁরা আল্লাহ্‌র প্রশংসা করে বলতে লাগলেন,"},{"v":14,"ve":14,"vl":"14","bn":"“বেহেশতে আল্লাহ্‌র প্রশংসা হোক, দুনিয়াতে যাদের উপর তিনি সন্তুষ্ট তাদের শান্তি হোক।”"},{"v":15,"ve":15,"vl":"15","bn":"ফেরেশতারা তাদের কাছ থেকে বেহেশতে চলে যাবার পর রাখালেরা একে অন্যকে বলল, “চল, আমরা বেথেলহেমে যাই এবং যে ঘটনার কথা মাবুদ আমাদের জানালেন তা গিয়ে দেখি।”"},{"v":16,"ve":16,"vl":"16","bn":"তারা তাড়াতাড়ি গিয়ে মরিয়ম, ইউসুফ ও যাবপাত্রে শোয়ানো সেই শিশুটিকে তালাশ করে বের করল।"},{"v":17,"ve":17,"vl":"17","bn":"তাদের কাছে ঐ শিশুর বিষয়ে যা জানানো হয়েছিল, শিশুটিকে দেখবার পরে তারা তা বলল।"},{"v":18,"ve":18,"vl":"18","bn":"রাখালদের কথা শুনে সবাই আশ্চর্য হল;"},{"v":19,"ve":19,"vl":"19","bn":"কিন্তু মরিয়ম সব কিছু মনে গেঁথে রাখলেন, কাউকে বললেন না; তিনি সেই বিষয়ে চিন্তা করতে থাকলেন।"},{"v":20,"ve":20,"vl":"20","bn":"ফেরেশতারা রাখালদের কাছে যা বলেছিলেন সব কিছু সেইমত দেখে ও শুনে তারা আল্লাহ্‌র প্রশংসা ও গৌরব করতে করতে ফিরে গেল।"},{"v":21,"ve":21,"vl":"21","bn":"জন্মের আট দিনের দিন ইহুদীদের নিয়ম মত যখন শিশুটির খৎনা করাবার সময় হল তখন তাঁর নাম রাখা হল ঈসা। মায়ের গর্ভে আসবার আগে ফেরেশতা তাঁর এই নামই দিয়েছিলেন।"},{"heading":"বায়তুল-মোকাদ্দসে শিশু ঈসা","v":22,"ve":22,"vl":"22","bn":"পরে মূসার শরীয়ত মতে তাঁদের পাক-সাফ হবার সময় হল। তখন ইউসুফ ও মরিয়ম ঈসাকে মাবুদের সামনে উপস্থিত করবার জন্য তাঁকে জেরুজালেম শহরে নিয়ে গেলেন,"},{"v":23,"ve":23,"vl":"23","bn":"কারণ মাবুদের শরীয়তে লেখা আছে, “প্রথমে জন্মেছে এমন প্রত্যেকটি পুরুষ সন্তানকে মাবুদের বলে ধরা হবে।”"},{"v":24,"ve":24,"vl":"24","bn":"এছাড়াও “এক জোড়া ঘুঘু কিংবা দু’টা কবুতরের বাচ্চা” কোরবানী দেবার কথা যেমন মাবুদের শরীয়তে লেখা আছে সেইভাবে তাঁরা তা কোরবানী দিতে গেলেন।"},{"v":25,"ve":26,"vl":"25-26","bn":"তখন জেরুজালেমে শামাউন নামে একজন ধার্মিক ও আল্লাহ্‌ভক্ত লোক ছিলেন। আল্লাহ্‌ কবে বনি-ইসরাইলদের দুঃখ দূর করবেন সেই সময়ের জন্য তিনি অপেক্ষা করছিলেন। পাক-রূহ্‌ তাঁর উপর ছিলেন এবং তাঁর কাছে প্রকাশ করেছিলেন যে, মারা যাবার আগে তিনি মাবুদের সেই মসীহ্‌কে দেখতে পাবেন।"},{"v":27,"ve":27,"vl":"27","bn":"পাক-রূহের দ্বারা চালিত হয়ে শামাউন সেই দিন বায়তুল-মোকাদ্দসে আসলেন। মূসার শরীয়ত মতে যা করা দরকার তা করবার জন্য ঈসার মা-বাবা শিশু ঈসাকে নিয়ে সেখানে আসলেন।"},{"v":28,"ve":28,"vl":"28","bn":"তখন শামাউন তাঁকে কোলে নিলেন এবং আল্লাহ্‌র প্রশংসা করে বললেন,"},{"v":29,"ve":29,"vl":"29","bn":"“মাবুদ, তুমি তোমার কথামত তোমার গোলামকে এখন শান্তিতে বিদায় দিচ্ছ,"},{"v":30,"ve":31,"vl":"30-31","bn":"কারণ মানুষকে নাজাত করবার জন্য সমস্ত লোকের চোখের সামনে তুমি যে ব্যবস্থা করেছ, আমি তা দেখতে পেয়েছি।"},{"v":32,"ve":32,"vl":"32","bn":"অন্য জাতির কাছে এটা পথ দেখাবার নূর, আর তোমার ইসরাইল জাতির কাছে এটা গৌরবের বিষয়।”"},{"v":33,"ve":33,"vl":"33","bn":"শামাউন শিশুটির বিষয়ে যা বললেন তাতে শিশুটির মা-বাবা আশ্চর্য হলেন।"},{"v":34,"ve":34,"vl":"34","bn":"এর পরে শামাউন তাঁদের দোয়া করলেন এবং ঈসার মা মরিয়মকে বললেন, “আল্লাহ্‌ এটাই স্থির করেছেন যে, এই শিশুটির জন্য বনি-ইসরাইলদের মধ্যে অনেকেরই পতন হবে, আবার অনেকেই উদ্ধার পাবে। ইনি এমন একটা চিহ্ন হবেন যাঁর বিরুদ্ধে অনেকেই কথা বলবে,"},{"v":35,"ve":35,"vl":"35","bn":"আর তাতে তাদের মনের চিন্তা প্রকাশ হয়ে পড়বে। এছাড়া ছোরার আঘাতের মত দুঃখ তোমার দিলকে বিঁধবে।”"},{"v":36,"ve":37,"vl":"36-37","bn":"সেই সময় হান্না নামে একজন মহিলা-নবী ছিলেন। তিনি আশের বংশের পনূয়েলের মেয়ে। তাঁর অনেক বয়স হয়েছিল। সাত বছর স্বামীর ঘর করবার পরে চুরাশি বছর বয়স পর্যন্ত তিনি বিধবার জীবন কাটিয়েছিলেন। বায়তুল-মোকাদ্দস ছেড়ে তিনি কোথাও যেতেন না বরং রোজা ও মুনাজাতের মধ্য দিয়ে দিন রাত আল্লাহ্‌র এবাদত করতেন।"},{"v":38,"ve":38,"vl":"38","bn":"তিনিও ঠিক সেই সময় এগিয়ে এসে আল্লাহ্‌র শুকরিয়া আদায় করতে লাগলেন, আর আল্লাহ্‌ জেরুজালেমকে মুক্ত করবেন বলে যারা অপেক্ষা করছিল তাদের কাছে সেই শিশুটির কথা বলতে লাগলেন।"},{"v":39,"ve":39,"vl":"39","bn":"মাবুদের শরীয়ত মতে সব কিছু শেষ করে মরিয়ম ও ইউসুফ গালীলে তাঁদের নিজেদের গ্রাম নাসরতে ফিরে গেলেন।"},{"v":40,"ve":40,"vl":"40","bn":"শিশু ঈসা বয়সে বেড়ে শক্তিমান হয়ে উঠলেন এবং জ্ঞানে পূর্ণ হতে থাকলেন। তাঁর উপরে আল্লাহ্‌র দোয়া ছিল।"},{"heading":"বায়তুল-মোকাদ্দসে বারো বছরের হযরত ঈসা মসীহ্‌","v":41,"ve":41,"vl":"41","bn":"উদ্ধার-ঈদের সময়ে ঈসার মা-বাবা প্রত্যেক বছর জেরুজালেমে যেতেন।"},{"v":42,"ve":42,"vl":"42","bn":"ঈসার বয়স যখন বারো বছর তখন নিয়ম মতই তাঁরা সেই ঈদে গেলেন।"},{"v":43,"ve":43,"vl":"43","bn":"ঈদের শেষে তাঁরা যখন বাড়ী ফিরছিলেন তখন ঈসা জেরুজালেমেই থেকে গেলেন। তাঁর মা-বাবা কিন্তু সেই কথা জানতেন না।"},{"v":44,"ve":44,"vl":"44","bn":"তিনি সংগের লোকদের মধ্যে আছেন মনে করে তাঁরা এক দিনের পথ চলে গেলেন। পরে তাঁরা তাঁদের আত্মীয় ও জানাশোনা লোকদের মধ্যে ঈসার তালাশ করতে লাগলেন।"},{"v":45,"ve":45,"vl":"45","bn":"কিন্তু তালাশ করে না পেয়ে তাঁকে তালাশ করতে করতে তাঁরা আবার জেরুজালেমে ফিরে গেলেন।"},{"v":46,"ve":46,"vl":"46","bn":"শেষে তিন দিন পরে তাঁরা তাঁকে বায়তুল-মোকাদ্দসে পেলেন। তিনি আলেমদের মধ্যে বসে তাঁদের কথা শুনছিলেন ও তাঁদের প্রশ্ন জিজ্ঞাসা করছিলেন।"},{"v":47,"ve":47,"vl":"47","bn":"যাঁরা ঈসার কথা শুনছিলেন তাঁরা সবাই তাঁর বুদ্ধি দেখে ও তাঁর জবাব শুনে অবাক হচ্ছিলেন।"},{"v":48,"ve":48,"vl":"48","bn":"তাঁর মা-বাবা তাঁকে দেখে আশ্চর্য হলেন। তাঁর মা তাঁকে বললেন, “বাবা, তুমি আমাদের সংগে কেন এমন করলে? তোমার পিতা ও আমি কত ব্যাকুল হয়ে তোমার তালাশ করছিলাম।”"},{"v":49,"ve":49,"vl":"49","bn":"ঈসা তাঁদের বললেন, “তোমরা কেন আমার তালাশ করছিলে? তোমরা কি জানতে না যে, আমার পিতার ঘরে আমাকে থাকতে হবে?”"},{"v":50,"ve":50,"vl":"50","bn":"ঈসা যা বললেন তাঁর মা-বাবা তা বুঝলেন না।"},{"v":51,"ve":51,"vl":"51","bn":"এর পরে তিনি তাঁদের সংগে নাসরতে ফিরে গেলেন এবং তাঁদের বাধ্য হয়ে রইলেন। তাঁর মা এই সব বিষয় মনে গেঁথে রাখলেন।"},{"v":52,"ve":52,"vl":"52","bn":"ঈসা জ্ঞানে, বয়সে এবং আল্লাহ্‌ ও মানুষের মহব্বতে বেড়ে উঠতে লাগলেন।"}],"3":[{"heading":"হযরত ইয়াহিয়া (আঃ)-এর তবলিগ","v":1,"ve":1,"vl":"1","bn":"রোম-সম্রাট টিবেরিয়াস সিজারের রাজত্বের পনের বছরের সময় এহুদিয়া প্রদেশের প্রধান শাসনকর্তা ছিলেন পন্তীয় পীলাত। তখন হেরোদ গালীল প্রদেশ ও তাঁর ভাই ফিলিপ যিতূরিয়া প্রদেশ ও ত্রাখোনীতিয়া শাসন করছিলেন। লুষানিয়া ছিলেন অবিলীনীর শাসনকর্তা,"},{"v":2,"ve":2,"vl":"2","bn":"আর হানন ও কাইয়াফা ছিলেন ইহুদীদের মহা-ইমাম। ঠিক এই সময়ে আল্লাহ্‌ মরুভূমিতে জাকারিয়ার পুত্র ইয়াহিয়ার উপর তাঁর কালাম নাজেল করলেন।"},{"v":3,"ve":3,"vl":"3","bn":"তখন ইয়াহিয়া জর্ডান নদীর চারদিকের সমস্ত জায়গায় গিয়ে তবলিগ করতে লাগলেন যেন লোকে গুনাহের মাফ পাবার জন্য তওবা করে এবং তার চিহ্ন হিসাবে তরিকাবন্দী নেয়।"},{"v":4,"ve":4,"vl":"4","bn":"নবী ইশাইয়ার কিতাবে যা লেখা আছে ঠিক সেইভাবে এই সব হল। লেখা আছে, “মরুভূমিতে একজনের কন্ঠস্বর চিৎকার করে জানাচ্ছে, ‘তোমরা মাবুদের পথ ঠিক কর, তাঁর রাস্তা সোজা কর।"},{"v":5,"ve":5,"vl":"5","bn":"সমস্ত উপত্যকা ভরা হবে, পাহাড়-পর্বত সমান করা হবে। আঁকাবাঁকা পথ সোজা করা হবে, অসমান রাস্তা সমান করা হবে।"},{"v":6,"ve":6,"vl":"6","bn":"মানুষকে নাজাত করবার জন্য আল্লাহ্‌ যা করেছেন, সব লোকেই তা দেখতে পাবে।’ ”"},{"v":7,"ve":7,"vl":"7","bn":"তখন তরিকাবন্দী নেবার জন্য অনেক লোক ইয়াহিয়ার কাছে আসতে লাগল। ইয়াহিয়া তাদের বললেন, “সাপের বংশধরেরা! আল্লাহ্‌র যে গজব নেমে আসছে তা থেকে পালিয়ে যাবার এই বুদ্ধি তোমাদের কে দিল?"},{"v":8,"ve":8,"vl":"8","bn":"তোমরা যে তওবা করেছ তার উপযুক্ত ফল তোমাদের জীবনে দেখাও। নিজেদের মনে ভেবো না যে, তোমরা ইব্রাহিমের বংশের লোক। আমি তোমাদের বলছি, এই পাথরগুলো থেকে আল্লাহ্‌ ইব্রাহিমের বংশধর তৈরী করতে পারেন।"},{"v":9,"ve":9,"vl":"9","bn":"গাছের গোড়াতে কুড়াল লাগানোই আছে। যে গাছে ভাল ফল ধরে না তা কেটে আগুনে ফেলে দেওয়া হবে।”"},{"v":10,"ve":10,"vl":"10","bn":"তখন লোকেরা ইয়াহিয়াকে জিজ্ঞাসা করল, “তা হলে আমরা কি করব?”"},{"v":11,"ve":11,"vl":"11","bn":"ইয়াহিয়া তাদের বললেন, “যদি কারও দু’টা কোর্তা থাকে তবে যার কোর্তা নেই সে তাকে একটা দিক। যার খাবার আছে সেও সেই রকম করুক।”"},{"v":12,"ve":12,"vl":"12","bn":"কয়েকজন খাজনা-আদায়কারী তরিকাবন্দী নেবার জন্য এসে ইয়াহিয়াকে বলল, “হুজুর, আমরা কি করব?”"},{"v":13,"ve":13,"vl":"13","bn":"তিনি তাদের বললেন, “আইনে যা আছে তার বেশী আদায় কোরো না।”"},{"v":14,"ve":14,"vl":"14","bn":"কয়েকজন সৈন্যও তাঁকে জিজ্ঞাসা করল, “আর আমরা কি করব?” তিনি সেই সৈন্যদের বললেন, “জুলুম করে বা অন্যায়ভাবে দোষ দেখিয়ে কারও কাছ থেকে কিছু আদায় কোরো না এবং তোমাদের বেতনেই সন্তুষ্ট থেকো।”"},{"v":15,"ve":15,"vl":"15","bn":"লোকেরা খুব আশা নিয়ে মনে মনে ভাবছিল হয়ত বা ইয়াহিয়াই মসীহ্‌।"},{"v":16,"ve":16,"vl":"16","bn":"এমন সময় ইয়াহিয়া তাদের সবাইকে বললেন, “আমি তোমাদের পানিতে তরিকাবন্দী দিচ্ছি, কিন্তু যিনি আমার চেয়ে শক্তিশালী তিনি আসছেন। আমি তাঁর জুতার ফিতা খুলবারও যোগ্য নই। তিনি পাক-রূহ্‌ ও আগুনে তোমাদের তরিকাবন্দী দেবেন।"},{"v":17,"ve":17,"vl":"17","bn":"কুলা তাঁর হাতেই আছে; তা দিয়ে তিনি তাঁর ফসল মাড়াবার জায়গা পরিষ্কার করে ফসল গোলায় জমা করবেন, কিন্তু যে আগুন কখনও নেভে না তাতে তিনি তুষ পুড়িয়ে ফেলবেন।”"},{"v":18,"ve":18,"vl":"18","bn":"ইয়াহিয়া আরও অনেক উপদেশের মধ্য দিয়ে লোকদের মনে উৎসাহ জাগিয়ে আল্লাহ্‌র দেওয়া সুসংবাদ তবলিগ করলেন।"},{"v":19,"ve":19,"vl":"19","bn":"শাসনকর্তা হেরোদের ভাইয়ের স্ত্রী হেরোদিয়ার সংগে হেরোদের সম্পর্কে র দরুন এবং তাঁর আরও অনেক খারাপ কাজের দরুন ইয়াহিয়া তাঁর দোষ দেখিয়ে দিয়েছিলেন।"},{"v":20,"ve":20,"vl":"20","bn":"তাতে তিনি ইয়াহিয়াকে বন্দী করে জেলে দিলেন। এতে তাঁর অন্য সব খারাপ কাজের সংগে এই খারাপ কাজটাও যোগ হল।"},{"heading":"হযরত ঈসা মসীহের তরিকাবন্দী","v":21,"ve":21,"vl":"21","bn":"যে সমস্ত লোক ইয়াহিয়ার কাছে এসেছিল তারা তরিকাবন্দী নেবার সময় ঈসাও তরিকাবন্দী নিলেন। তরিকাবন্দীর পরে ঈসা যখন মুনাজাত করছিলেন তখন আসমান খুলে গেল।"},{"v":22,"ve":22,"vl":"22","bn":"সেই সময় পাক-রূহ্‌ কবুতরের আকার নিয়ে তাঁর উপর নেমে আসলেন, আর বেহেশত থেকে এই কথা শোনা গেল, “তুমিই আমার প্রিয় পুত্র, তোমার উপর আমি খুবই সন্তুষ্ট।”"},{"heading":"হযরত ঈসা মসীহের বংশ-তালিকা","v":23,"ve":23,"vl":"23","bn":"প্রায় তিরিশ বছর বয়সে ঈসা তাঁর কাজ শুরু করলেন। লোকে মনে করত তিনি ইউসুফের ছেলে। ইউসুফ আলীর ছেলে;"},{"v":24,"ve":24,"vl":"24","bn":"আলী মত্ততের ছেলে, মত্তত লেবির ছেলে, লেবি মল্কির ছেলে, মল্কি যান্নায়ের ছেলে, যান্নায় ইউসুফের ছেলে;"},{"v":25,"ve":25,"vl":"25","bn":"ইউসুফ মত্তথিয়ের ছেলে, মত্তথিয় আমোজের ছেলে, আমোজ নাহূমের ছেলে, নাহূম ইষ্‌লির ছেলে, ইষ্‌লি নগির ছেলে;"},{"v":26,"ve":26,"vl":"26","bn":"নগি মাটের ছেলে, মাট মত্তথিয়ের ছেলে, মত্তথিয় শিমিয়ির ছেলে, শিমিয়ি যোষেখের ছেলে, যোষেখ যূদার ছেলে;"},{"v":27,"ve":27,"vl":"27","bn":"যূদা যোহানার ছেলে, যোহানা রীষার ছেলে, রীষা সরুব্বাবিলের ছেলে, সরুব্বাবিল শল্টীয়েলের ছেলে, শল্টীয়েল নেরির ছেলে;"},{"v":28,"ve":28,"vl":"28","bn":"নেরি মল্কির ছেলে, মল্কি অদ্দীর ছেলে, অদ্দী কোষমের ছেলে, কোষম ইল্‌মাদমের ছেলে, ইল্‌মাদম এরের ছেলে;"},{"v":29,"ve":29,"vl":"29","bn":"এর ইউসার ছেলে, ইউসা ইলীয়েষরের ছেলে, ইলীয়েষর যোরীমের ছেলে, যোরীম মত্ততের ছেলে, মত্তত লেবির ছেলে;"},{"v":30,"ve":30,"vl":"30","bn":"লেবি শামাউনের ছেলে, শামাউন যূদার ছেলে, যূদা ইউসুফের ছেলে, ইউসুফ যোনমের ছেলে, যোনম ইলিয়াকীমের ছেলে;"},{"v":31,"ve":31,"vl":"31","bn":"ইলিয়াকীম মিলেয়ার ছেলে, মিলেয়া মিন্নার ছেলে, মিন্না মত্তথের ছেলে, মত্তথ নাথনের ছেলে, নাথন দাউদের ছেলে;"},{"v":32,"ve":32,"vl":"32","bn":"দাউদ ইয়াসির ছেলে, ইয়াসি ওবেদের ছেলে, ওবেদ বোয়সের ছেলে, বোয়স সল্‌মোনের ছেলে, সল্‌মোন নহশোনের ছেলে;"},{"v":33,"ve":33,"vl":"33","bn":"নহশোন অম্মীনাদবের ছেলে, অম্মীনাদব অদমানের ছেলে, অদমান অর্ণির ছেলে, অর্ণি হিষ্রোণের ছেলে, হিষ্রোণ পেরসের ছেলে, পেরস এহুদার ছেলে;"},{"v":34,"ve":34,"vl":"34","bn":"এহুদা ইয়াকুবের ছেলে, ইয়াকুব ইসহাকের ছেলে, ইসহাক ইব্রাহিমের ছেলে, ইব্রাহিম তারেখের ছেলে, তারেখ নাহুরের ছেলে;"},{"v":35,"ve":35,"vl":"35","bn":"নাহুর সারূজের ছেলে, সারূজ রাউর ছেলে, রাউ ফালেজের ছেলে, ফালেজ আবেরের ছেলে, আবের শালেখের ছেলে;"},{"v":36,"ve":36,"vl":"36","bn":"শালেখ কীনানের ছেলে, কীনান আরফাখশাদের ছেলে, আরফাখশাদ সামের ছেলে, সাম নূহের ছেলে, নূহ লামাকের ছেলে;"},{"v":37,"ve":37,"vl":"37","bn":"লামাক মুতাওশালেহের ছেলে, মুতাওশালেহ ইনোকের ছেলে, ইনোক ইয়ারুদের ছেলে, ইয়ারুদ মাহলাইলের ছেলে, মাহলাইল কীনানের ছেলে;"},{"v":38,"ve":38,"vl":"38","bn":"কীনান আনুশের ছেলে, আনুশ শিসের ছেলে, শিস আদমের ছেলে, আদম আল্লাহ্‌র ছেলে।"}],"4":[{"heading":"হযরত ঈসা মসীহ্‌কে গুনাহে ফেলবার চেষ্টা","v":1,"ve":2,"vl":"1-2","bn":"ঈসা পাক-রূহে পূর্ণ হয়ে জর্ডান নদী থেকে চলে গেলেন। পাক-রূহের পরিচালনায় তিনি চল্লিশ দিন ধরে মরুভূমিতে ঘুরে বেড়াতে লাগলেন। সেই সময় ইবলিস তাঁকে লোভ দেখিয়ে গুনাহে ফেলবার চেষ্টা করতে থাকল। এই চল্লিশ দিন ঈসা কিছুই খান নি; সেইজন্য এই দিনগুলো কেটে যাবার পর তাঁর খিদে পেল।"},{"v":3,"ve":3,"vl":"3","bn":"তখন ইবলিস ঈসাকে বলল, “তুমি যদি ইব্‌নুল্লাহ্‌ হও তবে এই পাথরটাকে রুটি হয়ে যেতে বল।”"},{"v":4,"ve":4,"vl":"4","bn":"ঈসা ইবলিসকে বললেন, “পাক-কিতাবে লেখা আছে, ‘মানুষ কেবল রুটিতেই বাঁচে না।’ ”"},{"v":5,"ve":6,"vl":"5-6","bn":"এর পরে ইবলিস তাঁকে একটা উঁচু জায়গায় নিয়ে গেল এবং মুহূর্তের মধ্যে দুনিয়ার সব রাজ্যগুলো দেখিয়ে বলল, “এই সবের অধিকার ও সেগুলোর জাঁকজমক আমি তোমাকে দেব, কারণ এই সব আমাকে দেওয়া হয়েছে। আমার যাকে ইচ্ছা আমি তাকেই তা দিতে পারি।"},{"v":7,"ve":7,"vl":"7","bn":"এখন তুমি যদি আমাকে সেজদা কর তবে এই সবই তোমার হবে।”"},{"v":8,"ve":8,"vl":"8","bn":"ঈসা তাকে জবাব দিলেন, “পাক-কিতাবে লেখা আছে, ‘তুমি তোমার মাবুদ আল্লাহ্‌কেই ভয় করবে, কেবল তাঁরই এবাদত করবে।’ ”"},{"v":9,"ve":9,"vl":"9","bn":"তখন ইবলিস ঈসাকে জেরুজালেমে নিয়ে গেল আর বায়তুল-মোকাদ্দসের চূড়ার উপরে তাঁকে দাঁড় করিয়ে বলল, “তুমি যদি ইব্‌নুল্লাহ্‌ হও তবে এখান থেকে লাফ দিয়ে নীচে পড়,"},{"v":10,"ve":10,"vl":"10","bn":"কারণ পাক-কিতাবে লেখা আছে, তিনি তাঁর ফেরেশতাদের তোমার বিষয়ে হুকুম দেবেন যেন তাঁরা তোমাকে রক্ষা করেন।"},{"v":11,"ve":11,"vl":"11","bn":"তাঁরা তোমাকে হাত দিয়ে ধরে ফেলবেন যাতে তোমার পায়ে পাথরের আঘাত না লাগে।”"},{"v":12,"ve":12,"vl":"12","bn":"ঈসা তাকে বললেন, “পাক-কিতাবে বলা হয়েছে, ‘তোমার মাবুদ আল্লাহ্‌কে তুমি পরীক্ষা করতে যেয়ো না।’ ”"},{"v":13,"ve":13,"vl":"13","bn":"সমস্ত রকম লোভ দেখানো শেষ করে ইবলিস অল্প সময়ের জন্য ঈসার কাছ থেকে চলে গেল।"},{"heading":"নাসরতে হযরত ঈসা মসীহের উপদেশ","v":14,"ve":14,"vl":"14","bn":"পরে ঈসা পাক-রূহের শক্তিতে পূর্ণ হয়ে গালীল প্রদেশে ফিরে গেলেন। ঈসার খবর সেই এলাকার সব জায়গায় ছড়িয়ে পড়ল।"},{"v":15,"ve":15,"vl":"15","bn":"সেখানকার ভিন্ন ভিন্ন মজলিস-খানায় ঈসা শিক্ষা দিতে শুরু করলেন। তখন সবাই তাঁর প্রশংসা করতে লাগল।"},{"v":16,"ve":16,"vl":"16","bn":"এর পরে ঈসা নাসরতে গেলেন। এখানেই তিনি বড় হয়েছিলেন। তিনি নিজের নিয়ম মত বিশ্রামবারে মজলিস-খানায় গেলেন, তারপর কিতাব তেলাওয়াত করবার জন্য উঠে দাঁড়ালেন।"},{"v":17,"ve":17,"vl":"17","bn":"তাঁর হাতে নবী ইশাইয়ার লেখা কিতাবখানা দেওয়া হল। গুটিয়ে-রাখা কিতাবখানা খুলেই তিনি সেই জায়গাটা পেলেন যেখানে লেখা আছে,"},{"v":18,"ve":18,"vl":"18","bn":"“আল্লাহ্‌ মালিকের রূহ্‌ আমার উপরে আছেন, কারণ তিনিই আমাকে নিযুক্ত করেছেন যেন আমি গরীবদের কাছে সুসংবাদ তবলিগ করি। তিনি আমাকে বন্দীদের কাছে স্বাধীনতার কথা, অন্ধদের কাছে দেখতে পাবার কথা ঘোষণা করতে পাঠিয়েছেন। যাদের উপর জুলুম হচ্ছে, তিনি আমাকে তাদের মুক্ত করতে পাঠিয়েছেন।"},{"v":19,"ve":19,"vl":"19","bn":"এছাড়া মাবুদ আমাকে ঘোষণা করতে পাঠিয়েছেন যে, এখন তাঁর রহমত দেখাবার সময় হয়েছে।”"},{"v":20,"ve":20,"vl":"20","bn":"তারপর তিনি কিতাবখানা আবার গুটিয়ে কর্মচারীর হাতে দিয়ে বসে পড়লেন। মজলিস-খানার প্রত্যেকটি লোকের চোখ তাঁর উপরে পড়ল।"},{"v":21,"ve":21,"vl":"21","bn":"তখন ঈসা লোকদের বললেন, “পাক-কিতাবের এই কথা আজ আপনারা শুনবার সংগে সংগেই তা পূর্ণ হল।”"},{"v":22,"ve":22,"vl":"22","bn":"লোকেরা সবাই তাঁর প্রশংসা করল এবং তাঁর মুখে এই সব সুন্দর সুন্দর কথা শুনে আশ্চর্য হল। তারা বলল, “এ কি ইউসুফের ছেলে নয়?”"},{"v":23,"ve":23,"vl":"23","bn":"ঈসা তাদের বললেন, “আপনারা এই চলতি কথাটা নিশ্চয়ই আমাকে বলবেন, ‘ডাক্তার, নিজেকে সুস্থ কর।’ আরও বলবেন, ‘কফরনাহূমে যে সব কাজ করবার কথা আমরা শুনেছি সেই সব এখন নিজের গ্রামেও করে দেখাও।’ ”"},{"v":24,"ve":24,"vl":"24","bn":"তিনি আরও বললেন, “আমি আপনাদের সত্যি বলছি, কোন নবীকেই তাঁর নিজের গ্রামের লোক গ্রাহ্য করে না।"},{"v":25,"ve":25,"vl":"25","bn":"এই কথা সত্যি যে, নবী ইলিয়াসের সময়ে যখন সাড়ে তিন বছর বৃষ্টি হয় নি এবং সমস্ত দেশে ভীষণ দুর্ভিক্ষ হয়েছিল তখন ইসরাইল দেশে অনেক বিধবা ছিল।"},{"v":26,"ve":26,"vl":"26","bn":"কিন্তু তাদের কারও কাছে ইলিয়াসকে পাঠানো হয় নি, কেবল সিডন এলাকার সারিফত গ্রামের বিধবা স্ত্রীলোকটির কাছে পাঠানো হয়েছিল।"},{"v":27,"ve":27,"vl":"27","bn":"নবী আল-ইয়াসার সময়ে ইসরাইল দেশে অনেক চর্মরোগী ছিল, কিন্তু তাদের কাউকে সুস্থ করা হয় নি, কেবল সিরিয়া দেশের নামানকেই সুস্থ করা হয়েছিল।”"},{"v":28,"ve":28,"vl":"28","bn":"এই কথা শুনে মজলিস-খানার সমস্ত লোক রেগে আগুন হল।"},{"v":29,"ve":29,"vl":"29","bn":"তারা উঠে ঈসাকে গ্রামের বাইরে তাড়িয়ে নিয়ে চলল, আর তাঁকে নীচে ফেলে দেবার জন্য তাদের গ্রামটা যে পাহাড়ের গায়ে ছিল সেই পাহাড়ের চূড়ায় তাঁকে নিয়ে গেল।"},{"v":30,"ve":30,"vl":"30","bn":"কিন্তু তিনি সেই লোকদের মধ্য দিয়েই চলে গেলেন।"},{"heading":"অনেকে সুস্থ হল","v":31,"ve":31,"vl":"31","bn":"পরে ঈসা গালীল প্রদেশের কফরনাহূম শহরে গেলেন এবং বিশ্রামবারে লোকদের শিক্ষা দিলেন।"},{"v":32,"ve":32,"vl":"32","bn":"তাঁর শিক্ষায় লোকেরা আশ্চর্য হল, কারণ তিনি এমন লোকের মত কথা বলছিলেন যাঁর অধিকার আছে।"},{"v":33,"ve":33,"vl":"33","bn":"সেই মজলিস-খানায় এমন একটি লোক ছিল যাকে ভূতে পেয়েছিল। সে চিৎকার করে বলল,"},{"v":34,"ve":34,"vl":"34","bn":"“ওহে নাসরত গ্রামের ঈসা, আমাদের সংগে আপনার কি দরকার? আপনি কি আমাদের ধ্বংস করতে এসেছেন? আমি জানি আপনি কে; আপনিই তো আল্লাহ্‌র সেই পবিত্রজন।”"},{"v":35,"ve":35,"vl":"35","bn":"ঈসা সেই ভূতকে ধমক দিয়ে বললেন, “চুপ কর, ওর মধ্য থেকে বের হয়ে যাও।” সেই ভূত তখন লোকটিকে সকলের মাঝখানে আছড়ে ফেলল এবং তার কোন ক্ষতি না করে তার মধ্য থেকে বের হয়ে গেল।"},{"v":36,"ve":36,"vl":"36","bn":"এতে সবাই আশ্চর্য হয়ে নিজেদের মধ্যে বলাবলি করতে লাগল, “এ কেমন কথা! অধিকার ও ক্ষমতা নিয়ে তিনি ভূতদের হুকুম দেন আর তারা বের হয়ে যায়!”"},{"v":37,"ve":37,"vl":"37","bn":"সেই এলাকার সব জায়গায় ঈসার কথা ছড়িয়ে পড়ল।"},{"v":38,"ve":38,"vl":"38","bn":"এর পরে ঈসা মজলিস-খানা ছেড়ে শিমোনের বাড়ীতে গেলেন। শিমোনের শাশুড়ীর খুব জ্বর হয়েছিল। তাঁকে ভাল করবার জন্য ঈসাকে অনুরোধ করা হল।"},{"v":39,"ve":39,"vl":"39","bn":"তখন ঈসা শিমোনের শাশুড়ীর পাশে দাঁড়িয়ে জ্বরকে ধমক দিলেন। তাতে তাঁর জ্বর ছেড়ে গেল, আর তিনি তখনই উঠে তাঁদের খাওয়া-দাওয়ার ব্যবস্থা করতে লাগলেন।"},{"v":40,"ve":40,"vl":"40","bn":"বেলা ডুবে যাবার সময়ে লোকেরা সব রোগীদের ঈসার কাছে নিয়ে আসল। তারা নানা রকম রোগে ভুগছিল। ঈসা তাদের প্রত্যেকের গায়ে হাত দিয়ে তাদের সুস্থ করলেন।"},{"v":41,"ve":41,"vl":"41","bn":"অনেক লোকের মধ্য থেকে ভূতও বের হয়ে গেল। সেই ভূতগুলো চিৎকার করে বলল, “আপনি ইব্‌নুল্লাহ্‌।” তিনি যে মসীহ্‌ তা তারা জানত। এইজন্য তিনি ধমক দিয়ে তাদের মুখ বন্ধ করে দিলেন।"},{"v":42,"ve":42,"vl":"42","bn":"খুব ভোরে ঈসা সেই জায়গা ছেড়ে একটা নির্জন জায়গায় চলে গেলেন। লোকেরা তাঁর তালাশ করতে করতে তাঁর কাছে গেল এবং যাতে তিনি তাদের কাছ থেকে চলে না যান সেইজন্য তাঁকে তাদের কাছে ধরে রাখতে চেষ্টা করল।"},{"v":43,"ve":43,"vl":"43","bn":"তখন ঈসা তাদের বললেন, “আরও অনেক জায়গায় আমাকে আল্লাহ্‌র রাজ্যের সুসংবাদ তবলিগ করতে হবে, কারণ এরই জন্য আল্লাহ্‌ আমাকে পাঠিয়েছেন।”"},{"v":44,"ve":44,"vl":"44","bn":"এর পরে তিনি ইহুদীদের দেশের ভিন্ন ভিন্ন মজলিস-খানায় তবলিগ করতে থাকলেন।"}],"5":[{"heading":"সাহাবী গ্রহণ","v":1,"ve":1,"vl":"1","bn":"এক সময়ে ঈসা গিনেষরৎ সাগরের পারে দাঁড়িয়ে ছিলেন। লোকেরা আল্লাহ্‌র কালাম শুনবার জন্য তাঁর চারপাশে ঠেলাঠেলি করছিল।"},{"v":2,"ve":2,"vl":"2","bn":"এমন সময় তিনি সাগরের পারে দু’টা নৌকা দেখতে পেলেন। জেলেরা সেই নৌকা দু’টা থেকে নেমে তাদের জাল ধুচ্ছিল।"},{"v":3,"ve":3,"vl":"3","bn":"তখন ঈসা শিমোনের নৌকায় উঠলেন এবং তাঁকে পার থেকে একটু দূরে নৌকাটা নিয়ে যেতে বললেন। তারপর তিনি নৌকায় বসে লোকদের শিক্ষা দিতে লাগলেন।"},{"v":4,"ve":4,"vl":"4","bn":"কথা শেষ হলে পর ঈসা শিমোনকে বললেন, “গভীর পানিতে গিয়ে মাছ ধরবার জন্য তোমাদের জাল ফেল।”"},{"v":5,"ve":5,"vl":"5","bn":"শিমোন বললেন, “হুজুর, সারা রাত খুব পরিশ্রম করেও কিছুই ধরতে পারি নি; তবুও আপনার কথাতে আমি জাল ফেলব।”"},{"v":6,"ve":6,"vl":"6","bn":"জাল ফেললে পর তাতে এত মাছ পড়ল যে, তাঁদের জাল ছিঁড়বার মত হল।"},{"v":7,"ve":7,"vl":"7","bn":"তখন তাঁরা সাহায্যের জন্য ইশারা করে অন্য নৌকার সংগীদের ডাকলেন। তাঁরা এসে দু’টা নৌকায় এত মাছ বোঝাই করলেন যে, সেগুলো ডুবে যাবার মত হল।"},{"v":8,"ve":8,"vl":"8","bn":"এ দেখে শিমোন্তপিতর ঈসার সামনে উবুড় হয়ে পড়ে বললেন, “হুজুর, আমি গুনাহ্‌গার; আমার কাছ থেকে চলে যান।”"},{"v":9,"ve":9,"vl":"9","bn":"এত মাছ ধরা পড়েছে দেখে শিমোন্তপিতর ও তাঁর সংগীরা সবাই আশ্চর্য হলেন।"},{"v":10,"ve":10,"vl":"10","bn":"শিমোনের ব্যবসার ভাগীদার ইয়াকুব ও ইউহোন্না নামে সিবদিয়ের দুই ছেলেও আশ্চর্য হলেন। তখন ঈসা শিমোনকে বললেন, “ভয় কোরো না; এখন থেকে তুমি আল্লাহ্‌র জন্য মানুষ ধরবে।”"},{"v":11,"ve":11,"vl":"11","bn":"তারপর তাঁরা নৌকাগুলো পারে আনলেন এবং সব কিছু ফেলে রেখে ঈসার সংগে চললেন।"},{"heading":"দু’জন রোগী সুস্থ হল","v":12,"ve":12,"vl":"12","bn":"ঈসা একবার একটা গ্রামে গেলেন। সেখানে একজন লোকের সারা গায়ে খারাপ চর্মরোগ ছিল। ঈসাকে দেখে সে উবুড় হয়ে পড়ে কাকুতি-মিনতি করে বলল, “হুজুর, আপনি ইচ্ছা করলেই আমাকে ভাল করতে পারেন।”"},{"v":13,"ve":13,"vl":"13","bn":"ঈসা হাত বাড়িয়ে তাকে ছুঁয়ে বললেন, “আমি তা-ই চাই, তুমি পাক-সাফ হও।” আর তখনই সে ভাল হয়ে গেল।"},{"v":14,"ve":14,"vl":"14","bn":"ঈসা তাকে এই হুকুম দিলেন, “এই কথা কাউকে বোলো না বরং ইমামের কাছে গিয়ে নিজেকে দেখাও। তার পর পাক-সাফ হওয়া সম্বন্ধে মূসা যা কোরবানী দেবার হুকুম দিয়েছেন তা কোরবানী দাও। তাতে লোকদের কাছে প্রমাণ হবে তুমি ভাল হয়েছ।”"},{"v":15,"ve":15,"vl":"15","bn":"তবুও ঈসার খবর আরও ছড়িয়ে পড়ল। তাঁর কথা শুনবার জন্য ও রোগ থেকে সুস্থ হবার জন্য অনেক লোক তাঁর কাছে আসতে লাগল।"},{"v":16,"ve":16,"vl":"16","bn":"ঈসা প্রায়ই নির্জন জায়গায় গিয়ে মুনাজাত করতেন।"},{"v":17,"ve":17,"vl":"17","bn":"একদিন ঈসা যখন শিক্ষা দিচ্ছিলেন তখন ফরীশীরা এবং আলেমেরা সেখানে বসে ছিলেন। গালীল প্রদেশের বিভিন্ন গ্রাম এবং এহুদিয়া প্রদেশ ও জেরুজালেম শহর থেকে এঁরা এসেছিলেন। রোগীদের সুস্থ করবার জন্য মাবুদের কুদরত ঈসার মধ্যে ছিল।"},{"v":18,"ve":18,"vl":"18","bn":"তখন কয়েকজন লোক একজন অবশ-রোগীকে খাটে করে বয়ে আনল। তারা তাকে ভিতরে নিয়ে গিয়ে ঈসার সামনে রাখবার চেষ্টা করল,"},{"v":19,"ve":19,"vl":"19","bn":"কিন্তু ভিড়ের জন্য ভিতরে যাবার পথ পেল না। তখন তারা ছাদে উঠল এবং ছাদের টালি সরিয়ে বিছানা সুদ্ধ তাকে লোকদের মাঝখানে ঈসার সামনে নামিয়ে দিল।"},{"v":20,"ve":20,"vl":"20","bn":"তারা ঈমান এনেছে দেখে ঈসা বললেন, “বন্ধু, তোমার গুনাহ্‌ মাফ করা হল।”"},{"v":21,"ve":21,"vl":"21","bn":"এতে আলেম ও ফরীশীরা মনে মনে ভাবতে লাগলেন, “এই লোকটা কে, যে কুফরী করছে? আল্লাহ্‌ ছাড়া আর কে গুনাহ্‌ মাফ করতে পারে?”"},{"v":22,"ve":22,"vl":"22","bn":"তাঁরা মনে মনে কি চিন্তা করছিলেন ঈসা তা বুঝতে পেরে বললেন, “আপনারা মনে মনে কেন ঐ কথা ভাবছেন?"},{"v":23,"ve":23,"vl":"23","bn":"কোন্‌টা বলা সহজ, ‘তোমার গুনাহ্‌ মাফ করা হল,’ না ‘তুমি উঠে হেঁটে বেড়াও’?"},{"v":24,"ve":24,"vl":"24","bn":"কিন্তু আপনারা যেন জানতে পারেন দুনিয়াতে গুনাহ্‌ মাফ করবার ক্ষমতা ইব্‌ন্তেআদমের আছে”- এই পর্যন্ত বলে তিনি সেই অবশ-রোগীকে বললেন, “আমি তোমাকে বলছি, ওঠো, তোমার বিছানা তুলে নিয়ে বাড়ী চলে যাও।”"},{"v":25,"ve":25,"vl":"25","bn":"সেই লোকটি তখনই সকলের সামনে উঠে দাঁড়াল এবং যে বিছানার উপরে সে শুয়ে ছিল তা তুলে নিয়ে আল্লাহ্‌র প্রশংসা করতে করতে বাড়ী চলে গেল।"},{"v":26,"ve":26,"vl":"26","bn":"তাতে সবাই খুব আশ্চর্য হল এবং ভয়ে আল্লাহ্‌র প্রশংসা করে বলল, “আজ আমরা কি আশ্চর্য ব্যাপার দেখলাম!”"},{"heading":"হযরত লেবির প্রতি হযরত ঈসা মসীহের ডাক","v":27,"ve":27,"vl":"27","bn":"এর পরে ঈসা বাইরে গেলেন এবং খাজনা আদায় করবার ঘরে লেবি নামে একজন খাজনা-আদায়কারীকে বসে থাকতে দেখলেন। ঈসা লেবিকে বললেন, “এস, আমার সাহাবী হও।”"},{"v":28,"ve":28,"vl":"28","bn":"তাতে লেবি উঠলেন এবং তাঁর সব কিছু ফেলে রেখে ঈসার সংগে গেলেন।"},{"v":29,"ve":29,"vl":"29","bn":"পরে লেবি ঈসার জন্য তাঁর বাড়ীতে একটা বড় মেজবানী দিলেন। তাঁদের সংগে অনেক খাজনা-আদায়কারী ও অন্য লোকেরা খেতে বসল।"},{"v":30,"ve":30,"vl":"30","bn":"তখন ফরীশীরা ও তাঁদের দলের আলেমেরা বিরক্ত হয়ে ঈসার সাহাবীদের বললেন, “তোমরা কর-আদায়কারী ও খারাপ লোকদের সংগে খাওয়া-দাওয়া কর কেন?”"},{"v":31,"ve":31,"vl":"31","bn":"ঈসা তাঁদের বললেন, “সুস্থদের জন্য ডাক্তারের দরকার নেই বরং অসুস্থদের জন্যই দরকার আছে।"},{"v":32,"ve":32,"vl":"32","bn":"তওবা করবার জন্য আমি ধার্মিকদের ডাকতে আসি নি বরং গুনাহ্‌গারদেরই ডাকতে এসেছি।”"},{"heading":"রোজার বিষয়ে শিক্ষা","v":33,"ve":33,"vl":"33","bn":"পরে সেই ধর্ম-নেতারা ঈসাকে বললেন, “ইয়াহিয়ার সাহাবীরা প্রায়ই রোজা ও মুনাজাত করে এবং ফরীশীদের শাগরেদেরাও তা করে, কিন্তু আপনার সাহাবীরা কখনও খাওয়া-দাওয়া বাদ দেয় না।”"},{"v":34,"ve":34,"vl":"34","bn":"ঈসা তাঁদের বললেন, “বর সংগে থাকতে কি বরের সংগের লোকদের রোজা রাখাতে পারা যায়?"},{"v":35,"ve":35,"vl":"35","bn":"কিন্তু এমন সময় আসবে যখন তাদের কাছ থেকে বরকে নিয়ে যাওয়া হবে, আর সেই সময়েই তারা রোজা রাখবে।”"},{"v":36,"ve":36,"vl":"36","bn":"তারপর ঈসা শিক্ষা দেবার জন্য তাঁদের কাছে এই উদাহরণ দিলেন: “নতুন কোর্তার টুকরা ছিঁড়ে নিয়ে কেউ পুরানো কোর্তায় তালি দেয় না, কারণ তা করলে সেই নতুন কোর্তাটা তো সে ছিঁড়ে ফেলে; আর সেই নতুন টুকরাটাও পুরানো কোর্তার সংগে মানায় না।"},{"v":37,"ve":37,"vl":"37","bn":"টাটকা আংগুর-রস কেউ পুরানো চামড়ার থলিতে রাখে না, রাখলে টাটকা রসে থলিগুলো ফেটে যায়। তাতে রসও পড়ে যায়, থলিগুলোও নষ্ট হয়।"},{"v":38,"ve":38,"vl":"38","bn":"টাটকা আংগুর-রস নতুন চামড়ার থলিতেই রাখা উচিত।"},{"v":39,"ve":39,"vl":"39","bn":"পুরানো আংগুর-রস খাবার পরে কেউ টাটকা আংগুর-রস খেতে চায় না, কারণ সে বলে, ‘পুরানোটাই ভাল।’ ”"}],"6":[{"heading":"বিশ্রামবার সম্বন্ধে শিক্ষা","v":1,"ve":1,"vl":"1","bn":"কোন এক বিশ্রামবারে ঈসা শস্যক্ষেতের মধ্য দিয়ে যাচ্ছিলেন। তাঁর সাহাবীরা শীষ ছিঁড়ে হাতে ঘষে ঘষে খেতে লাগলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তখন কয়েকজন ফরীশী বললেন, “শরীয়ত মতে বিশ্রামবারে যা করা উচিত নয়, তোমরা তা করছ কেন?”"},{"v":3,"ve":3,"vl":"3","bn":"ঈসা বললেন, “নবী দাউদ ও তাঁর সংগীদের যখন খিদে পেয়েছিল তখন তিনি কি করেছিলেন তা কি আপনারা পড়েন নি?"},{"v":4,"ve":4,"vl":"4","bn":"তিনি তো আল্লাহ্‌র ঘরে ঢুকে পবিত্র-রুটি নিয়ে খেয়েছিলেন এবং তাঁর সংগীদেরও দিয়েছিলেন। কিন্তু কেবল মাত্র ইমামেরা ছাড়া আর কারও তা খাবার নিয়ম ছিল না।”"},{"v":5,"ve":5,"vl":"5","bn":"শেষে ঈসা সেই ফরীশীদের বললেন, “ইব্‌ন্তেআদমই বিশ্রামবারের মালিক।”"},{"heading":"শুকনা-হাত লোকটি সুস্থ হল","v":6,"ve":6,"vl":"6","bn":"আর এক বিশ্রামবারে ঈসা মজলিস-খানায় গিয়ে শিক্ষা দিচ্ছিলেন। সেখানে এমন একজন লোক ছিল যার ডান হাত শুকিয়ে গিয়েছিল।"},{"v":7,"ve":7,"vl":"7","bn":"আলেমেরা ও ফরীশীরা ঈসাকে দোষ দেবার একটা অজুহাত খুঁজছিলেন। তাই বিশ্রামবারে তিনি কাউকে সুস্থ করেন কি না তা দেখবার জন্য তাঁরা ঈসার উপর ভালভাবে নজর রাখতে লাগলেন।"},{"v":8,"ve":8,"vl":"8","bn":"ঈসা কিন্তু তাঁদের মনের চিন্তা জানতেন। সেইজন্য যার হাত শুকিয়ে গিয়েছিল তিনি সেই লোকটিকে বললেন, “উঠে সকলের সামনে এসে দাঁড়াও।” তাতে সে উঠে দাঁড়াল।"},{"v":9,"ve":9,"vl":"9","bn":"ঈসা আলেম ও ফরীশীদের বললেন, “আমি আপনাদের একটা কথা জিজ্ঞাসা করি, বিশ্রামবারে ভাল কাজ করা উচিত, না খারাপ কাজ করা উচিত? প্রাণ রক্ষা করা উচিত, না নষ্ট করা উচিত?”"},{"v":10,"ve":10,"vl":"10","bn":"তারপর ঈসা চারপাশের সকলের দিকে তাকিয়ে লোকটিকে বললেন, “তোমার হাত বাড়িয়ে দাও।” সে তা করলে পর তার হাত একেবারে ভাল হয়ে গেল।"},{"v":11,"ve":11,"vl":"11","bn":"তখন সেই ধর্ম-নেতারা ভীষণ রাগ করলেন এবং ঈসাকে নিয়ে কি করা যায় তা নিজেদের মধ্যে আলোচনা করতে লাগলেন।"},{"heading":"বারোজন সাহাবীকে সাহাবী-পদ দান","v":12,"ve":12,"vl":"12","bn":"এর পরে ঈসা মুনাজাত করবার জন্য একটা পাহাড়ে গেলেন এবং সারা রাত আল্লাহ্‌র কাছে মুনাজাত করে কাটালেন।"},{"v":13,"ve":13,"vl":"13","bn":"সকাল হলে পর তিনি তাঁর সাহাবীদের নিজের কাছে ডাকলেন এবং তাঁদের মধ্য থেকে বারোজনকে বেছে নিয়ে তাঁদের সাহাবী-পদ দিলেন।"},{"v":14,"ve":14,"vl":"14","bn":"তাঁরা হলেন শিমোন, যাকে তিনি পিতর নামও দিলেন; শিমোনের ভাই আন্দ্রিয়; ইয়াকুব ও ইউহোন্না; ফিলিপ ও বর্থলময়;"},{"v":15,"ve":15,"vl":"15","bn":"মথি ও থোমা; আল্‌ফেয়ের ছেলে ইয়াকুব; শিমোন, যাঁকে মৌলবাদী বলা হয়;"},{"v":16,"ve":16,"vl":"16","bn":"ইয়াকুবের ছেলে এহুদা এবং এহুদা ইষ্কারিয়োৎ, যে ঈসাকে পরে শত্রুদের হাতে ধরিয়ে দিয়েছিল।"},{"v":17,"ve":17,"vl":"17","bn":"ঈসা তাঁর সাহাবীদের সংগে নিয়ে পাহাড় থেকে নেমে একটা সমান জায়গায় গিয়ে দাঁড়ালেন। সেখানে তাঁর অনেক উম্মত জড়ো হয়েছিলেন। এছাড়া এহুদিয়া, জেরুজালেম এবং টায়ার ও সিডন নামে সাগর পারের দু’টা শহরের এলাকা থেকেও অনেক লোক সেখানে ছিল।"},{"v":18,"ve":18,"vl":"18","bn":"তারা তাঁর কথা শুনবার জন্য এবং রোগ থেকে সুস্থ হবার জন্য সেখানে এসেছিল। যারা ভূতের দ্বারা কষ্ট পাচ্ছিল তারা ভাল হচ্ছিল।"},{"v":19,"ve":19,"vl":"19","bn":"তখন সব লোক তাঁকে ছোঁবার চেষ্টা করতে লাগল, কারণ তাঁর মধ্য থেকে শক্তি বের হয়ে সকলকে সুস্থ করছিল।"},{"heading":"হযরত ঈসা মসীহের শিক্ষা","v":20,"ve":20,"vl":"20","bn":"পরে ঈসা সাহাবীদের দিকে তাকিয়ে বলতে লাগলেন, “ধন্য তোমরা, যারা গরীব, কারণ আল্লাহ্‌র রাজ্য তোমাদেরই।"},{"v":21,"ve":21,"vl":"21","bn":"ধন্য তোমরা, যাদের এখন খিদে আছে, কারণ তোমরা তৃপ্ত হবে। ধন্য তোমরা, যারা এখন কাঁদছ, কারণ তোমরা হাসবে।"},{"v":22,"ve":22,"vl":"22","bn":"“ধন্য তোমরা, যখন ইব্‌ন্তেআদমের দরুন লোকে তোমাদের ঘৃণা করে, সমাজ থেকে বের করে দেয় ও নিন্দা করে এবং তোমাদের নাম শুনলে থুথু ফেলে।"},{"v":23,"ve":23,"vl":"23","bn":"সেই সময় তোমরা খুশী হয়ো ও আনন্দে নেচে উঠো, কারণ বেহেশতে তোমাদের জন্য মহা পুরস্কার আছে। ঐ সব লোকদের পূর্বপুরুষেরা নবীদের উপরও এই রকম করত।"},{"v":24,"ve":24,"vl":"24","bn":"“কিন্তু ঘৃণ্য ধনী লোকেরা! তোমরা পরিপূর্ণভাবেই সুখ ভোগ করছ।"},{"v":25,"ve":25,"vl":"25","bn":"ঘৃণ্য তৃপ্ত লোকেরা! তোমাদের তো খিদে পাবে। ঘৃণ্য যারা হাসছ! তোমরা দুঃখ করবে ও কাঁদবে।"},{"v":26,"ve":26,"vl":"26","bn":"ঘৃণ্য তোমরা, যখন সব লোকে তোমাদের প্রশংসা করে। এই সব লোকদের পূর্বপুরুষেরা ভণ্ড নবীদেরও প্রশংসা করত।"},{"v":27,"ve":27,"vl":"27","bn":"“তোমরা যারা শুনছ তাদের আমি বলছি, তোমাদের শত্রুদের মহব্বত কোরো। যারা তোমাদের ঘৃণা করে তাদের উপকার কোরো।"},{"v":28,"ve":28,"vl":"28","bn":"যারা তোমাদের অবনতি চায় তাদের উন্নতি চেয়ো। যারা তোমাদের সংগে খারাপ ব্যবহার করে তাদের জন্য মুনাজাত কোরো।"},{"v":29,"ve":29,"vl":"29","bn":"যে তোমার এক গালে চড় মারে তাকে অন্য গালেও মারতে দিয়ো। যে তোমার চাদর নিয়ে যায় তাকে কোর্তাও নিতে দিয়ো।"},{"v":30,"ve":30,"vl":"30","bn":"যারা তোমার কাছে চায় তাদের দিয়ো। কেউ তোমার কোন জিনিস নিয়ে গেলে তা আর ফেরৎ চেয়ো না।"},{"v":31,"ve":31,"vl":"31","bn":"লোকের কাছ থেকে তোমরা যেমন ব্যবহার পেতে চাও তোমরাও তাদের সংগে তেমনই ব্যবহার কোরো।"},{"v":32,"ve":32,"vl":"32","bn":"“যারা তোমাদের মহব্বত করে তোমরা যদি তাদেরই কেবল মহব্বত কর তবে তাতে প্রশংসার কি আছে? খারাপ লোকেরাও তো এইভাবে মহব্বত করে থাকে।"},{"v":33,"ve":33,"vl":"33","bn":"যারা তোমাদের উপকার করে তোমরা যদি তাদেরই উপকার করতে থাক তবে তাতে প্রশংসার কি আছে? খারাপ লোকেরাও তো তা করে থাকে।"},{"v":34,"ve":34,"vl":"34","bn":"যাদের কাছ থেকে তোমরা ফিরে পাবার আশা কর, যদি তাদেরই টাকা ধার দাও তবে তাতে প্রশংসার কি আছে? পাবে বলেই তো খারাপ লোকেরা খারাপ লোকদের ধার দিয়ে থাকে।"},{"v":35,"ve":35,"vl":"35","bn":"কিন্তু তোমরা তোমাদের শত্রুদের মহব্বত কোরো এবং তাদের উপকার কোরো। কিছুই ফেরৎ পাবার আশা না রেখে ধার দিয়ো। তাহলে তোমাদের জন্য মহা পুরস্কার আছে, আর তোমরা আল্লাহ্‌তা’লার সন্তান হবে, কারণ তিনি অকৃতজ্ঞ এবং দুষ্টদেরও দয়া করেন।"},{"v":36,"ve":36,"vl":"36","bn":"তোমাদের পিতা যেমন দয়ালু তোমরাও তেমনি দয়ালু হও।"},{"v":37,"ve":37,"vl":"37","bn":"“অন্যদের দোষ ধরে বেড়িয়ো না, তাতে তোমাদেরও দোষ ধরা হবে না। অন্যদের শাস্তি পাবার যোগ্য বলে মনে কোরো না, তাতে তোমাদেরও শাস্তি পাবার যোগ্য বলে মনে করা হবে না। অন্যদের মাফ কোরো, তাতে তোমাদেরও মাফ করা হবে।"},{"v":38,"ve":38,"vl":"38","bn":"দান কোরো, তাতে তোমাদেরও দেওয়া হবে; অনেক বেশী করে, চেপে চেপে, ঝাঁকিয়ে ঝাঁকিয়ে, উপ্‌চে পড়বার মত করে তোমাদের কোঁচড়ে দেওয়া হবে, কারণ যেভাবে তোমরা মেপে দাও সেইভাবে তোমাদের জন্য মাপা হবে।”"},{"v":39,"ve":39,"vl":"39","bn":"পরে ঈসা তাঁর সাহাবীদের শিক্ষা দেবার জন্য এই উদাহরণ দিলেন: “একজন অন্ধ কি অন্য আর একজন অন্ধকে পথ দেখাতে পারে? তা হলে কি তারা দু’জনেই গর্তে পড়বে না?"},{"v":40,"ve":40,"vl":"40","bn":"ছাত্র তার শিক্ষকের উপরে নয়, কিন্তু পরিপূর্ণ শিক্ষা পেয়ে প্রত্যেকটি ছাত্র তার শিক্ষকের মতই হয়ে ওঠে।"},{"v":41,"ve":41,"vl":"41","bn":"“তোমার ভাইয়ের চোখে যে কূটা আছে তা-ই কেবল দেখছ, অথচ তোমার নিজের চোখে যে কড়িকাঠ আছে তা লক্ষ্য করছ না কেন?"},{"v":42,"ve":42,"vl":"42","bn":"তোমার নিজের চোখে যে কড়িকাঠ আছে তা যখন লক্ষ্য করছ না তখন কেমন করে তোমার ভাইকে বলতে পার, ‘ভাই, তোমার চোখে যে কূটা আছে, এস, তা বের করে দিই’? ভণ্ড, প্রথমে তোমার নিজের চোখ থেকে কড়িকাঠটা বের করে ফেল, তাহলে তোমার ভাইয়ের চোখে যে কূটাটা আছে তা বের করবার জন্য স্পষ্ট দেখতে পাবে।"},{"v":43,"ve":43,"vl":"43","bn":"“ভাল গাছে খারাপ ফল ধরে না, আবার খারাপ গাছেও ভাল ফল ধরে না।"},{"v":44,"ve":44,"vl":"44","bn":"ফল দিয়েই গাছ চেনা যায়। লোকে কাঁটাঝোপ থেকে ডুমুর এবং কাঁটাগাছ থেকে আংগুর তোলে না।"},{"v":45,"ve":45,"vl":"45","bn":"ভাল লোক তার অন্তর-ভরা ভাল থেকে ভাল কথাই বের করে আনে, আর খারাপ লোক তার অন্তর-ভরা খারাপী থেকে খারাপ কথা বের করে আনে। মানুষের অন্তর যা দিয়ে পূর্ণ থাকে মুখ তো সেই কথাই বলে।"},{"v":46,"ve":46,"vl":"46","bn":"“তোমরা কেন আমাকে ‘প্রভু, প্রভু’ বলে ডাক, অথচ আমি যা বলি তা কর না?"},{"v":47,"ve":47,"vl":"47","bn":"যে কেউ আমার কাছে এসে আমার কথা শোনে এবং সেইমত কাজ করে সে কার মত আমি তা তোমাদের বলি।"},{"v":48,"ve":48,"vl":"48","bn":"সে এমন একজন লোকের মত, যে ঘর তৈরী করবার জন্য গভীর করে মাটি কেটে পাথরের উপর ভিত্তি গাঁথল। পরে বন্যা আসল এবং নদীর পানির স্রোত সেই ঘরের উপর এসে পড়ল, কিন্তু ঘরটা নাড়াতে পারল না, কারণ সেটা শক্ত করেই তৈরী করা হয়েছিল।"},{"v":49,"ve":49,"vl":"49","bn":"যে আমার কথা শোনে অথচ সেইমত কাজ না করে সে এমন একজন লোকের মত, যে মাটির উপর ভিত্তি ছাড়াই ঘর তৈরী করল। পরে নদীর পানির স্রোত যখন সেই ঘরের উপর এসে পড়ল তখনই সেই ঘরটা পড়ে একেবারে ধ্বংস হয়ে গেল।”"}],"7":[{"heading":"সেনাপতির গোলাম সুস্থ হল","v":1,"ve":1,"vl":"1","bn":"ঈসা লোকদের কাছে এই সব কথা বলা শেষ করে কফরনাহূম শহরে গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"সেখানে একজন রোমীয় শত-সেনাপতির গোলাম অসুস্থ হয়ে মরবার মত হয়েছিল। এই গোলামকে সেই সেনাপতি খুব ভালবাসতেন।"},{"v":3,"ve":3,"vl":"3","bn":"তিনি ঈসার বিষয় শুনে ইহুদীদের কয়েকজন বৃদ্ধনেতাকে ঈসার কাছে অনুরোধ করতে পাঠালেন যেন তিনি এসে তাঁর গোলামকে সুস্থ করেন।"},{"v":4,"ve":4,"vl":"4","bn":"সেই নেতারা ঈসার কাছে এসে তাঁকে বিশেষভাবে অনুরোধ করে বললেন, “আপনি যাঁর জন্য এই কাজ করবেন তিনি এর উপযুক্ত,"},{"v":5,"ve":5,"vl":"5","bn":"কারণ তিনি আমাদের লোকদের ভালবাসেন এবং আমাদের মজলিস-খানা তিনিই তৈরী করিয়ে দিয়েছেন।”"},{"v":6,"ve":6,"vl":"6","bn":"তখন ঈসা তাঁদের সংগে চললেন। তিনি সেই বাড়ীর কাছে আসলে পর সেই সেনাপতি তাঁর বন্ধুদের দিয়ে বলে পাঠালেন, “হুজুর, আর কষ্ট করবেন না, কারণ আপনি যে আমার বাড়ীতে ঢোকেন তার যোগ্য আমি নই।"},{"v":7,"ve":7,"vl":"7","bn":"সেইজন্য আপনার কাছে যাবার উপযুক্তও আমি নিজেকে মনে করি নি। আপনি কেবল মুখে বলুন, তাতেই আমার গোলাম ভাল হয়ে যাবে।"},{"v":8,"ve":8,"vl":"8","bn":"আমি এই কথা জানি, কারণ আমাকেও অন্যের কথামত চলতে হয় এবং সৈন্যেরাও আমার কথামত চলে। আমি একজনকে ‘যাও’ বললে সে যায়, অন্যজনকে ‘এস’ বললে সে আসে, আর আমার গোলামকে ‘এটা কর’ বললে সে তা করে।”"},{"v":9,"ve":9,"vl":"9","bn":"এই কথা শুনে ঈসা আশ্চর্য হলেন এবং যে সব লোকেরা ভিড় করে তাঁর পিছনে আসছিল তাদের দিকে ফিরে তিনি বললেন, “আমি আপনাদের বলছি, বনি-ইসরাইলদের মধ্যেও এত বড় বিশ্বাস আমি কখনও দেখি নি।”"},{"v":10,"ve":10,"vl":"10","bn":"সেনাপতি যাদের পাঠিয়েছিলেন তারা তাঁর ঘরে ফিরে গিয়ে সেই গোলামকে সুস্থ দেখতে পেল।"},{"heading":"বিধবার ছেলেকে জীবন দান","v":11,"ve":11,"vl":"11","bn":"এর কিছু পরে ঈসা নায়িন্‌ নামে একটা গ্রামের দিকে চললেন। তাঁর সাহাবীরা এবং আরও অনেক লোক তাঁর সংগে সংগে যাচ্ছিলেন।"},{"v":12,"ve":12,"vl":"12","bn":"যখন তিনি সেই গ্রামের দরজার কাছে পৌঁছালেন তখন লোকেরা একজন মৃত লোককে বাইরে নিয়ে যাচ্ছিল। যে লোকটি মারা গিয়েছিল সে ছিল তার মায়ের একমাত্র সন্তান, আর সেই মা-ও ছিল বিধবা। গ্রামের অনেক লোক সেই বিধবার সংগে ছিল।"},{"v":13,"ve":13,"vl":"13","bn":"সেই বিধবাকে দেখে ঈসা মমতায় পূর্ণ হয়ে বললেন, “আর কেঁদো না।”"},{"v":14,"ve":14,"vl":"14","bn":"তারপর তিনি কাছে গিয়ে খাট ছুঁলেন। এতে যারা লাশ বয়ে নিয়ে যাচ্ছিল তারা দাঁড়াল। ঈসা বললেন, “যুবক, আমি তোমাকে বলছি, ওঠো।”"},{"v":15,"ve":15,"vl":"15","bn":"তাতে যে মারা গিয়েছিল সেই লোকটি উঠে বসল এবং কথা বলতে লাগল। ঈসা তাকে তার মায়ের কাছে ফিরিয়ে দিলেন।"},{"v":16,"ve":16,"vl":"16","bn":"এতে সকলের দিল ভয়ে পূর্ণ হল। তারা আল্লাহ্‌র প্রশংসা করে বলতে লাগল, “আমাদের মধ্যে একজন মহান নবী উপস্থিত হয়েছেন। আল্লাহ্‌ রহমত করে তাঁর বান্দাদের দিকে মনোযোগ দিয়েছেন।”"},{"v":17,"ve":17,"vl":"17","bn":"ঈসার বিষয়ে এই কথা এহুদিয়া প্রদেশ ও তার আশেপাশের সব জায়গায় ছড়িয়ে গেল।"},{"heading":"হযরত ঈসা মসীহের কাছে হযরত ইয়াহিয়ার সাহাবীরা","v":18,"ve":19,"vl":"18-19","bn":"নবী ইয়াহিয়ার সাহাবীরা এই সব ঘটনার কথা ইয়াহিয়াকে জানাল। তখন ইয়াহিয়া তাঁর দু’জন সাহাবীকে ডেকে ঈসার কাছে এই কথা জিজ্ঞাসা করে পাঠালেন, “যাঁর আসবার কথা আছে আপনিই কি তিনি, না আমরা অন্য কারও জন্য অপেক্ষা করব?”"},{"v":20,"ve":20,"vl":"20","bn":"সেই লোকেরা ঈসার কাছে এসে বলল, “তরিকাবন্দীদাতা ইয়াহিয়া আপনার কাছে আমাদের জিজ্ঞাসা করতে পাঠিয়েছেন, ‘যাঁর আসবার কথা আছে আপনিই কি তিনি, না আমরা অন্য কারও জন্য অপেক্ষা করব?”"},{"v":21,"ve":21,"vl":"21","bn":"তখন ঈসা অনেক লোককে রোগ থেকে ও ভীষণ যন্ত্রণা থেকে সুস্থ করলেন এবং ভূতে পাওয়া লোকদের ভাল করলেন আর অনেক অন্ধ লোককেও দেখবার শক্তি দিলেন।"},{"v":22,"ve":22,"vl":"22","bn":"এই সব করবার পরে ঈসা ইয়াহিয়ার সাহাবীদের প্রশ্নের জবাবে বললেন, “তোমরা যা দেখলে ও শুনলে তা গিয়ে ইয়াহিয়াকে বল। তাঁকে জানাও যে, অন্ধেরা দেখছে, খোঁড়ারা হাঁটছে, চর্মরোগীরা পাক-সাফ হচ্ছে, বধির লোকেরা শুনছে, মৃতেরা বেঁচে উঠছে এবং গরীবদের কাছে সুসংবাদ তবলিগ করা হচ্ছে।"},{"v":23,"ve":23,"vl":"23","bn":"আর ধন্য সে-ই, যে আমাকে নিয়ে মনে কোন বাধা না পায়।”"},{"v":24,"ve":24,"vl":"24","bn":"ইয়াহিয়া যাদের পাঠিয়েছিলেন সেই লোকেরা চলে গেলে পর ঈসা লোকদের কাছে ইয়াহিয়ার বিষয়ে বলতে লাগলেন, “আপনারা মরুভূমিতে কি দেখতে গিয়েছিলেন? বাতাসে দোলা নল-খাগড়া?"},{"v":25,"ve":25,"vl":"25","bn":"তা না হলে কি দেখতে গিয়েছিলেন? সুন্দর কাপড় পরা একজন লোককে কি? যারা দামী দামী কাপড় পরে ও জাঁকজমকের সংগে বাস করে তারা তো রাজবাড়ীতে থাকে।"},{"v":26,"ve":26,"vl":"26","bn":"তা না হলে কি দেখতে গিয়েছিলেন? কোন নবীকে কি? জ্বী, আমি আপনাদের বলছি, তিনি নবীর চেয়েও বড়।"},{"v":27,"ve":27,"vl":"27","bn":"ইয়াহিয়াই সেই লোক যাঁর বিষয়ে পাক-কিতাবে লেখা আছে, ‘দেখ, আমি তোমার আগে আমার সংবাদদাতাকে পাঠাচ্ছি। সে তোমার আগে গিয়ে তোমার পথ প্রস্তুত করবে।’"},{"v":28,"ve":28,"vl":"28","bn":"আমি আপনাদের বলছি, মানুষের মধ্যে কেউই ইয়াহিয়ার চেয়ে বড় নয়; তবুও আল্লাহ্‌র রাজ্যের মধ্যে সবচেয়ে যে ছোট সেও ইয়াহিয়ার চেয়ে মহান।”"},{"v":29,"ve":29,"vl":"29","bn":"(সমস্ত সাধারণ লোকেরা ও খাজনা-আদায়কারীরা ইয়াহিয়ার তবলিগ শুনেছিল এবং তাঁর কাছে তরিকাবন্দী গ্রহণ করে আল্লাহ্‌কে ন্যায়বান বলে স্বীকার করে নিয়েছিল।"},{"v":30,"ve":30,"vl":"30","bn":"কিন্তু ফরীশীরা ও আলেমেরা ইয়াহিয়ার কাছে তরিকাবন্দী গ্রহণ করেন নি বলে নিজেদের জন্য আল্লাহ্‌র উদ্দেশ্যকে তাঁরা অগ্রাহ্য করেছিলেন)।"},{"v":31,"ve":31,"vl":"31","bn":"ঈসা আরও বললেন, “তা হলে এই কালের লোকদের আমি কাদের সংগে তুলনা করব? তারা কি রকম?"},{"v":32,"ve":32,"vl":"32","bn":"তারা এমন ছেলেমেয়েদের মত যারা বাজারে বসে একে অন্যকে ডেকে বলে, ‘আমরা তোমাদের জন্য বাঁশী বাজালাম কিন্তু তোমরা নাচলে না; আমরা বিলাপের গান গাইলাম কিন্তু তোমরা কাঁদলে না।’"},{"v":33,"ve":33,"vl":"33","bn":"তরিকাবন্দীদাতা ইয়াহিয়া এসে রুটি বা আংগুর-রস খেলেন না বলে আপনারা বলছেন, ‘তাকে ভূতে পেয়েছে।’"},{"v":34,"ve":34,"vl":"34","bn":"আর ইব্‌ন্তেআদম এসে খাওয়া-দাওয়া করলেন বলে আপনারা বলছেন, ‘দেখ, এই লোকটা পেটুক ও মদখোর, খাজনা-আদায়কারী ও খারাপ লোকদের বন্ধু।’"},{"v":35,"ve":35,"vl":"35","bn":"কিন্তু জ্ঞানের অধীনে যারা চলে তাদের জীবনই প্রমাণ করে যে, জ্ঞান খাঁটি।"},{"heading":"ফরীশী শিমোনের বাড়ীতে হযরত ঈসা মসীহ্‌","v":36,"ve":36,"vl":"36","bn":"একজন ফরীশী ঈসাকে তাঁর সংগে খাবার দাওয়াত করলেন। তখন ঈসা তাঁর বাড়ীতে গিয়ে ভোজে যোগ দিলেন।"},{"v":37,"ve":37,"vl":"37","bn":"সেই গ্রামে একজন খারাপ স্ত্রীলোক ছিল। সেই ফরীশীর ঘরে ঈসা ভোজে যোগ দিয়েছেন জানতে পেরে সে একটা সাদা পাথরের পাত্রে করে আতর নিয়ে আসল।"},{"v":38,"ve":38,"vl":"38","bn":"পরে সে ঈসার পিছনে তাঁর পায়ের কাছে গিয়ে দাঁড়াল এবং কেঁদে কেঁদে চোখের পানিতে তাঁর পা ভিজাতে লাগল। তারপর সে তার মাথার চুল দিয়ে তাঁর পা মুছিয়ে দিল এবং তাঁর পায়ের উপর চুমু দিয়ে সেই আতর ঢেলে দিল।"},{"v":39,"ve":39,"vl":"39","bn":"যে ফরীশী ঈসাকে দাওয়াত করেছিলেন তিনি এ দেখে মনে মনে বলতে লাগলেন, “যদি এই লোকটা নবী হত তবে জানতে পারত, কে এবং কি রকম স্ত্রীলোক তার পা ছুঁচ্ছে; স্ত্রীলোকটা তো খারাপ।”"},{"v":40,"ve":40,"vl":"40","bn":"ঈসা সেই ফরীশীকে বললেন, “শিমোন, তোমাকে আমার কিছু বলবার আছে।” শিমোন বললেন, “হুজুর, বলুন।”"},{"v":41,"ve":41,"vl":"41","bn":"ঈসা বললেন, “কোন এক মহাজনের কাছে দু’জন লোক টাকা ধারত। একজন ধারত পাঁচশো দীনার আর অন্যজন পঞ্চাশ দীনার।"},{"v":42,"ve":42,"vl":"42","bn":"তাদের কারও ঋণ শোধ দেবার ক্ষমতা ছিল না বলে তিনি দয়া করে দু’জনকেই মাফ করলেন। তা হলে বল দেখি, তাদের দু’জনের মধ্যে কে সেই মহাজনকে বেশী ভালবাসবে?”"},{"v":43,"ve":43,"vl":"43","bn":"শিমোন বললেন, “আমার মনে হয়, যার বেশী ঋণ মাফ করা হল সে-ই।” ঈসা তাঁকে বললেন, “তুমি ঠিক বলেছ।”"},{"v":44,"ve":44,"vl":"44","bn":"তারপর ঈসা সেই স্ত্রীলোকটির দিকে মুখ ফিরিয়ে শিমোনকে বললেন, “তুমি এই স্ত্রীলোকটিকে তো দেখছ। আমি তোমার ঘরে আসলে পর তুমি আমার পা ধোবার পানি দাও নি, কিন্তু সে চোখের পানিতে আমার পা ভিজিয়ে তার চুল দিয়ে মুছিয়ে দিয়েছে।"},{"v":45,"ve":45,"vl":"45","bn":"তুমি আমাকে চুমু দাও নি, কিন্তু আমি ঘরে আসবার পর থেকেই সে আমার পায়ে চুমু দিচ্ছে।"},{"v":46,"ve":46,"vl":"46","bn":"তুমি আমার মাথায় তেল দাও নি, কিন্তু সে আমার পায়ের উপর আতর ঢেলে দিয়েছে।"},{"v":47,"ve":47,"vl":"47","bn":"তাই আমি তোমাকে বলছি, সে বেশী ভালবাসা দেখিয়েছে বলে বুঝা যাচ্ছে যে, তার গুনাহ্‌ অনেক হলেও তা মাফ করা হয়েছে। যার অল্প মাফ করা হয় সে অল্পই ভালবাসা দেখায়।”"},{"v":48,"ve":48,"vl":"48","bn":"পরে ঈসা সেই স্ত্রীলোকটিকে বললেন, “তোমার গুনাহ্‌ মাফ করা হয়েছে।”"},{"v":49,"ve":49,"vl":"49","bn":"যারা ঈসার সংগে খেতে বসেছিল তারা মনে মনে বলতে লাগল, “এ কে, যে গুনাহ্‌ও মাফ করে?”"},{"v":50,"ve":50,"vl":"50","bn":"ঈসা তখন সেই স্ত্রীলোকটিকে বললেন, “তুমি ঈমান এনেছ বলে নাজাত পেয়েছ। শান্তিতে চলে যাও।”"}],"8":[{"v":1,"ve":2,"vl":"1-2","bn":"এর পরে ঈসা গ্রামে গ্রামে ও শহরে শহরে ঘুরে আল্লাহ্‌র রাজ্যের সুসংবাদ তবলিগ করতে লাগলেন। তাঁর সংগে তাঁর বারোজন সাহাবী এবং কয়েকজন স্ত্রীলোকও ছিলেন। এই স্ত্রীলোকেরা ভূতের হাত থেকে রেহাই পেয়েছিলেন ও রোগ থেকে সুস্থ হয়েছিলেন। এঁরা হলেন মরিয়ম, যাঁকে মগ্‌দলীনী বলা হত ও যাঁর মধ্য থেকে সাতটা ভূত বের হয়ে গিয়েছিল;"},{"v":3,"ve":3,"vl":"3","bn":"বাদশাহ্‌ হেরোদের কর্মচারী কূষের স্ত্রী যোহানা; শোশন্না এবং আরও অনেক স্ত্রীলোক। ঈসা ও তাঁর সাহাবীদের সেবা-যত্নের জন্য এঁরা সবাই নিজের টাকা-পয়সা থেকে খরচ করতেন।"},{"heading":"একজন চাষীর গল্প","v":4,"ve":4,"vl":"4","bn":"সেই সময় ভিন্ন ভিন্ন গ্রাম থেকে অনেক লোক ঈসার কাছে এসে ভিড় করল। তখন তিনি তাদের শিক্ষা দেবার জন্য এই গল্পটা বললেন:"},{"v":5,"ve":5,"vl":"5","bn":"“একজন চাষী বীজ বুনতে গেল। বীজ বুনবার সময় কতগুলো বীজ পথের পাশে পড়ল। লোকেরা সেগুলো পায়ে মাড়াল এবং পাখীরা এসে খেয়ে ফেলল।"},{"v":6,"ve":6,"vl":"6","bn":"কতগুলো বীজ পাথুরে জমিতে পড়ে গজিয়ে উঠল, কিন্তু রস না পেয়ে শুকিয়ে গেল।"},{"v":7,"ve":7,"vl":"7","bn":"আবার কতগুলো বীজ কাঁটাবনের মধ্যে পড়ল। পরে কাঁটাগাছ সেই চারাগুলোর সংগে বেড়ে উঠে সেগুলো চেপে রাখল।"},{"v":8,"ve":8,"vl":"8","bn":"আবার কতগুলো বীজ ভাল জমিতে পড়ল এবং বেড়ে উঠে একশো গুণ ফসল দিল।” এই কথা বলবার পরে ঈসা জোরে বললেন, “যার শুনবার কান আছে সে শুনুক।”"},{"v":9,"ve":9,"vl":"9","bn":"এর পরে তাঁর সাহাবীরা তাঁকে সেই গল্পের অর্থ জিজ্ঞাসা করলেন।"},{"v":10,"ve":10,"vl":"10","bn":"তখন ঈসা বললেন, “আল্লাহ্‌র রাজ্যের গোপন সত্যগুলো তোমাদেরই জানতে দেওয়া হয়েছে, কিন্তু অন্যদের কাছে আমি তা গল্পের মধ্য দিয়ে বলি, যেন তারা দেখেও না দেখে আর শুনেও না বোঝে।"},{"v":11,"ve":11,"vl":"11","bn":"“গল্পটার মানে এই: বীজ হল আল্লাহ্‌র কালাম।"},{"v":12,"ve":12,"vl":"12","bn":"পথের পাশে পড়া বীজের মধ্য দিয়ে তাদের সম্বন্ধেই বলা হয়েছে যারা সেই কালাম শোনে বটে, কিন্তু পরে ইবলিস এসে তাদের দিল থেকে তা তুলে নিয়ে যায়। তাতে তারা তার উপর ঈমান আনতে পারে না বলে নাজাত পায় না।"},{"v":13,"ve":13,"vl":"13","bn":"পাথুরে জমিতে পড়া বীজের মধ্য দিয়ে তাদের সম্বন্ধেই বলা হয়েছে যারা সেই কালাম শুনে আনন্দের সংগে গ্রহণ করে, কিন্তু তাদের মধ্যে তার শিকড় ভাল করে বসে না। তাই তারা অল্প দিনের জন্য ঈমান রাখে, কিন্তু যখন পরীক্ষা আসে তখন পিছিয়ে যায়।"},{"v":14,"ve":14,"vl":"14","bn":"কাঁটাবনের মধ্যে পড়া বীজের মধ্য দিয়ে তাদের সম্বন্ধেই বলা হয়েছে যারা তা শোনে, কিন্তু জীবন্তপথে চলতে চলতে সংসারের চিন্তা-ভাবনা, ধন-সম্পত্তি এবং সুখভোগের মধ্যে তারা চাপা পড়ে যায়। তাতে তাদের জীবনে কোন পাকা ফল দেখা দেয় না।"},{"v":15,"ve":15,"vl":"15","bn":"ভাল জমিতে পড়া বীজের মধ্য দিয়ে তাদের সম্বন্ধেই বলা হয়েছে যারা সৎ ও সরল মনে সেই কালাম শুনে শক্ত করে ধরে রাখে এবং তাতে স্থির থেকে জীবনে পাকা ফল দেখায়।"},{"v":16,"ve":16,"vl":"16","bn":"“কেউ বাতি জ্বালিয়ে কোন পাত্র দিয়ে তা ঢেকে রাখে না বা খাটের নীচে রাখে না। সে তা বাতিদানের উপরেই রাখে যেন ভিতরে যারা আসে তারা আলো দেখতে পায়।"},{"v":17,"ve":17,"vl":"17","bn":"এমন কিছু লুকানো নেই যা প্রকাশিত হবে না, বা এমন কিছু গোপন নেই যা জানা যাবে না কিংবা প্রকাশ পাবে না।"},{"v":18,"ve":18,"vl":"18","bn":"এইজন্য কিভাবে শুনছ সেই বিষয়ে মনোযোগ দাও, কারণ যার আছে তাকে আরও দেওয়া হবে, কিন্তু যার নেই তার যা আছে বলে সে মনে করে, তাও তার কাছে থেকে নিয়ে নেওয়া হবে।”"},{"v":19,"ve":19,"vl":"19","bn":"পরে ঈসার মা ও ভাইয়েরা তাঁর কাছে আসলেন কিন্তু ভিড়ের জন্য তাঁর সংগে দেখা করতে পারলেন না।"},{"v":20,"ve":20,"vl":"20","bn":"তখন একজন লোক তাঁকে বলল, “আপনার মা ও ভাইয়েরা আপনার সংগে দেখা করবার জন্য বাইরে দাঁড়িয়ে আছেন।”"},{"v":21,"ve":21,"vl":"21","bn":"এতে ঈসা লোকদের বললেন, “যারা আল্লাহ্‌র কালাম শুনে সেইমত কাজ করে তারাই আমার মা ও আমার ভাই।”"},{"heading":"ঝড় থামানো","v":22,"ve":22,"vl":"22","bn":"একদিন ঈসা ও তাঁর সাহাবীরা একটা নৌকায় উঠলেন। তিনি সাহাবীদের বললেন, “চল, আমরা সাগরের ওপারে যাই।” সাহাবীরা নৌকা ছাড়লেন।"},{"v":23,"ve":23,"vl":"23","bn":"নৌকা চলতে থাকলে ঈসা ঘুমিয়ে পড়লেন। সেই সময় হঠাৎ সাগরে ঝড় উঠল এবং নৌকাটা পানিতে পূর্ণ হতে লাগল। এতে তাঁরা খুব বিপদে পড়লেন।"},{"v":24,"ve":24,"vl":"24","bn":"তাঁরা ঈসার কাছে গিয়ে তাঁকে জাগিয়ে বললেন, “হুজুর, হুজুর, আমরা যে মরলাম!” তখন ঈসা উঠে বাতাস ও পানির ঢেউকে ধমক্‌ দিলেন। তাতে বাতাস আর ঢেউ থামল এবং সব কিছু শান্ত হয়ে গেল।"},{"v":25,"ve":25,"vl":"25","bn":"তিনি সাহাবীদের বললেন, “তোমাদের ঈমান কোথায়?” সাহাবীরা ভয়ে আশ্চর্য হয়ে নিজেদের মধ্যে বলাবলি করতে লাগলেন, “ইনি কে, যিনি বাতাস ও পানিকে হুকুম দিলে পর তারাও তাঁর কথা শোনে?”"},{"heading":"ভূতে পাওয়া লোকটি সুস্থ হল","v":26,"ve":26,"vl":"26","bn":"এর পরে ঈসা ও তাঁর সাহাবীরা সাগর পার হয়ে গালীল প্রদেশের উল্টা দিকে গাদারীয়দের এলাকায় গেলেন।"},{"v":27,"ve":27,"vl":"27","bn":"তিনি যখন নৌকা থেকে নামলেন তখন সেখানকার গ্রামের একজন লোক তাঁর কাছে আসল। সেই লোকটিকে অনেকগুলো ভূতে পেয়েছিল বলে সে অনেক দিন ধরে কাপড়-চোপড় পরত না এবং বাড়ীতে না থেকে কবরস্থানে থাকত।"},{"v":28,"ve":28,"vl":"28","bn":"ঈসাকে দেখে সে চিৎকার করে উঠল এবং তাঁর সামনে মাটিতে পড়ে জোরে জোরে বলল, “আল্লাহ্‌তা’লার পুত্র ঈসা, আমার সংগে আপনার কি সম্বন্ধ? দয়া করে আপনি আমাকে যন্ত্রণা দেবেন না।”"},{"v":29,"ve":29,"vl":"29","bn":"লোকটি এই কথা বলল কারণ ঈসা সেই ভূতকে তার মধ্য থেকে বের হয়ে যেতে হুকুম দিয়েছিলেন। সেই ভূত বার বার লোকটিকে আঁকড়ে ধরত। যদিও তখন তার হাত-পা শিকল দিয়ে বাঁধা থাকত এবং তাকে পাহারা দেওয়া হত তবুও সে সেই শিকল ছিঁড়ে ফেলত, আর সেই ভূত তাকে নির্জন জায়গায় তাড়িয়ে নিয়ে যেত।"},{"v":30,"ve":30,"vl":"30","bn":"ঈসা তাঁকে জিজ্ঞাসা করলেন, “তোমার নাম কি?” সে বলল, “বাহিনী,” কারণ অনেকগুলো ভূত তার ভিতরে ঢুকেছিল।"},{"v":31,"ve":31,"vl":"31","bn":"তখন সেই ভূতগুলো ঈসাকে কাকুতি-মিনতি করতে লাগল যেন তিনি তাদের হাবিয়া-দোজখে না পাঠান।"},{"v":32,"ve":33,"vl":"32-33","bn":"সেখানে পাহাড়ের ধারে খুব বড় এক পাল শূকর চরছিল। ভূতগুলো ঈসাকে অনুরোধ করল যেন তিনি সেই শূকরগুলোর ভিতরে ঢুকতে তাদের অনুমতি দেন। তিনি অনুমতি দিলে পর তারা লোকটির মধ্য থেকে বের হয়ে শূকরগুলোর ভিতরে ঢুকল। তাতে সেই শূকরের পাল সাগরের ঢালু পার দিয়ে জোরে দৌড়ে গিয়ে পানিতে ডুবে মরল।"},{"v":34,"ve":34,"vl":"34","bn":"যারা শূকর চরাচ্ছিল তারা এই ঘটনা দেখে দৌড়ে গিয়ে সেই গ্রামে ও তার আশেপাশের সব জায়গায় এই খবর দিল।"},{"v":35,"ve":35,"vl":"35","bn":"কি হয়েছে তা দেখবার জন্য তখন লোকেরা বের হয়ে আসল। ঈসার কাছে এসে তারা দেখল, যার মধ্য থেকে ভূতগুলো বের হয়ে গেছে সে কাপড়-চোপড় পরে সুস্থ মনে ঈসার পায়ের কাছে বসে আছে। এ দেখে তারা ভয় পেল।"},{"v":36,"ve":36,"vl":"36","bn":"যারা সেই ঘটনা দেখেছিল তারা ঐ লোকদের কাছে বলল কেমন করে লোকটা সুস্থ হয়েছে।"},{"v":37,"ve":37,"vl":"37","bn":"তখন গাদারীয়দের এলাকার সমস্ত লোক ঈসাকে তাদের কাছ থেকে চলে যেতে অনুরোধ করল, কারণ তারা ভীষণ ভয় পেয়েছিল। তখন ঈসা ফিরে যাবার জন্য নৌকায় উঠলেন।"},{"v":38,"ve":38,"vl":"38","bn":"যে লোকটির মধ্য থেকে ভূতগুলো বের হয়ে গিয়েছিল সেই লোকটি ঈসাকে অনুরোধ করল যেন সে তাঁর সংগে যেতে পারে। ঈসা কিন্তু তাকে এই কথা বলে বাড়ী পাঠিয়ে দিলেন,"},{"v":39,"ve":39,"vl":"39","bn":"“তুমি বাড়ী ফিরে যাও এবং আল্লাহ্‌ তোমার জন্য কত বড় কাজ করেছেন তা প্রচার কর।” সেই লোকটি তখন গ্রামে গেল এবং ঈসা তার জন্য কত বড় কাজ করেছেন তা সমস্ত জায়গায় বলে বেড়াতে লাগল।"},{"heading":"একটি মৃত বালিকা ও একজন অসুস্থ স্ত্রীলোক","v":40,"ve":40,"vl":"40","bn":"ঈসা অন্য পারে ফিরে যাবার পর সেখানকার লোকেরা তাঁকে খুশী মনে গ্রহণ করল, কারণ তারা তাঁর জন্য অপেক্ষা করছিল।"},{"v":41,"ve":41,"vl":"41","bn":"পরে যায়ীর নামে মজলিস-খানার একজন নেতা এসে ঈসার পায়ের উপর পড়লেন।"},{"v":42,"ve":42,"vl":"42","bn":"তিনি ঈসাকে তাঁর বাড়ীতে আসবার জন্য কাকুতি-মিনতি করতে লাগলেন, কারণ তাঁর বারো বছরের একমাত্র মেয়েটি মরবার মত হয়েছিল। ঈসা যখন যাচ্ছিলেন তখন লোকেরা তাঁর চারদিকে ভিড় করে ঠেলাঠেলি করছিল।"},{"v":43,"ve":43,"vl":"43","bn":"তাদের মধ্যে একজন স্ত্রীলোক বারো বছর ধরে রক্তস্রাব রোগে ভুগছিল। ডাক্তারদের পিছনে সে তার সব কিছুই খরচ করেছিল, কিন্তু কেউই তাকে ভাল করতে পারে নি।"},{"v":44,"ve":44,"vl":"44","bn":"সে পিছন দিক থেকে ঈসার কাছে এসে তাঁর চাদরের কিনারা ছুঁলো, আর তখনই তার রক্তস্রাব বন্ধ হল।"},{"v":45,"ve":45,"vl":"45","bn":"তখন ঈসা বললেন, “কে আমাকে ছুঁলো?” সবাই অস্বীকার করলে পর পিতর ও তাঁর সংগীরা ঈসাকে বললেন, “হুজুর, লোকেরা আপনার চারপাশে চাপাচাপি করে আপনার উপর পড়ছে।”"},{"v":46,"ve":46,"vl":"46","bn":"তবুও ঈসা বললেন, “আমি জানি কেউ আমাকে ছুঁয়েছে, কারণ আমি বুঝতে পারলাম আমার মধ্য থেকে শক্তি বের হল।”"},{"v":47,"ve":47,"vl":"47","bn":"সেই স্ত্রীলোকটি যখন দেখল সে ধরা পড়েছে তখন কাঁপতে কাঁপতে ঈসার সামনে সে উবুড় হয়ে পড়ল। পরে সকলের সামনেই সে ঈসাকে বলল কেন সে তাঁকে ছুঁয়েছিল, আর কেমন করে সে তখনই ভাল হয়েছে।"},{"v":48,"ve":48,"vl":"48","bn":"এতে ঈসা সেই স্ত্রীলোকটিকে বললেন, “মা, তুমি বিশ্বাস করেছ বলে ভাল হয়েছ। শান্তিতে চলে যাও।”"},{"v":49,"ve":49,"vl":"49","bn":"ঈসা তখনও কথা বলছেন এমন সময় সেই মজলিস-খানার নেতার বাড়ী থেকে একজন এসে বলল, “আপনার মেয়েটি মারা গেছে; ওস্তাদকে আর কষ্ট দেবেন না।"},{"v":50,"ve":50,"vl":"50","bn":"এই কথা শুনে ঈসা যায়ীরকে বললেন, “ভয় করবেন না; কেবল বিশ্বাস করুন, তাতেই সে বাঁচবে।”"},{"v":51,"ve":51,"vl":"51","bn":"ঈসা যায়ীরের বাড়ীতে পৌঁছে পিতর, ইউহোন্না ও ইয়াকুব এবং মেয়েটির মা-বাবা ছাড়া আর কাউকে ঘরের ভিতরে আসতে দিলেন না।"},{"v":52,"ve":52,"vl":"52","bn":"সবাই মেয়েটির জন্য কান্নাকাটি ও বিলাপ করছিল। তখন ঈসা বললেন, “আর কেঁদো না। মেয়েটি মারা যায় নি, ঘুমাচ্ছে।”"},{"v":53,"ve":53,"vl":"53","bn":"লোকেরা ঠাট্টা করতে লাগল, কারণ তারা জানত মেয়েটি মারা গেছে।"},{"v":54,"ve":54,"vl":"54","bn":"পরে ঈসা মেয়েটির হাত ধরে ডেকে বললেন, “খুকী, ওঠো।”"},{"v":55,"ve":55,"vl":"55","bn":"এতে মেয়েটির প্রাণ ফিরে আসল, আর সে তখনই উঠে দাঁড়াল। তখন ঈসা হুকুম দিলেন যেন মেয়েটিকে কিছু খেতে দেওয়া হয়।"},{"v":56,"ve":56,"vl":"56","bn":"মেয়েটির মা-বাবা খুব অবাক হয়ে গিয়েছিলেন, কিন্তু ঈসা তাঁদের নিষেধ করে দিলেন যেন এই ঘটনার কথা তাঁরা কাউকে না বলেন।"}],"9":[{"heading":"সাহাবীদের তবলিগ-যাত্রা","v":1,"ve":1,"vl":"1","bn":"এর পরে ঈসা সেই বারোজন সাহাবীকে ডেকে একত্র করলেন এবং সব ভূতের উপরে ক্ষমতা ও অধিকার দান করলেন। তিনি তাঁদের রোগ ভাল করবার ক্ষমতাও দিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তারপর তিনি তাঁদের আল্লাহ্‌র রাজ্যের বিষয়ে তবলিগ করতে ও রোগীদের সুস্থ করতে পাঠিয়ে দিলেন।"},{"v":3,"ve":3,"vl":"3","bn":"তিনি তাঁদের বললেন, “তোমরা পথের জন্য লাঠি, থলি, রুটি বা টাকা কিছুই নিয়ো না, এমন কি, দু’টা করে কোর্তাও না।"},{"v":4,"ve":4,"vl":"4","bn":"যে বাড়ীতে তোমরা ঢুকবে সেই গ্রাম না ছাড়া পর্যন্ত সেই বাড়ীতেই থেকো।"},{"v":5,"ve":5,"vl":"5","bn":"যদি লোকে তোমাদের গ্রহণ না করে তবে তাদের গ্রাম ছেড়ে যাবার সময় তোমাদের পায়ের ধুলা ঝেড়ে ফেলো, যেন সেটাই তাদের বিরুদ্ধে সাক্ষ্য হয়ে দাঁড়ায়।”"},{"v":6,"ve":6,"vl":"6","bn":"তখন সাহাবীরা গ্রামে গ্রামে গিয়ে আল্লাহ্‌র রাজ্যের সুসংবাদ তবলিগ করতে এবং রোগ ভাল করতে লাগলেন।"},{"v":7,"ve":7,"vl":"7","bn":"ঈসা যা করছিলেন সেই সব কথা শুনে শাসনকর্তা হেরোদ কিছুই বুঝে উঠতে পারলেন না। এর কারণ হল, কেউ কেউ বলছিল নবী ইয়াহিয়া মৃত্যু থেকে বেঁচে উঠেছেন;"},{"v":8,"ve":8,"vl":"8","bn":"কেউ কেউ বলছিল নবী ইলিয়াস দেখা দিয়েছেন; আবার কেউ কেউ বলছিল অনেক দিন আগেকার একজন নবী বেঁচে উঠেছেন।"},{"v":9,"ve":9,"vl":"9","bn":"হেরোদ বললেন, “আমি তো ইয়াহিয়ার মাথা কেটে ফেলেছি। তবে যার বিষয়ে আমি এই সব শুনছি, সে কে?” হেরোদ ঈসাকে দেখবার চেষ্টা করতে লাগলেন।"},{"heading":"পাঁচ হাজার লোককে খাওয়ানো","v":10,"ve":10,"vl":"10","bn":"ঈসা যে সাহাবীদের পাঠিয়েছিলেন তাঁরা ফিরে আসলেন এবং কি কি করেছেন সব কিছু তাঁরা ঈসাকে বললেন। তখন ঈসা তাঁদের নিয়ে বৈৎসৈদা গ্রামের কাছে একটা নির্জন জায়গায় গেলেন।"},{"v":11,"ve":11,"vl":"11","bn":"সেই খবর জানতে পেরে অনেক লোক ঈসার পিছনে পিছনে চলল। তিনি সেই লোকদের গ্রহণ করলেন এবং তাদের কাছে আল্লাহ্‌র রাজ্যের কথা বললেন। এছাড়া যাদের সুস্থ হবার দরকার ছিল তিনি তাদের সুস্থ করলেন।"},{"v":12,"ve":12,"vl":"12","bn":"যখন বেলা শেষ হয়ে আসল তখন সেই বারোজন সাহাবী এসে ঈসাকে বললেন, “আমরা যেখানে আছি সেটা একটা নির্জন জায়গা। তাই এই লোকদের বিদায় দিন যেন তারা কাছের পাড়ায় এবং গ্রামগুলোতে গিয়ে খাবার এবং থাকবার জায়গা খুঁজে নিতে পারে।”"},{"v":13,"ve":13,"vl":"13","bn":"ঈসা তাঁদের বললেন, “তোমরাই ওদের খেতে দাও।” তাঁরা বললেন, “কিন্তু আমাদের কাছে কেবল পাঁচটা রুটি আর দু’টা মাছ ছাড়া আর কিছুই নেই। কেবল যদি আমরা গিয়ে এই সব লোকদের জন্য খাবার কিনে আনতে পারতাম তবেই তাদের খাওয়ানো যেত।”"},{"v":14,"ve":14,"vl":"14","bn":"সেখানে কমবেশি পাঁচ হাজার পুরুষ লোক ছিল। ঈসা তাঁর সাহাবীদের বললেন, “পঞ্চাশজন পঞ্চাশজন করে এক এক দলে লোকদের বসিয়ে দাও।”"},{"v":15,"ve":15,"vl":"15","bn":"সাহাবীরা সেই ভাবেই সব লোকদের বসিয়ে দিলেন।"},{"v":16,"ve":16,"vl":"16","bn":"তখন ঈসা সেই পাঁচটা রুটি আর দু’টা মাছ নিয়ে আসমানের দিকে তাকালেন এবং সেগুলোর জন্য আল্লাহ্‌কে শুকরিয়া জানাবার পর টুকরা টুকরা করলেন। তারপর তিনি লোকদের দেবার জন্য সেগুলো সাহাবীদের হাতে দিলেন।"},{"v":17,"ve":17,"vl":"17","bn":"লোকেরা সবাই পেট ভরে খেল। পরে যে টুকরাগুলো পড়ে রইল তা বারোটা টুকরিতে তুলে নেওয়া হল।"},{"heading":"হযরত পিতরের সাক্ষ্য","v":18,"ve":18,"vl":"18","bn":"একবার ঈসা একটা নির্জন জায়গায় মুনাজাত করছিলেন। তাঁর সংগে কেবল তাঁর সাহাবীরাই ছিলেন। তিনি তাঁদের জিজ্ঞাসা করলেন, “আমি কে, এই বিষয়ে লোকে কি বলে?”"},{"v":19,"ve":19,"vl":"19","bn":"সাহাবীরা বললেন, “কেউ কেউ বলে আপনি তরিকাবন্দীদাতা ইয়াহিয়া; কেউ কেউ বলে নবী ইলিয়াস; আবার কেউ কেউ বলে অনেক দিন আগেকার একজন নবী বেঁচে উঠেছেন।”"},{"v":20,"ve":20,"vl":"20","bn":"ঈসা তাঁদের বললেন, “কিন্তু তোমরা কি বল, আমি কে?” পিতর বললেন, “আপনি আল্লাহ্‌র সেই মসীহ্‌।”"},{"v":21,"ve":21,"vl":"21","bn":"তখন ঈসা তাঁদের সাবধান করলেন এবং হুকুম দিলেন যেন তাঁরা কাউকে এই কথা না বলেন।"},{"v":22,"ve":22,"vl":"22","bn":"তিনি তাঁদের আরও বললেন, ইব্‌ন্তেআদমকে অনেক দুঃখভোগ করতে হবে। বৃদ্ধনেতারা, প্রধান ইমামেরা এবং আলেমেরা তাঁকে অগ্রাহ্য করবেন। তাঁকে হত্যা করা হবে এবং তিন দিনের দিন তাঁকে মৃত্যু থেকে জীবিত হয়ে উঠতে হবে।"},{"v":23,"ve":23,"vl":"23","bn":"তারপর তিনি সবাইকে বললেন, “যদি কেউ আমার পথে আসতে চায়, তবে সে নিজের ইচ্ছামত না চলুক; প্রত্যেক দিন নিজের ক্রুশ বয়ে নিয়ে সে আমার পিছনে আসুক।"},{"v":24,"ve":24,"vl":"24","bn":"যে কেউ তার নিজের জন্য বেঁচে থাকতে চায় সে তার সত্যিকারের জীবন হারাবে; কিন্তু যে আমার জন্য তার প্রাণ হারায় সে তার সত্যিকারের জীবন রক্ষা করবে।"},{"v":25,"ve":25,"vl":"25","bn":"যদি কেউ সমস্ত দুনিয়া লাভ করে তার বিনিময়ে তার সত্যিকারের জীবন হারায় তবে তার কি লাভ হল?"},{"v":26,"ve":26,"vl":"26","bn":"যদি কেউ আমাকে নিয়ে ও আমার কথা নিয়ে লজ্জা বোধ করে, তবে ইব্‌ন্তেআদম যখন নিজের মহিমা এবং পিতা ও পবিত্র ফেরেশতাদের মহিমায় আসবেন তখন তিনিও সেই লোকের সম্বন্ধে লজ্জা বোধ করবেন।"},{"v":27,"ve":27,"vl":"27","bn":"আমি তোমাদের সত্যিই বলছি, এখানে এমন কয়েকজন আছে যাদের কাছে আল্লাহ্‌র রাজ্য দেখা না দেওয়া পর্যন্ত তারা কোনমতেই মারা যাবে না।”"},{"heading":"হযরত ঈসা মসীহের নূরানী চেহারা","v":28,"ve":28,"vl":"28","bn":"এই সব কথা বলবার প্রায় এক সপ্তা পরে ঈসা মুনাজাত করবার জন্য পিতর, ইউহোন্না ও ইয়াকুবকে নিয়ে একটা পাহাড়ে গেলেন।"},{"v":29,"ve":29,"vl":"29","bn":"মুনাজাত করবার সময় ঈসার মুখের চেহারা বদলে গেল এবং তাঁর কাপড়-চোপড় উজ্জ্বল সাদা হয়ে গেল,"},{"v":30,"ve":30,"vl":"30","bn":"আর দু’জন লোককে তাঁর সংগে কথা বলতে দেখা গেল। সেই দু’জন ছিলেন নবী মূসা এবং নবী ইলিয়াস।"},{"v":31,"ve":31,"vl":"31","bn":"তাঁরা মহিমার সংগে দেখা দিলেন। জেরুজালেমে যে মৃত্যুর সামনে ঈসা উপস্থিত হতে যাচ্ছিলেন তাঁরা সেই বিষয়ে কথাবার্তা বলছিলেন।"},{"v":32,"ve":32,"vl":"32","bn":"পিতর ও তাঁর সংগীরা সেই সময় অঘোরে ঘুমাচ্ছিলেন। তাঁরা জেগে উঠে ঈসার মহিমা দেখতে পেলেন এবং তাঁর সংগে দাঁড়ানো সেই দু’জন লোককেও দেখলেন।"},{"v":33,"ve":33,"vl":"33","bn":"সেই দু’জন যখন ঈসার কাছ থেকে চলে যাচ্ছিলেন তখন পিতর ঈসাকে বললেন, “হুজুর, ভালই হয়েছে যে, আমরা এখানে আছি। আমরা এখানে তিনটা কুঁড়ে-ঘর তৈরী করি- একটা আপনার, একটা মূসার ও একটা ইলিয়াসের জন্য।” তিনি যে কি বলছিলেন তা নিজেই বুঝলেন না।"},{"v":34,"ve":34,"vl":"34","bn":"পিতর যখন কথা বলছিলেন তখন একটা মেঘ এসে তাঁদের ঢেকে ফেলল। তাঁরা সেই মেঘের মধ্যে ঢাকা পড়লে পর সাহাবীরা ভয় পেলেন।"},{"v":35,"ve":35,"vl":"35","bn":"সেই মেঘ থেকে এই কথা শোনা গেল, “ইনিই আমার পুত্র যাঁকে আমি বেছে নিয়েছি; তোমরা এঁর কথা শোন।”"},{"v":36,"ve":36,"vl":"36","bn":"যখন কথা থেমে গেল তখন দেখা গেল ঈসা একাই আছেন। সাহাবীরা যা দেখেছিলেন সেই বিষয়ে সেই সময় কাউকে কিছু না বলে তাঁরা চুপ করে রইলেন।"},{"heading":"ভূতে পাওয়া ছেলেটি সুস্থ হল","v":37,"ve":37,"vl":"37","bn":"পরের দিন ঈসা ও সেই তিনজন সাহাবী পাহাড় থেকে নেমে আসলে পর অনেক লোক ঈসার সংগে দেখা করতে আসল।"},{"v":38,"ve":38,"vl":"38","bn":"তখন ভিড়ের মধ্য থেকে একজন লোক চিৎকার করে ঈসাকে বলল, “হুজুর, দয়া করে আমার ছেলেটাকে দেখুন। সে আমার একমাত্র ছেলে।"},{"v":39,"ve":39,"vl":"39","bn":"তাকে একটা ভূতে ধরে এবং সে হঠাৎ চিৎকার করে ওঠে। সেই ভূত যখন তাকে মুচড়ে ধরে তখন তার মুখ থেকে ফেনা বের হয়; তারপর সে তাকে খুব কষ্ট দিয়ে ক্ষত-বিক্ষত করে ছেড়ে দেয়।"},{"v":40,"ve":40,"vl":"40","bn":"আমি আপনার সাহাবীদের কাছে কাকুতি-মিনতি করেছিলাম যেন তাঁরা সেই ভূতকে ছাড়িয়ে দেন, কিন্তু তাঁরা পারলেন না।”"},{"v":41,"ve":41,"vl":"41","bn":"তখন ঈসা বললেন, “বেঈমান ও দুষ্ট লোকেরা! আর কতদিন আমি তোমাদের সংগে থাকব ও তোমাদের সহ্য করব? তোমার ছেলেকে এখানে আন।”"},{"v":42,"ve":42,"vl":"42","bn":"ছেলেটা যখন আসছিল তখন সেই ভূত তাকে আছাড় মেরে মুচড়ে ধরল। এতে ঈসা সেই ভূতকে ধমক দিলেন এবং ছেলেটিকে সুস্থ করে তার পিতার কাছে ফিরিয়ে দিলেন।"},{"v":43,"ve":43,"vl":"43","bn":"আল্লাহ্‌ যে কত মহান তা দেখে সবাই আশ্চর্য হল। ঈসা যা করছিলেন সেই বিষয়ে সবাই যখন আশ্চর্য হয়ে ভাবছিল তখন তিনি তাঁর সাহাবীদের বললেন,"},{"heading":"নানা রকম শিক্ষা ও জেরুজালেমে যাত্রা","v":44,"ve":44,"vl":"44","bn":"“আমার এই কথা মন দিয়ে শোন, ইব্‌ন্তেআদমকে লোকদের হাতে ধরিয়ে দেওয়া হবে।”"},{"v":45,"ve":45,"vl":"45","bn":"সাহাবীরা কিন্তু সেই কথা বুঝলেন না। আল্লাহ্‌ তাঁদের কাছ থেকে তা গোপন রেখেছিলেন যেন তাঁরা বুঝতে না পারেন। এই নিয়ে কোন কথা ঈসাকে জিজ্ঞাসা করতেও সাহাবীদের ভয় হল।"},{"v":46,"ve":46,"vl":"46","bn":"সাহাবীদের মধ্যে কে সবচেয়ে বড় সেই বিষয়ে তাঁদের মধ্যে তর্ক হচ্ছিল।"},{"v":47,"ve":47,"vl":"47","bn":"ঈসা তাঁদের মনের চিন্তা বুঝতে পেরে একটা শিশুকে নিয়ে নিজের পাশে দাঁড় করালেন।"},{"v":48,"ve":48,"vl":"48","bn":"তারপর তিনি তাঁদের বললেন, “যে কেউ আমার নামে এই শিশুকে গ্রহণ করে সে আমাকেই গ্রহণ করে। যে আমাকে গ্রহণ করে, আমাকে যিনি পাঠিয়েছেন সে তাঁকেই গ্রহণ করে। তোমাদের সকলের মধ্যে সবচেয়ে যে ছোট, সে-ই বড়।”"},{"v":49,"ve":49,"vl":"49","bn":"ইউহোন্না বললেন, “হুজুর, আপনার নামে আমরা একজনকে ভূত ছাড়াতে দেখেছি। সে আমাদের দলের লোক নয় বলে আমরা তাকে নিষেধ করেছি।”"},{"v":50,"ve":50,"vl":"50","bn":"ঈসা তাঁকে বললেন, “আর নিষেধ কোরো না, কারণ যে তোমাদের বিপক্ষে থাকে না সে তো তোমাদের পক্ষেই আছে।”"},{"v":51,"ve":51,"vl":"51","bn":"যখন ঈসার বেহেশতে যাবার সময় হয়ে আসল তখন তিনি জেরুজালেমে যাবার জন্য মন স্থির করলেন।"},{"v":52,"ve":52,"vl":"52","bn":"তিনি আগেই সেখানে লোকদের পাঠিয়ে দিলেন। তারা ঈসার জন্য সব কিছু ব্যবস্থা করতে সামেরীয়দের একটা গ্রামে ঢুকল,"},{"v":53,"ve":53,"vl":"53","bn":"কিন্তু ঈসা জেরুজালেমে যাচ্ছেন বলে সেই গ্রামের লোকেরা তাঁকে গ্রহণ করল না।"},{"v":54,"ve":54,"vl":"54","bn":"তা দেখে তাঁর সাহাবী ইয়াকুব ও ইউহোন্না বললেন, “হুজুর, আপনি কি চান যে, নবী ইলিয়াসের মত আমরা এদের ধ্বংস করবার জন্য বেহেশত থেকে আগুন নেমে আসতে বলব?”"},{"v":55,"ve":55,"vl":"55","bn":"ঈসা তাঁদের দিকে ফিরে তাঁদের ধমক দিলেন।"},{"v":56,"ve":56,"vl":"56","bn":"তারপর তাঁরা অন্য গ্রামে গেলেন।"},{"v":57,"ve":57,"vl":"57","bn":"তাঁরা পথে যাচ্ছেন এমন সময় একজন লোক ঈসাকে বলল, “আপনি যেখানে যাবেন আমিও আপনার সংগে সেখানে যাব।”"},{"v":58,"ve":58,"vl":"58","bn":"ঈসা তাকে বললেন, “শিয়ালের গর্ত আছে এবং পাখীর বাসা আছে, কিন্তু ইব্‌ন্তেআদমের মাথা রাখবার জায়গা কোথাও নেই।”"},{"v":59,"ve":59,"vl":"59","bn":"পরে তিনি অন্য আর একজনকে বললেন, “আমার সংগে চল।” কিন্তু সেই লোক বলল, “হুজুর, আগে আমার বাবাকে দাফন করে আসতে দিন।”"},{"v":60,"ve":60,"vl":"60","bn":"ঈসা তাকে বললেন, “মৃতেরাই তাদের মৃতদের দাফন করুক, কিন্তু তুমি এসে আল্লাহ্‌র রাজ্যের বিষয়ে তবলিগ কর।”"},{"v":61,"ve":61,"vl":"61","bn":"আর একজন বলল, “হুজুর, আমি আপনার সংগে যাব, কিন্তু আগে আমার বাড়ী থেকে আমাকে বিদায় নিয়ে আসতে দিন।”"},{"v":62,"ve":62,"vl":"62","bn":"ঈসা তাকে বললেন, “লাংগলে হাত দিয়ে যে পিছন দিকে তাকিয়ে থাকে সে আল্লাহ্‌র রাজ্যের উপযুক্ত নয়।”"}],"10":[{"heading":"সত্তরজন সাহাবীকে পাঠানো","v":1,"ve":1,"vl":"1","bn":"এর পরে হযরত ঈসা আরও সত্তরজন সাহাবীকে তবলিগে পাঠাবার জন্য বেছে নিলেন। তিনি নিজে যে যে গ্রামে ও যে যে জায়গায় যাবেন বলে ঠিক করেছিলেন সেই সব জায়গায় যাবার আগে সাহাবীদের দু’জন দু’জন করে পাঠিয়ে দিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তিনি সাহাবীদের বললেন, “সত্যিই ফসল অনেক, কিন্তু কাজ করবার লোক কম। এইজন্য ফসলের মালিকের কাছে অনুরোধ কর যেন তিনি তাঁর ফসল কাটবার জন্য লোক পাঠিয়ে দেন।"},{"v":3,"ve":3,"vl":"3","bn":"তোমরা যাও; নেকড়ে বাঘের মধ্যে ভেড়ার মতই আমি তোমাদের পাঠাচ্ছি।"},{"v":4,"ve":4,"vl":"4","bn":"টাকার থলি, ঝুলি বা জুতা সংগে নিয়ো না এবং রাস্তায় কাউকে সালাম জানায়ো না।"},{"v":5,"ve":5,"vl":"5","bn":"তোমরা যে বাড়ীতে যাবে প্রথমে বলবে, ‘এই বাড়ীতে শান্তি হোক।’"},{"v":6,"ve":6,"vl":"6","bn":"শান্তি ভালবাসে এমন কেউ যদি সেখানে থাকে তবে তোমাদের শান্তি তার উপরে থাকবে, কিন্তু যদি সেই রকম কেউ না থাকে তবে তোমাদের শান্তি তোমাদের কাছেই ফিরে আসবে।"},{"v":7,"ve":7,"vl":"7","bn":"সেই বাড়ীতেই থেকো এবং তারা যা দেয় তা-ই খেয়ো, কারণ যে কাজ করে সে বেতন পাবার যোগ্য। এক বাড়ী ছেড়ে অন্য বাড়ীতে যেয়ো না।"},{"v":8,"ve":8,"vl":"8","bn":"“যদি কোন গ্রামে যাও এবং সেখানকার লোকেরা তোমাদের গ্রহণ করে তবে তোমাদের যা খেতে দেওয়া হয় তা-ই খেয়ো।"},{"v":9,"ve":9,"vl":"9","bn":"সেই গ্রামের অসুস্থদের সুস্থ কোরো এবং তাদের বোলো, ‘আল্লাহ্‌র রাজ্য তোমাদের কাছে এসেছে।’"},{"v":10,"ve":10,"vl":"10","bn":"কিন্তু যদি কোন গ্রামে যাও এবং সেখানকার লোকেরা তোমাদের গ্রহণ না করে তবে সেই গ্রামের রাস্তায় রাস্তায় গিয়ে এই কথা বোলো,"},{"v":11,"ve":11,"vl":"11","bn":"‘তোমাদের গ্রামের যে ধুলা আমাদের পায়ে লেগেছে তাও আমরা তোমাদের বিরুদ্ধে ঝেড়ে ফেললাম। তবুও তোমরা জেনে রেখো, আল্লাহ্‌র রাজ্য কাছে এসে গেছে।’"},{"v":12,"ve":12,"vl":"12","bn":"আমি তোমাদের বলছি, রোজ হাশরে সেই গ্রামের চেয়ে বরং সাদুম শহরের লোকদের অবস্থা অনেকখানি সহ্য করবার মত হবে।"},{"v":13,"ve":13,"vl":"13","bn":"“ঘৃণ্য কোরাসীন! ঘৃণ্য বৈৎসৈদা! যে সব অলৌকিক কাজ তোমাদের মধ্যে করা হয়েছে তা যদি টায়ার ও সিডন শহরে করা হত, তবে তারা অনেক দিন আগেই চট পরে ছাইয়ের মধ্যে বসে তওবা করত।"},{"v":14,"ve":14,"vl":"14","bn":"সত্যিই, রোজ হাশরে টায়ার ও সিডনের অবস্থা বরং তোমাদের চেয়ে অনেকখানি সহ্য করবার মত হবে।"},{"v":15,"ve":15,"vl":"15","bn":"আর তুমি, কফরনাহূম, তুমি নাকি বেহেশত পর্যন্ত উঁচুতে উঠবে? কখনও না, তোমাকে নীচে কবরে ফেলে দেওয়া হবে।”"},{"v":16,"ve":16,"vl":"16","bn":"ঈসা আবার তাঁর সাহাবীদের বললেন, “যারা তোমাদের কথা শোনে তারা আমারই কথা শোনে। যারা তোমাদের অগ্রাহ্য করে তারা আমাকেই অগ্রাহ্য করে। যারা আমাকে অগ্রাহ্য করে, আমাকে যিনি পাঠিয়েছেন তারা তাঁকেই অগ্রাহ্য করে।”"},{"v":17,"ve":17,"vl":"17","bn":"সেই সত্তরজন সাহাবী আনন্দের সংগে ফিরে এসে বললেন, “হুজুর, আপনার নাম করে বললে ভূতেরা পর্যন্ত আমাদের কথা শোনে।”"},{"v":18,"ve":18,"vl":"18","bn":"ঈসা তাঁদের বললেন, “আমি শয়তানকে বেহেশত থেকে বিদ্যুৎ চম্‌কাবার মত করে পড়ে যেতে দেখেছি।"},{"v":19,"ve":19,"vl":"19","bn":"দেখ, আমি তোমাদের সাপ ও বিছার উপর দিয়ে হেঁটে যাবার ক্ষমতা দিয়েছি এবং তোমাদের শত্রু শয়তানের সমস্ত শক্তির উপরেও ক্ষমতা দিয়েছি। কোন কিছুই তোমাদের ক্ষতি করবে না।"},{"v":20,"ve":20,"vl":"20","bn":"কিন্তু ভূতেরা তোমাদের কথা শোনে বলে আনন্দিত হয়ো না বরং বেহেশতে তোমাদের নাম লেখা হয়েছে বলে আনন্দিত হয়ো।”"},{"v":21,"ve":21,"vl":"21","bn":"তখন ঈসা পাক-রূহের দেওয়া আনন্দে আনন্দিত হয়ে বললেন, “হে পিতা, তুমি বেহেশত ও দুনিয়ার মালিক। আমি তোমার প্রশংসা করি, কারণ তুমি এই সব বিষয় জ্ঞানী ও বুদ্ধিমানদের কাছ থেকে লুকিয়ে রেখেছ কিন্তু শিশুর মত লোকদের কাছে প্রকাশ করেছ। জ্বী পিতা, তোমার ইচ্ছামতই এটা হয়েছে।"},{"v":22,"ve":22,"vl":"22","bn":"“আমার পিতা আমার হাতে সব কিছুই দিয়েছেন। পিতা ছাড়া আর কেউ জানে না পুত্র কে, আবার পুত্র ছাড়া আর কেউ জানে না পিতা কে। এছাড়া পুত্র যার কাছে পিতাকে প্রকাশ করতে ইচ্ছা করেন কেবল সে-ই জানে।"},{"v":23,"ve":23,"vl":"23","bn":"পরে তিনি সাহাবীদের দিকে ফিরে তাঁদের গোপনে বললেন, “তোমরা যা যা দেখছ, তা যারা দেখতে পায় তারা ধন্য।"},{"v":24,"ve":24,"vl":"24","bn":"আমি তোমাদের বলছি, তোমরা যা যা দেখছ, অনেক নবী ও বাদশাহ্‌ তা দেখতে চেয়েও দেখতে পান নি; আর তোমরা যা যা শুনছ, তা শুনতে চেয়েও শুনতে পান নি।”"},{"heading":"দয়ালু সামেরীয়ের গল্প","v":25,"ve":25,"vl":"25","bn":"একবার একজন আলেম ঈসার কাছে আসলেন। ঈসাকে পরীক্ষা করবার জন্য সেই আলেম বললেন, “হুজুর, কি করলে আমি অনন্ত জীবন লাভ করতে পারব?”"},{"v":26,"ve":26,"vl":"26","bn":"ঈসা তাঁকে বললেন, “তৌরাত শরীফে কি লেখা আছে? সেখানে কি পড়েছেন?”"},{"v":27,"ve":27,"vl":"27","bn":"সেই আলেম ঈসাকে জবাব দিলেন, “তোমরা প্রত্যেকে তোমাদের সমস্ত দিল, সমস্ত প্রাণ, সমস্ত শক্তি ও সমস্ত মন দিয়ে তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত করবে; আর তোমার প্রতিবেশীকে নিজের মত মহব্বত করবে।”"},{"v":28,"ve":28,"vl":"28","bn":"ঈসা তাঁকে বললেন, “আপনি ঠিক জবাব দিয়েছেন। যদি আপনি তা করতে থাকেন তবে জীবন পাবেন।”"},{"v":29,"ve":29,"vl":"29","bn":"সেই আলেম নিজের সম্মান রক্ষা করবার জন্য ঈসাকে বললেন, “আমার প্রতিবেশী কে?”"},{"v":30,"ve":30,"vl":"30","bn":"ঈসা জবাব দিলেন, “একজন লোক জেরুজালেম থেকে জেরিকো শহরে যাবার সময় ডাকাতদের হাতে পড়ল। তারা লোকটির কাপড় খুলে ফেলল এবং তাকে মেরে আধমরা করে রেখে গেল।"},{"v":31,"ve":31,"vl":"31","bn":"পরে একজন ইমাম সেই পথ দিয়ে যাচ্ছিলেন। তিনি সেই লোকটিকে দেখে পাশ কাটিয়ে চলে গেলেন।"},{"v":32,"ve":32,"vl":"32","bn":"ঠিক সেইভাবে একজন লেবীয় সেই জায়গায় আসল এবং তাকে দেখতে পেয়ে পাশ কাটিয়ে চলে গেল।"},{"v":33,"ve":33,"vl":"33","bn":"তারপর সামেরিয়া প্রদেশের একজন লোকও সেই পথ দিয়ে যেতে যেতে ঐ লোকটির কাছাকাছি আসল। তাকে দেখে তার মমতা হল।"},{"v":34,"ve":34,"vl":"34","bn":"লোকটির কাছে গিয়ে সে তার আঘাতের উপর তেল আর আংগুর-রস ঢেলে দিয়ে বেঁধে দিল। তারপর তার নিজের গাধার উপর তাকে বসিয়ে একটা হোটেলে নিয়ে গিয়ে তার সেবা-যত্ন করল।"},{"v":35,"ve":35,"vl":"35","bn":"পরের দিন সেই সামেরীয় দু’টা দীনার বের করে হোটেলের মালিককে দিয়ে বলল, ‘এই লোকটিকে যত্ন করবেন। যদি এর চেয়ে বেশী খরচ হয় তবে আমি ফিরে এসে তা শোধ করব।’ ”"},{"v":36,"ve":36,"vl":"36","bn":"শেষে ঈসা বললেন, “এখন আপনার কি মনে হয়? এই তিনজনের মধ্যে কে সেই ডাকাতদের হাতে পড়া লোকটির প্রতিবেশী?”"},{"v":37,"ve":37,"vl":"37","bn":"সেই আলেম বললেন, “যে তাকে মমতা করল সেই লোক।” তখন ঈসা তাঁকে বললেন, “তা হলে আপনিও গিয়ে সেই রকম করুন।”"},{"heading":"বিবি মার্থা ও তাঁর বোন","v":38,"ve":38,"vl":"38","bn":"এর পরে ঈসা ও তাঁর সাহাবীরা পথ চলতে চলতে কোন একটা গ্রামে ঢুকলেন। সেখানে মার্থা নামে একজন স্ত্রীলোক খুশী হয়ে তাঁর ঘরে ঈসাকে গ্রহণ করলেন।"},{"v":39,"ve":39,"vl":"39","bn":"মরিয়ম নামে মার্থার একটি বোন ছিলেন। তিনি ঈসার পায়ের কাছে বসে তাঁর কথা শুনছিলেন।"},{"v":40,"ve":40,"vl":"40","bn":"মার্থা কিন্তু খাওয়া-দাওয়ার ব্যবস্থা করতে ব্যস্ত ছিলেন। তাই তিনি এসে বললেন, “হুজুর, আপনি কি দেখেন না, আমার বোন সমস্ত কাজ একা আমার উপর ফেলে দিয়েছে? আপনি ওকে বলুন যেন ও আমাকে সাহায্য করে।”"},{"v":41,"ve":41,"vl":"41","bn":"তখন ঈসা মার্থাকে বললেন, “মার্থা, মার্থা, তুমি অনেক বিষয়ে চিনি-ত ও ব্যস্ত,"},{"v":42,"ve":42,"vl":"42","bn":"কিন্তু একটাই মাত্র দরকারী বিষয় আছে। মরিয়ম সেই ভাল বিষয়টাই বেছে নিয়েছে। ওটা তার কাছ থেকে নিয়ে নেওয়া হবে না।”"}],"11":[{"heading":"মুনাজাতের বিষয়ে শিক্ষা","v":1,"ve":1,"vl":"1","bn":"এক সময়ে ঈসা কোন একটা জায়গায় মুনাজাত করছিলেন। মুনাজাত শেষ হলে পর তাঁর একজন সাহাবী তাঁকে বললেন, “হুজুর, ইয়াহিয়া যেমন তাঁর সাহাবীদের মুনাজাত করতে শিখিয়েছিলেন তেমনি আমাদেরও আপনি মুনাজাত করতে শিখান।”"},{"v":2,"ve":2,"vl":"2","bn":"ঈসা তাঁদের বললেন, “যখন তোমরা মুনাজাত কর তখন বোলো, ‘হে আমাদের বেহেশতী পিতা, তোমার নাম পবিত্র বলে মান্য হোক। তোমার রাজ্য আসুক।"},{"v":3,"ve":3,"vl":"3","bn":"প্রত্যেক দিনের খাবার তুমি আমাদের প্রত্যেক দিন দাও।"},{"v":4,"ve":4,"vl":"4","bn":"আমাদের গুনাহ্‌ মাফ কর, কারণ যারা আমাদের বিরুদ্ধে গুনাহ্‌ করে আমরা তাদের মাফ করি। আমাদের তুমি পরীক্ষায় পড়তে দিয়ো না।’ ”"},{"v":5,"ve":5,"vl":"5","bn":"তারপর ঈসা তাঁর সাহাবীদের বললেন, “মনে কর, মাঝ রাতে তোমাদের মধ্যে একজন তার বন্ধুর বাড়ীতে গিয়ে বলল, ‘বন্ধু, আমাকে তিনটা রুটি ধার দাও।"},{"v":6,"ve":6,"vl":"6","bn":"আমার এক বন্ধু পথে যেতে যেতে আমার কাছে এসেছে। তাকে খেতে দেবার মত আমার কিছুই নেই।’"},{"v":7,"ve":7,"vl":"7","bn":"তখন ঘরের ভিতর থেকে তার বন্ধু জবাব দিল, ‘আমাকে কষ্ট দিয়ো না। দরজা এখন বন্ধ আর আমার ছেলেমেয়েরা বিছানায় আমার কাছে শুয়ে আছে। আমি উঠে তোমাকে কিছুই দিতে পারব না।’"},{"v":8,"ve":8,"vl":"8","bn":"আমি তোমাদের বলছি, সে যদি বন্ধু হিসাবে উঠে তাকে কিছু না-ও দেয়, তবু লোকটি বারবার অনুরোধ করছে বলে সে উঠবে এবং তার যা দরকার তা তাকে দেবে।"},{"v":9,"ve":9,"vl":"9","bn":"“এইজন্য আমি তোমাদের বলছি, চাও, তোমাদের দেওয়া হবে; তালাশ কর, পাবে; দরজায় আঘাত কর, তোমাদের জন্য খোলা হবে।"},{"v":10,"ve":10,"vl":"10","bn":"যারা চায় তারা প্রত্যেকে পায়; যে তালাশ করে সে পায়; আর যে দরজায় আঘাত করে তার জন্য দরজা খোলা হয়।"},{"v":11,"ve":11,"vl":"11","bn":"তোমাদের মধ্যে এমন পিতা কে আছে, যে তার ছেলে রুটি চাইলে তাকে পাথর দেবে, কিংবা মাছ চাইলে সাপ দেবে,"},{"v":12,"ve":12,"vl":"12","bn":"কিংবা ডিম চাইলে বিছা দেবে?"},{"v":13,"ve":13,"vl":"13","bn":"তাহলে তোমরা খারাপ হয়েও যদি তোমাদের ছেলেমেয়েদের ভাল ভাল জিনিস দিতে জান, তবে যারা বেহেশতী পিতার কাছে চায়, তিনি যে তাদের পাক-রূহ্‌কে দেবেন এটা কত না নিশ্চয়!”"},{"heading":"হযরত ঈসা মসীহ্‌ কার সাহায্যে কাজ করেন?","v":14,"ve":14,"vl":"14","bn":"অন্য এক সময়ে ঈসা একটা বোবা ভূত দূর করছিলেন। ভূত দূর হয়ে গেলে পর বোবা লোকটা কথা বলতে লাগল। এতে লোকেরা আশ্চর্য হল,"},{"v":15,"ve":15,"vl":"15","bn":"কিন্তু কয়েকজন বলল, “ভূতদের বাদশাহ্‌ বেল্‌সবূলের সাহায্যে সে ভূত ছাড়ায়।”"},{"v":16,"ve":16,"vl":"16","bn":"অন্য লোকেরা ঈসাকে পরীক্ষা করবার জন্য বেহেশত থেকে একটা চিহ্ন দেখাতে বলল।"},{"v":17,"ve":17,"vl":"17","bn":"তাদের মনের কথা বুুঝতে পেরে ঈসা বললেন, “যে রাজ্য নিজের মধ্যে ভাগ হয়ে যায় সেই রাজ্য ধ্বংস হয়, আর তাতে সেই রাজ্যের পরিবারগুলোও ভাগ হয়ে যায়।"},{"v":18,"ve":18,"vl":"18","bn":"শয়তানও যদি নিজের বিরুদ্ধে দাঁড়ায় তবে কেমন করে তার রাজ্য টিকবে? আপনারা বলছেন আমি বেল্‌সবূলের সাহায্যে ভূত ছাড়াই।"},{"v":19,"ve":19,"vl":"19","bn":"খুব ভাল, আমি যদি বেল্‌সবূলের সাহায্যেই তাদের ছাড়াই তবে আপনাদের লোকেরা কার সাহায্যে ভূত ছাড়ায়? আপনারা ঠিক কথা বলছেন কিনা আপনাদের লোকেরাই তা বিচার করবেন।"},{"v":20,"ve":20,"vl":"20","bn":"কিন্তু আমি যদি আল্লাহ্‌র শক্তিতে ভূত ছাড়াই তবে আল্লাহ্‌র রাজ্য তো আপনাদের কাছে এসে গেছে।"},{"v":21,"ve":21,"vl":"21","bn":"“একজন বলবান লোক সব রকম অস্ত্রশস্ত্র নিয়ে যখন নিজের ঘর পাহারা দেয় তখন তার জিনিসপত্র নিরাপদে থাকে।"},{"v":22,"ve":22,"vl":"22","bn":"কিন্তু তার চেয়ে বলবান কেউ এসে যদি তাকে হামলা করে হারিয়ে দেয় তবে যে অস্ত্রশস্ত্রের উপর সে ভরসা করেছিল, অন্য লোকটি সেগুলো কেড়ে নেয় আর লুট-করা জিনিসগুলো ভাগ করে নেয়।"},{"v":23,"ve":23,"vl":"23","bn":"“যদি কেউ আমার পক্ষে না থাকে তবে তো সে আমার বিপক্ষে আছে। যে আমার সংগে কুড়ায় না সে ছড়ায়।"},{"v":24,"ve":24,"vl":"24","bn":"“কোন ভূত যখন একজন লোকের মধ্য থেকে বের হয়ে যায় তখন সে বিশ্রামের তালাশে শুকনা জায়গার মধ্য দিয়ে ঘোরাফেরা করতে থাকে। পরে তা না পেয়ে সে বলে, ‘আমি যে ঘর থেকে বের হয়ে এসেছি আবার আমি সেই ঘরেই ফিরে যাব।’"},{"v":25,"ve":25,"vl":"25","bn":"ফিরে এসে সেই ঘরটা সে খালি, পরিষ্কার এবং সাজানো দেখতে পায়।"},{"v":26,"ve":26,"vl":"26","bn":"তখন সে গিয়ে নিজের চেয়েও খারাপ অন্য আরও সাতটা ভূত সংগে করে নিয়ে আসে এবং সেখানে ঢুকে বাস করতে থাকে। তার ফলে সেই লোকটার প্রথম দশা থেকে শেষ দশা আরও খারাপ হয়।”"},{"v":27,"ve":27,"vl":"27","bn":"ঈসা যখন কথা বলছিলেন তখন ভিড়ের মধ্য থেকে একজন স্ত্রীলোক চিৎকার করে বলল, “ধন্য সেই স্ত্রীলোক, যিনি আপনাকে গর্ভে ধরেছেন এবং বুকের দুধ খাইয়েছেন।”"},{"v":28,"ve":28,"vl":"28","bn":"কিন্তু ঈসা বললেন, “এর চেয়ে বরং ধন্য তারা, যারা আল্লাহ্‌র কালাম শোনে এবং সেইমত কাজ করে।”"},{"heading":"নানা রকম শিক্ষা","v":29,"ve":29,"vl":"29","bn":"আরও লোক ঈসার চারদিকে জমায়েত হতে থাকল। তখন ঈসা বললেন, “এই কালের লোকেরা খারাপ। তারা চিহ্নের তালাশ করে কিন্তু নবী ইউনুসের চিহ্ন ছাড়া আর কোন চিহ্ন তাদের দেখানো হবে না।"},{"v":30,"ve":30,"vl":"30","bn":"নিনেভে শহরের লোকদের জন্য ইউনুস যেমন নিজেই চিহ্ন হয়েছিলেন ঠিক তেমনি করে এই কালের লোকদের জন্য ইব্‌ন্তেআদম চিহ্ন হবেন।"},{"v":31,"ve":31,"vl":"31","bn":"রোজ হাশরে দক্ষিণ দেশের রাণী উঠে এই কালের লোকদের দোষ দেখিয়ে দেবেন, কারণ সোলায়মান বাদশাহ্‌র জ্ঞানের কথাবার্তা শুনবার জন্য তিনি দুনিয়ার শেষ সীমা থেকে এসেছিলেন; আর দেখুন, এখানে সোলায়মানের চেয়েও আরও মহান একজন আছেন।"},{"v":32,"ve":32,"vl":"32","bn":"রোজ হাশরে নিনেভে শহরের লোকেরা উঠে এই কালের লোকদের দোষ দেখিয়ে দেবে, কারণ নবী ইউনুসের তবলিগের ফলে নিনেভের লোকেরা তওবা করেছিল; আর দেখুন, এখানে ইউনুসের চেয়েও আরও মহান একজন আছেন।"},{"v":33,"ve":33,"vl":"33","bn":"“কেউ বাতি জ্বেলে কোন গোপন জায়গায় বা ঝুড়ির নীচে রাখে না বরং বাতিদানের উপরেই রাখে, যেন ভিতরে যারা ঢোকে তারা আলো দেখতে পায়।"},{"v":34,"ve":34,"vl":"34","bn":"আপনার চোখ হল আপনার শরীরের বাতি। যদি আপনার চোখ ভাল হয় তবে আপনার সমস্ত শরীর আলোতে পূর্ণ হবে, কিন্তু চোখ খারাপ হলে আপনার শরীরও অন্ধকারে পূর্ণ হবে।"},{"v":35,"ve":35,"vl":"35","bn":"আপনার মধ্যে যে আলো আছে তা আসলে অন্ধকার কি না সেই বিষয়ে সাবধান হোন।"},{"v":36,"ve":36,"vl":"36","bn":"আপনার সারা শরীর যদি আলোতে পূর্ণ হয় এবং একটুও অন্ধকার না থাকে তবে তা সম্পূর্ণ আলোময় হবে, ঠিক যেমন বাতির আলো আপনার উপর পড়লে আপনার শরীর আলোময় হয়।”"},{"heading":"ধর্ম-নেতাদের সম্বন্ধে হযরত ঈসা মসীহের মতামত","v":37,"ve":37,"vl":"37","bn":"ঈসা কথা বলা শেষ করলে পর একজন ফরীশী ঈসাকে খাওয়ার দাওয়াত করলেন। তখন ঈসা ভিতরে গিয়ে খেতে বসলেন।"},{"v":38,"ve":38,"vl":"38","bn":"সেই ফরীশী যখন দেখলেন খাওয়ার আগে ঈসা শরীয়ত মত হাত ধুলেন না তখন তিনি অবাক হলেন।"},{"v":39,"ve":39,"vl":"39","bn":"ঈসা তাঁকে বললেন, “তবে শুনুন, আপনারা, অর্থাৎ ফরীশীরা বাসন-কোসনের বাইরের দিকটা পরিষ্কার করে থাকেন, কিন্তু আপনাদের ভিতরটা লোভ ও খারাপীতে ভরা।"},{"v":40,"ve":40,"vl":"40","bn":"আপনারা মূর্খ! যিনি বাইরের দিক তৈরী করেছেন তিনি কি ভিতরের দিকও তৈরী করেন নি?"},{"v":41,"ve":41,"vl":"41","bn":"আপনাদের বাসন-কোসনের ভিতরে যা আছে তা-ই বরং ভিক্ষার মত দান করুন; দেখবেন, সব কিছুই আপনাদের কাছে পাক-সাফ হবে।"},{"v":42,"ve":42,"vl":"42","bn":"“ঘৃণ্য ফরীশীরা! আপনারা আল্লাহ্‌কে পুদিনা, তেজপাতা ও সব রকম শাকের দশ ভাগের এক ভাগ দিয়ে থাকেন, কিন্তু ন্যায়বিচার ও আল্লাহ্‌র প্রতি মহব্বতের দিকে মনোযোগ দেন না। আগেরগুলো পালন করবার সংগে সংগে পরেরগুলোও পালন করা আপনাদের উচিত।"},{"v":43,"ve":43,"vl":"43","bn":"“ঘৃণ্য ফরীশীরা! মজলিস-খানার প্রধান প্রধান আসনে বসতে এবং হাটে-বাজারে সম্মান পেতে আপনারা ভালবাসেন।"},{"v":44,"ve":44,"vl":"44","bn":"ঘৃণ্য আপনারা! আপনারা তো চিহ্ন না দেওয়া কবরের মত। লোকে না জেনে তার উপর দিয়ে হেঁটে যায়।”"},{"v":45,"ve":45,"vl":"45","bn":"তখন আলেমদের মধ্যে একজন ঈসাকে বললেন, “হুজুর, এই কথা বলে আপনি আমাদেরও অপমান করছেন।”"},{"v":46,"ve":46,"vl":"46","bn":"ঈসা বললেন, “ঘৃণ্য আলেমেরা! আপনারা লোকদের উপর ভারী বোঝা চাপিয়ে দিয়ে থাকেন, কিন্তু তাদের সাহায্য করবার জন্য নিজেরা একটা আংগুলও নাড়ান না।"},{"v":47,"ve":47,"vl":"47","bn":"“ঘৃণ্য আপনারা! নবীদের কবর আপনারা নতুন করে গেঁথে থাকেন, অথচ আপনাদের পূর্বপুরুষেরাই তো তাঁদের খুন করেছিল।"},{"v":48,"ve":48,"vl":"48","bn":"সেইজন্য আপনাদের পূর্বপুরুষদের কাজের সাক্ষী আপনারাই এবং তাদের সেই কাজ আপনারা মেনেও নিচ্ছেন। একদিকে তারা নবীদের খুন করেছে, অন্যদিকে আপনারা সেই নবীদের কবর গাঁথছেন।"},{"v":49,"ve":49,"vl":"49","bn":"এইজন্য আল্লাহ্‌ তাঁর উদ্দেশ্য অনুসারে এই কথা বলেছেন, ‘আমি তাদের কাছে নবীদের ও প্রেরিত্‌দের পাঠিয়ে দেব। তাদের মধ্যে কয়েকজনকে তারা খুন করবে এবং অন্যদের উপর জুলুম করবে।’"},{"v":50,"ve":50,"vl":"50","bn":"এর ফল হল, দুনিয়া সৃষ্টির সময় থেকে শুরু করে যতজন নবীকে খুন করা হয়েছে, তাঁদের রক্তের দায়ী হবে এই কালের লোকেরা।"},{"v":51,"ve":51,"vl":"51","bn":"জ্বী, আমি আপনাদের বলছি, হাবিলের খুন থেকে শুরু করে যে জাকারিয়াকে কোরবানগাহ্‌ এবং পবিত্র স্থানের মধ্যে হত্যা করা হয়েছিল সেই জাকারিয়ার খুন পর্যন্ত সমস্ত রক্তের দায়ী হবে এই কালের লোকেরা।"},{"v":52,"ve":52,"vl":"52","bn":"“ঘৃণ্য আলেমেরা! আপনারা জ্ঞানের চাবি নিয়ে গেছেন। নিজেরাও ভিতরে ঢোকেন নি এবং যারা ভিতরে ঢুকতে চাইছিল তাদের ও ঢুকতে দেন নি।”"},{"v":53,"ve":54,"vl":"53-54","bn":"তিনি সেই জায়গা ছেড়ে চলে যাবার সময়ে আলেমেরা এবং ফরীশীরা তাঁর বিরুদ্ধে শত্রুতা করবার জন্য উঠে-পড়ে লেগে গেলেন। নানা বিষয়ে প্রশ্ন জিজ্ঞাসা করে তাঁকে কথার ফাঁদে ফেলবার জন্য তাঁরা অপেক্ষা করতে লাগলেন।"}],"12":[{"heading":"সাহাবীদের শিক্ষাদান","v":1,"ve":1,"vl":"1","bn":"এর মধ্যে হাজার হাজার লোক এমনভাবে জমায়েত হল যে, তারা ঠেলাঠেলি করে একে অন্যের উপর পড়তে লাগল। তখন ঈসা প্রথমে তাঁর সাহাবীদের বললেন, “ফরীশীদের খামি থেকে সাবধান হও। সেই খামি হল তাঁদের ভণ্ডামি।"},{"v":2,"ve":2,"vl":"2","bn":"লুকানো সব কিছুই প্রকাশ পাবে এবং গোপন সব কিছুই জানানো হবে।"},{"v":3,"ve":3,"vl":"3","bn":"তোমরা অন্ধকারে যা বলেছ তা লোকে আলোতে শুনবে। ভিতরের ঘরে যা কানে কানে বলেছ তা ছাদের উপর থেকে প্রচার করা হবে।"},{"v":4,"ve":4,"vl":"4","bn":"“বন্ধুরা আমার, আমি তোমাদের বলছি, যারা শরীর ধ্বংস করবার পরে আর কিছুই করতে পারে না তাদের ভয় কোরো না।"},{"v":5,"ve":5,"vl":"5","bn":"কাকে ভয় করবে আমি তোমাদের তা বলে দিচ্ছি। তোমাদের হত্যা করবার পরে জাহান্নামে ফেলে দেবার ক্ষমতা যাঁর আছে তাঁকেই ভয় কোরো। জ্বী, আমি তোমাদের বলছি, তাঁকেই ভয় কোরো।"},{"v":6,"ve":6,"vl":"6","bn":"“পাঁচটা চড়াই পাখী কি সামান্য দামে বিক্রি হয় না? তবুও আল্লাহ্‌ সেগুলোর একটাকেও ভুলে যান না।"},{"v":7,"ve":7,"vl":"7","bn":"এমন কি, তোমাদের মাথার চুলগুলোও তাঁর গোণা আছে। ভয় কোরো না, অনেক অনেক চড়াই পাখীর চেয়েও তোমাদের মূল্য অনেক বেশী।"},{"v":8,"ve":8,"vl":"8","bn":"“আমি তোমাদের বলছি, যে কেউ লোকদের সামনে আমাকে স্বীকার করে ইব্‌ন্তেআদমও তাকে আল্লাহ্‌র ফেরেশতাদের সামনে স্বীকার করবেন।"},{"v":9,"ve":9,"vl":"9","bn":"কিন্তু যে কেউ আমাকে লোকদের সামনে অস্বীকার করে তাকে আল্লাহ্‌র ফেরেশতাদের সামনে অস্বীকার করা হবে।"},{"v":10,"ve":10,"vl":"10","bn":"ইব্‌ন্তেআদমের বিরুদ্ধে কেউ কোন কথা বললে তাকে মাফ করা হবে, কিন্তু যদি কেউ পাক-রূহের বিরুদ্ধে কুফরী করে তাকে মাফ করা হবে না।"},{"v":11,"ve":11,"vl":"11","bn":"লোকে তোমাদের যখন মজলিস-খানায় এবং শাসনকর্তা ও ক্ষমতাশালী লোকদের সামনে নিয়ে যাবে, তখন কিভাবে নিজের পক্ষে কথা বলবে বা কি জবাব দেবে সেই বিষয়ে চিনি-ত হোয়ো না।"},{"v":12,"ve":12,"vl":"12","bn":"কি বলতে হবে পাক-রূহ্‌ই সেই মুহূর্তে তা তোমাদের শিখিয়ে দেবেন।”"},{"heading":"মূর্খ ধনী লোকের গল্প","v":13,"ve":13,"vl":"13","bn":"ভিড়ের মধ্য থেকে একজন লোক ঈসাকে বলল, “হুজুর, আমাদের বাবা যে সম্পত্তি আমাদের জন্য রেখে গেছেন, আমার ভাইকে তা আমার সংগে ভাগ করে নিতে বলুন।”"},{"v":14,"ve":14,"vl":"14","bn":"ঈসা তাকে বললেন, “বিচার করবার বা আপনাদের মধ্যে সম্পত্তি ভাগ করে দেবার অধিকার আমাকে কে দিয়েছে?”"},{"v":15,"ve":15,"vl":"15","bn":"তারপর ঈসা লোকদের বললেন, “সাবধান! সব রকম লোভের হাত থেকে নিজেদের রক্ষা করুন, কারণ অনেক বিষয়-সম্পত্তি থাকাই মানুষের জীবনের সবচেয়ে দরকারী বিষয় নয়।”"},{"v":16,"ve":16,"vl":"16","bn":"এর পরে ঈসা লোকদের শিক্ষা দেবার জন্য এই উদাহরণ দিলেন: “কোন একজন ধনী লোকের জমিতে অনেক ফসল হয়েছিল।"},{"v":17,"ve":17,"vl":"17","bn":"এইজন্য সে মনে মনে বলতে লাগল, ‘এত ফসল রাখবার জায়গা তো আমার নেই; আমি এখন কি করি?"},{"v":18,"ve":18,"vl":"18","bn":"আচ্ছা, আমি একটা কাজ করব। আমার গোলাঘরগুলো ভেংগে ফেলে বড় বড় গোলাঘর তৈরী করব এবং আমার সমস্ত ফসল ও ধন সেখানে রাখব।"},{"v":19,"ve":19,"vl":"19","bn":"পরে আমি নিজেকে বলব, অনেক বছরের জন্য অনেক ভাল ভাল জিনিস জমা করা আছে। আরাম কর, খাওয়া-দাওয়া কর, আমোদ-আহ্‌লাদে দিন কাটাও।’"},{"v":20,"ve":20,"vl":"20","bn":"আল্লাহ্‌ কিন্তু তাকে বললেন, ‘ওহে বোকা, আজ রাতেই তোমাকে মরতে হবে। তাহলে যে সব জিনিস তুমি জমা করেছ সেগুলো কে ভোগ করবে?’ ”"},{"v":21,"ve":21,"vl":"21","bn":"শেষে ঈসা বললেন, “যে লোক নিজের জন্য ধন-সম্পত্তি জমা করে অথচ আল্লাহ্‌র চোখে ধনী নয়, তার অবস্থা ঐ রকমই হয়।”"},{"heading":"জীবনের সবচেয়ে দরকারী বিষয়ে শিক্ষা","v":22,"ve":22,"vl":"22","bn":"এর পর ঈসা তাঁর সাহাবীদের বললেন, “এইজন্যই আমি তোমাদের বলছি, কি খাবে বলে বেঁচে থাকবার বিষয়ে কিংবা কি পরবে বলে গায়ের বিষয়ে চিনি-ত হোয়ো না।"},{"v":23,"ve":23,"vl":"23","bn":"প্রাণটা কেবল খাওয়া-দাওয়ার ব্যাপার নয়, আর শরীরটা কেবল কাপড়-চোপড়ের ব্যাপার নয়।"},{"v":24,"ve":24,"vl":"24","bn":"কাকগুলোর দিকে চেয়ে দেখ, তারা বীজও বোনে না ফসলও কাটে না। তাদের গুদাম-ঘর বা গোলাঘরও নেই, তবুও আল্লাহ্‌ তাদের খাইয়ে থাকেন। তোমরা এই পাখীদের চেয়ে আরও বেশী মূল্যবান।"},{"v":25,"ve":25,"vl":"25","bn":"তোমাদের মধ্যে কে চিন্তা-ভাবনা করে নিজের আয়ু এক ঘণ্টা বাড়াতে পারে?"},{"v":26,"ve":26,"vl":"26","bn":"তা হলে এই সামান্য কাজটাও যদি তোমরা করতে না পার তবে অন্যান্য বিষয়ের জন্য কেন চিন্তা কর?"},{"v":27,"ve":27,"vl":"27","bn":"“ভেবে দেখ, ফুল কেমন করে বেড়ে ওঠে। তারা পরিশ্রমও করে না সুতাও কাটে না। কিন্তু আমি তোমাদের বলছি, সোলায়মান বাদশাহ্‌ এত জাঁকজমকের মধ্যে থেকেও এগুলোর একটারও মত নিজেকে সাজাতে পারেন নি।"},{"v":28,"ve":28,"vl":"28","bn":"মাঠে যে ঘাস আজ আছে আর কাল চুলায় ফেলে দেওয়া হবে, আল্লাহ্‌ তা যখন এইভাবে সাজান তখন ওহে অল্প বিশ্বাসীরা, তিনি যে তোমাদের সাজাবেন তা কত না নিশ্চয়!"},{"v":29,"ve":29,"vl":"29","bn":"কি খাওয়া-দাওয়া করবে ভেবে ব্যস্ত হয়ো না বা অস্থির হয়ো না।"},{"v":30,"ve":30,"vl":"30","bn":"এই দুনিয়ার অন্যান্য জাতিরা ঐ সব বিষয় নিয়ে ব্যস্ত হয়; এছাড়া তোমাদের পিতা তো জানেন যে, তোমাদের এগুলোর দরকার আছে।"},{"v":31,"ve":31,"vl":"31","bn":"তার চেয়ে বরং আল্লাহ্‌র রাজ্যের বিষয়ে ব্যস্ত হও, তা হলে এগুলোও তোমরা পাবে।"},{"v":32,"ve":32,"vl":"32","bn":"“হে আমার মেষের ছোট দল, ভয় কোরো না, কারণ তোমাদের পিতার ইচ্ছা এই যে, তাঁর রাজ্য তিনি তোমাদের দেবেন।"},{"v":33,"ve":33,"vl":"33","bn":"তোমাদের বিষয়-সম্পত্তি বিক্রি করে ভিক্ষা হিসাবে দান কর। যে টাকার থলি কখনও পুরানো হয় না তা-ই নিজেদের জন্য তৈরী কর, অর্থাৎ যে ধন চিরদিন টিকে থাকে তা-ই বেহেশতে জমা কর। সেখানে চোরও আসে না এবং পোকায়ও নষ্ট করে না।"},{"v":34,"ve":34,"vl":"34","bn":"তোমাদের ধন যেখানে থাকবে তোমাদের মনও সেখানে থাকবে।"},{"heading":"প্রস্তুত থাকবার বিষয়ে শিক্ষা","v":35,"ve":35,"vl":"35","bn":"“কোমরে কাপড় জড়িয়ে এবং তোমাদের বাতি জ্বালিয়ে নিয়ে প্রস্তুত থাক।"},{"v":36,"ve":36,"vl":"36","bn":"তোমরা এমন লোকদের মত হও যারা তাদের মালিকের জন্য অপেক্ষা করে থাকে, যেন তিনি বিয়ের মেজবানী থেকে ফিরে এসে দরজায় আঘাত করলেই তারা দরজা খুলে দিতে পারে।"},{"v":37,"ve":37,"vl":"37","bn":"মালিক যে গোলামদের জেগে থাকতে দেখবেন, ধন্য তারাই। আমি তোমাদের সত্যি বলছি, সেই মালিক কোমরে কাপড় জড়িয়ে নিয়ে তাদের বসাবেন এবং এসে নিজেই তাদের খাওয়াবেন।"},{"v":38,"ve":38,"vl":"38","bn":"ধন্য সেই সব গোলাম, যাদের তিনি এসে জেগে থাকতে দেখবেন, তা মাঝ রাতে হোক বা শেষ রাতে হোক।"},{"v":39,"ve":39,"vl":"39","bn":"এই কথা তোমরা জেনো, চোর কোন্‌ সময় আসবে তা যদি বাড়ীর কর্তা জানতেন তা হলে জেগে থাকতেন আর সেই চোরকে তাঁর ঘরে ঢুকতে দিতেন না।"},{"v":40,"ve":40,"vl":"40","bn":"সেইভাবে তোমরাও প্রস্তুত থাক, কারণ যে সময়ের কথা তোমরা চিন্তাও করবে না সেই সময়েই ইব্‌ন্তেআদম আসবেন।”"},{"v":41,"ve":41,"vl":"41","bn":"তখন পিতর বললেন, “হুজুর, আপনি এই শিক্ষা কি আমাদের দিচ্ছেন, না সকলকে দিচ্ছেন?”"},{"v":42,"ve":42,"vl":"42","bn":"জবাবে হযরত ঈসা বললেন, “সেই বিশ্বস্ত ও জ্ঞানী কর্মচারী কে, যাকে তার মালিক তাঁর গোলামদের ঠিক সময়ে খাবার ভাগ করে দেবার ভার দেবেন?"},{"v":43,"ve":43,"vl":"43","bn":"ধন্য সেই গোলাম, যাকে তাঁর মালিক এসে বিশ্বস্তভাবে কাজ করতে দেখবেন।"},{"v":44,"ve":44,"vl":"44","bn":"আমি তোমাদের সত্যিই বলছি, সেই মালিক তাঁকে তাঁর সমস্ত বিষয়-সম্পত্তির ভার দেবেন।"},{"v":45,"ve":45,"vl":"45","bn":"কিন্তু ধর, সেই গোলাম মনে মনে বলল, ‘আমার মালিক আসতে দেরি করছেন।’ সেই সুযোগে সে গোলাম ও বাঁদীদের মারধর করতে শুরু করল এবং খাওয়া-দাওয়া করবার পরে মদানো রস খেয়ে মাতাল হল।"},{"v":46,"ve":46,"vl":"46","bn":"তাহলে যেদিন ও যে সময়ের কথা সে চিন্তাও করবে না, সেই দিন ও সেই সময়েই তার মালিক এসে হাজির হবেন। তিনি তাঁকে কেটে দু’টুকরা করে কাফেরদের মধ্যে তার স্থান ঠিক করবেন।"},{"v":47,"ve":47,"vl":"47","bn":"“যে গোলাম তার মালিকের ইচ্ছা জেনেও প্রস্তুত থাকে নি কিংবা মালিক যা চান তা করে নি তাকে ভীষণভাবে মার খেতে হবে।"},{"v":48,"ve":48,"vl":"48","bn":"কিন্তু না জেনে যে শাস্তি পাবার কাজ করেছে তার অল্পই শাস্তি হবে। যাকে বেশী দেওয়া হয় তার কাছে থেকে বেশী দাবি করা হবে; আর লোকে যার কাছে বেশী রেখেছে তার কাছে তারা বেশীই চাইবে।"},{"v":49,"ve":49,"vl":"49","bn":"“আমি দুনিয়াতে আগুন জ্বালাতে এসেছি; যদি তা আগেই জ্বলে উঠত তবে কত না ভাল হত!"},{"v":50,"ve":50,"vl":"50","bn":"আমাকে একটা তরিকাবন্দী নিতে হবে, আর যতদিন পর্যন্ত তা না হয় ততদিন পর্যন্ত আমার দুঃখের শেষ নেই।"},{"v":51,"ve":51,"vl":"51","bn":"তোমাদের কি মনে হয় যে, আমি দুনিয়াতে শান্তি দিতে এসেছি? না, তা নয়। আমি শান্তি দিতে আসি নি বরং মানুষকে মানুষের বিরুদ্ধে দাঁড় করাতে এসেছি।"},{"v":52,"ve":52,"vl":"52","bn":"এখন থেকে এক বাড়ীর পাঁচজন ভাগ হয়ে যাবে, তিনজন দু’জনের বিরুদ্ধে আর দু’জন তিনজনের বিরুদ্ধে।"},{"v":53,"ve":53,"vl":"53","bn":"তারা এইভাবে ভাগ হয়ে যাবে- বাবা ছেলের বিরুদ্ধে ও ছেলে বাবার বিরুদ্ধে, মা মেয়ের বিরুদ্ধে ও মেয়ে মায়ের বিরুদ্ধে, শাশুড়ী বউয়ের বিরুদ্ধে ও বউ শাশুড়ীর বিরুদ্ধে।”"},{"v":54,"ve":54,"vl":"54","bn":"তারপর ঈসা লোকদের বললেন, “আপনারা পশ্চিম দিকে মেঘ করতে দেখলেই বলেন, ‘ঝড় আসছে,’ আর তা-ই হয়।"},{"v":55,"ve":55,"vl":"55","bn":"আবার দখিনা বাতাস বইতে দেখলে বলেন, ‘গরম পড়বে,’ আর তা-ই হয়।"},{"v":56,"ve":56,"vl":"56","bn":"আপনারা ভণ্ড! আপনারা দুনিয়া ও আকাশের চেহারার অর্থ বুঝতে পারেন, অথচ এ কেমন যে, আপনারা এখনকার সময়ে অর্থ বোঝেন না?"},{"v":57,"ve":57,"vl":"57","bn":"“যা ঠিক তা আপনারা নিজেরা ভেবে স্থির করেন না কেন?"},{"v":58,"ve":58,"vl":"58","bn":"আপনারা বিপক্ষের সংগে বিচারকের কাছে যাবার সময়ে পথেই তার সংগে একটা মীমাংসার চেষ্টা করবেন। তা না হলে সে আপনাকে বিচারকের কাছে টেনে নিয়ে যাবে। তখন বিচারক আপনাকে পুলিশের হাতে দেবে এবং পুলিশ আপনাকে জেলে দেবে।"},{"v":59,"ve":59,"vl":"59","bn":"আমি আপনাকে বলছি, শেষ পয়সাটা না দেওয়া পর্যন্ত আপনি কিছুতেই জেল থেকে ছাড়া পাবেন না।”"}],"13":[{"heading":"তওবার বিষয়ে শিক্ষা","v":1,"ve":1,"vl":"1","bn":"সেই সময় সেখানে উপস্থিত কয়েকজন লোক ঈসাকে গালীল প্রদেশের কয়েকজন লোকের বিষয়ে বলল। তারা বলল যে, রোমীয় শাসনকর্তা পীলাত এই গালীলীয়দের কেটে তাদের কোরবানী-করা পশুর রক্তের সংগে তাদের রক্তও মিশিয়েছিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"এই কথা শুনে ঈসা বললেন, “আপনাদের কি মনে হয় যে, সেই গালীলীয়রা ঐভাবে যন্ত্রণা ভোগ করেছে বলে তারা অন্য সব গালীলীয়দের চেয়ে বেশী গুনাহ্‌গার ছিল?"},{"v":3,"ve":3,"vl":"3","bn":"আমি আপনাদের বলছি, তা নয়, তবে তওবা না করলে আপনারাও সবাই বিনষ্ট হবেন।"},{"v":4,"ve":4,"vl":"4","bn":"শীলোহের উঁচু ঘরটা পড়ে যাওয়ার দরুন যে আঠারোজনের মৃত্যু হয়েছিল, আপনাদের কি মনে হয় যে, জেরুজালেমের বাকী লোকদের চেয়ে তাদের বেশী দোষ ছিল?"},{"v":5,"ve":5,"vl":"5","bn":"আমি আপনাদের বলছি, তা নয়, কিন্তু তওবা না করলে আপনারাও সবাই বিনষ্ট হবেন।”"},{"v":6,"ve":6,"vl":"6","bn":"তারপর শিক্ষা দেবার জন্য ঈসা এই কথা বললেন: “কোন একজন লোকের ফলের বাগানে একটা ডুমুর গাছ লাগানো হয়েছিল। একবার তিনি এসে ফলের তালাশ করলেন কিন্তু পেলেন না।"},{"v":7,"ve":7,"vl":"7","bn":"তখন তিনি মালীকে বললেন, ‘দেখ, তিন বছর ধরে এই ডুমুর গাছে আমি ফলের তালাশ করছি কিন্তু কিছুই পাচ্ছি না। এইজন্য তুমি গাছটা কেটে ফেল। কেন এটা শুধু শুধু জমি নষ্ট করবে?’"},{"v":8,"ve":8,"vl":"8","bn":"মালী জবাব দিল, ‘হুজুর, এই বছরও ওটা থাকতে দিন। আমি ওটার চারপাশে খুঁড়ে সার দেব।"},{"v":9,"ve":9,"vl":"9","bn":"তারপর যদি ফল ধরে তো ভাল তা না হলে আপনি ওটা কেটে ফেলবেন।’ ”"},{"heading":"একজন কুঁজা স্ত্রীলোককে সুস্থ করা","v":10,"ve":10,"vl":"10","bn":"কোন এক বিশ্রামবারে ঈসা একটা মজলিস-খানায় শিক্ষা দিচ্ছিলেন।"},{"v":11,"ve":11,"vl":"11","bn":"সেখানে এমন একজন স্ত্রীলোক ছিল যাকে একটা ভূত আঠারো বছর ধরে অসুখে ভোগাচ্ছিল। সে কুঁজা ছিল এবং একেবারেই সোজা হতে পারত না।"},{"v":12,"ve":12,"vl":"12","bn":"ঈসা তাকে দেখলেন এবং তাকে কাছে ডেকে বললেন, “মা, তোমার অসুখ থেকে তুমি মুক্ত হলে।”"},{"v":13,"ve":13,"vl":"13","bn":"এই কথা বলে ঈসা তার উপর হাত রাখলেন, আর তখনই সে সোজা হয়ে দাঁড়াল এবং আল্লাহ্‌র প্রশংসা করতে লাগল।"},{"v":14,"ve":14,"vl":"14","bn":"ঈসা বিশ্রামবারে সুস্থ করেছেন বলে মজলিস-খানার নেতা বিরক্ত হয়ে লোকদের বললেন, “কাজ করবার জন্য ছয় দিন তো আছেই। সেইজন্য বিশ্রামবারে না এসে ঐ ছয় দিনের মধ্যে এসে সুস্থ হয়ো।”"},{"v":15,"ve":15,"vl":"15","bn":"তখন হযরত ঈসা সেই নেতাকে বললেন, “আপনারা ভণ্ড! বিশ্রামবারে আপনারা সবাই কি আপনাদের বলদ বা গাধাকে গোয়াল ঘর থেকে খুলে পানি খাওয়াতে নিয়ে যান না?"},{"v":16,"ve":16,"vl":"16","bn":"তবে ইব্রাহিমের বংশের এই যে স্ত্রীলোকটিকে আঠারো বছর ধরে শয়তান বেঁধে রেখেছিল, সেই বাঁধন থেকে বিশ্রামবারে কি তাকে মুক্ত করা উচিত নয়?”"},{"v":17,"ve":17,"vl":"17","bn":"তিনি এই কথা বললে পর যারা তাঁর বিরুদ্ধে ছিল তারা সবাই লজ্জা পেল। কিন্তু অন্য লোকেরা তাঁর এই সমস্ত মহান কাজ দেখে আনন্দিত হল।"},{"heading":"সরিষা-দানা ও খামির গল্প","v":18,"ve":18,"vl":"18","bn":"এর পরে ঈসা বললেন, “আল্লাহ্‌র রাজ্য কিসের মত? কিসের সংগে আমি এর তুলনা করব?"},{"v":19,"ve":19,"vl":"19","bn":"আল্লাহ্‌র রাজ্য এমন একটা সরিষা-দানার মত যা একজন লোক নিয়ে তার বাগানে লাগাল। পরে চারা বেড়ে উঠে একটা গাছ হয়ে উঠল। তখন পাখীরা এসে তার ডালপালায় বাসা বাঁধল।”"},{"v":20,"ve":20,"vl":"20","bn":"ঈসা আবার বললেন, “কিসের সংগে আমি আল্লাহ্‌র রাজ্যের তুলনা করব?"},{"v":21,"ve":21,"vl":"21","bn":"আল্লাহ্‌র রাজ্য খামির মত। একজন স্ত্রীলোক তা নিয়ে আঠারো কেজি ময়দার সংগে মিশাল, ফলে সব ময়দাই ফেঁপে উঠল।”"},{"heading":"নাজাত পাবার বিষয়ে শিক্ষা","v":22,"ve":22,"vl":"22","bn":"গ্রামে গ্রামে ও শহরে শহরে শিক্ষা দিতে দিতে ঈসা জেরুজালেমের দিকে এগিয়ে চললেন।"},{"v":23,"ve":23,"vl":"23","bn":"একজন লোক তাঁকে জিজ্ঞাসা করল, “হুজুর, নাজাত কি কেবল অল্প লোকেই পাবে?” তখন ঈসা লোকদের বললেন,"},{"v":24,"ve":24,"vl":"24","bn":"“সরু দরজা দিয়ে ঢুকতে প্রাণপণে চেষ্টা করুন। আমি আপনাদের বলছি, অনেকেই ঢুকতে চেষ্টা করবে কিন্তু পারবে না।"},{"v":25,"ve":25,"vl":"25","bn":"ঘরের কর্তা যখন ওঠে দরজা বন্ধ করবেন তখন আপনারা বাইরে দাঁড়িয়ে দরজায় ঘা দিতে দিতে বলবেন, ‘হুজুর, আমাদের জন্য দরজা খুলে দিন।’ কিন্তু তিনি আপনাদের এই জবাব দেবেন, ‘তোমরা কোথা থেকে এসেছ আমি জানি না।’"},{"v":26,"ve":26,"vl":"26","bn":"তখন আপনারা বলবেন, ‘আমরা আপনার সংগে খাওয়া-দাওয়া করেছি, আর আপনি তো আমাদের রাস্তায় রাস্তায় শিক্ষা দিতেন।’"},{"v":27,"ve":27,"vl":"27","bn":"তখন তিনি বলবেন, ‘তোমরা কোথা থেকে এসেছ আমি জানি না। দুষ্ট লোকেরা, তোমরা সবাই আমার কাছ থেকে দূর হও।’"},{"v":28,"ve":28,"vl":"28","bn":"“যখন আপনারা দেখবেন, ইব্রাহিম, ইসহাক, ইয়াকুব ও নবীরা সবাই আল্লাহ্‌র রাজ্যের মধ্যে আছেন এবং আপনাদের বাইরে ফেলে দেওয়া হয়েছে, তখন আপনারা কান্নাকাটি করবেন ও যন্ত্রণায় দাঁতে দাঁত ঘষতে থাকবেন।"},{"v":29,"ve":29,"vl":"29","bn":"পূর্ব, পশ্চিম, উত্তর ও দক্ষিণ থেকে লোকেরা এসে আল্লাহ্‌র রাজ্যে খেতে বসবে।"},{"v":30,"ve":30,"vl":"30","bn":"যারা এখন শেষে আছে তাদের মধ্যে কেউ কেউ প্র্রথম হবে, আর যারা এখন প্রথমে আছে তাদের মধ্যে কেউ কেউ শেষে পড়বে।”"},{"heading":"জেরুজালেমের জন্য দুঃখ প্রকাশ","v":31,"ve":31,"vl":"31","bn":"সেই সময় কয়েকজন ফরীশী ঈসার কাছে এসে বললেন, “আপনি এখান থেকে চলে যান, কারণ হেরোদ আপনাকে হত্যা করতে চাইছেন।”"},{"v":32,"ve":32,"vl":"32","bn":"ঈসা তাদের বললেন, “আপনারা গিয়ে সেই শিয়ালকে বলুন, ‘আর কয়েকদিন আমি ভূত ছাড়াব এবং রোগীদের সুস্থ করব আর তারপর আমার কাজ শেষ করব।"},{"v":33,"ve":33,"vl":"33","bn":"যাহোক, আর কয়েকদিন পরে আমাকে চলে যেতে হবে, কারণ এক জেরুজালেম ছাড়া আর কোথাও কোন নবীর মৃত্যু হতে পারে কি?"},{"v":34,"ve":34,"vl":"34","bn":"“জেরুজালেম, হায় জেরুজালেম! নবীদের তুমি খুন করে থাক এবং তোমার কাছে যাঁদের পাঠানো হয় তাঁদের পাথর মেরে থাক। মুরগী যেমন নিজের বাচ্চাদের তার ডানার নীচে জড়ো করে ঠিক তেমনি আমি কতবার তোমার লোকদের আমার কাছে জড়ো করতে চেয়েছি, কিন্তু তোমরা রাজী হও নি।"},{"v":35,"ve":35,"vl":"35","bn":"দেখ, তোমাদের বাড়ী তোমাদের সামনে খালি হয়ে পড়ে থাকবে। আমি তোমাদের বলছি, যতদিন না তোমরা বলবে, ‘যিনি মাবুদের নামে আসছেন তাঁর প্রশংসা হোক,’ ততদিন তোমরা আর আমাকে দেখতে পাবে না।”"}],"14":[{"heading":"একজন ফরীশী নেতার বাড়ীতে হযরত ঈসা মসীহ্‌","v":1,"ve":1,"vl":"1","bn":"এক বিশ্রামবারে ঈসা একজন ফরীশী নেতার বাড়ীতে খেতে গেলেন। ফরীশীরা খুব ভাল করেই ঈসাকে লক্ষ্য করছিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"ঈসার সামনে একজন রোগী ছিল যার সমস্ত শরীরটা শোথ রোগে ফুলে গিয়েছিল।"},{"v":3,"ve":3,"vl":"3","bn":"ঈসা আলেম ও ফরীশীদের জিজ্ঞাসা করলেন, “মূসার শরীয়ত মতে বিশ্রামবারে কি কাউকে সুস্থ করা উচিত?”"},{"v":4,"ve":4,"vl":"4","bn":"ধর্ম-নেতারা চুপ করে রইলেন। তখন ঈসা লোকটির গায়ে হাত দিয়ে তাকে ধরে সুস্থ করে বিদায় দিলেন।"},{"v":5,"ve":5,"vl":"5","bn":"তারপর তিনি সেই ধর্ম-নেতাদের বললেন, “বিশ্রামবারে যদি আপনাদের কারও ছেলে বা বলদ কূয়ায় পড়ে যায় তবে আপনারা কি তাকে তখনই তোলেন না?”"},{"v":6,"ve":6,"vl":"6","bn":"কিন্তু সেই ধর্ম-নেতারা এর জবাব দিতে পারলেন না।"},{"v":7,"ve":7,"vl":"7","bn":"যে লোকদের দাওয়াত করা হয়েছিল, তারা কিভাবে সম্মানের জায়গাগুলো বেছে নিচ্ছে তা দেখে ঈসা তাদের শিক্ষা দেবার জন্য এই কথা বললেন,"},{"v":8,"ve":8,"vl":"8","bn":"“যখন কেউ আপনাকে বিয়ের ভোজে দাওয়াত করে তখন আপনি সম্মানের জায়গায় গিয়ে বসবেন না, কারণ আপনার চেয়ে হয়তো আরও সম্মানিত কাউকে দাওয়াত করা হয়েছে।"},{"v":9,"ve":9,"vl":"9","bn":"তাহলে যিনি আপনাকে ও তাঁকে দাওয়াত করেছেন তিনি এসে আপনাকে বলবেন, ‘এই জায়গাটা ওনাকে ছেড়ে দিন।’ তখন তো আপনি লজ্জা পেয়ে সবচেয়ে নীচু জায়গায় বসতে যাবেন।"},{"v":10,"ve":10,"vl":"10","bn":"আপনি যখন দাওয়াত পাবেন তখন বরং সবচেয়ে নীচু জায়গায় গিয়ে বসবেন। তাহলে দাওয়াত-কর্তা এসে আপনাকে বলবেন, ‘বন্ধু, আরও ভাল জায়গায় গিয়ে বসুন।’ তখন অন্য সব মেহমানদের সামনে আপনি সম্মান পাবেন।"},{"v":11,"ve":11,"vl":"11","bn":"যে নিজেকে উঁচু করে তাকে নীচু করা হবে, আর যে নিজেকে নীচু করে তাকে উঁচু করা হবে।”"},{"v":12,"ve":12,"vl":"12","bn":"যিনি তাঁকে দাওয়াত করেছিলেন পরে ঈসা তাঁকে বললেন, “যখন আপনি খাওয়া-দাওয়ার আয়োজন করবেন বা মেজবানী দেবেন তখন আপনার বন্ধুদের বা ভাইদের কিংবা আত্মীয়-স্বজনদের বা ধনী প্রতিবেশীদের দাওয়াত করবেন না। তা করলে হয়ত তাঁরাও এর বদলে আপনাকে দাওয়াত করবেন আর এইভাবে আপনার দাওয়াত শোধ হয়ে যাবে।"},{"v":13,"ve":13,"vl":"13","bn":"কিন্তু আপনি যখন মেজবানী দেবেন তখন গরীব, নুলা, খোঁড়া এবং অন্ধদের ডাকবেন।"},{"v":14,"ve":14,"vl":"14","bn":"তাতে আপনি আল্লাহ্‌র দোয়া পাবেন, কারণ তারা আপনার সেই দাওয়াতের শোধ দিতে পারবে না। যখন মৃত্যু থেকে ধার্মিক লোকদের জীবিত করা হবে তখন আপনি এর শোধ পাবেন।”"},{"heading":"বিরাট মেজবানীর গল্প","v":15,"ve":15,"vl":"15","bn":"যারা খেতে বসেছিল তাদের মধ্যে একজন এই কথা শুনে ঈসাকে বলল, “যিনি আল্লাহ্‌র রাজ্যে খেতে বসবেন তিনি ধন্য।”"},{"v":16,"ve":16,"vl":"16","bn":"ঈসা বললেন, “কোন একজন লোক একটা বড় মেজবানী দিলেন এবং অনেককে দাওয়াত দিলেন।"},{"v":17,"ve":17,"vl":"17","bn":"মেজবানীর সময় হলে পর তিনি তাঁর গোলামকে দিয়ে যে লোকদের দাওয়াত করা হয়েছিল, তাদের বলে পাঠালেন, ‘আসুন, এখন সবই প্রস্তুত হয়েছে।’"},{"v":18,"ve":18,"vl":"18","bn":"কিন্তু তারা সবাই একজনের পর একজন অজুহাত দেখাতে লাগল। প্রথম জন সেই গোলামকে বলল, ‘আমি কিছু জমি কিনেছি, আমাকে গিয়ে তা দেখতে হবে। দয়া করে আমাকে মাফ কর।’"},{"v":19,"ve":19,"vl":"19","bn":"আর একজন বলল, ‘আমি পাঁচ জোড়া বলদ কিনেছি, সেগুলো পরীক্ষা করতে যাচ্ছি। দয়া করে আমাকে মাফ কর।’"},{"v":20,"ve":20,"vl":"20","bn":"অন্য আর একজন বলল, ‘আমি বিয়ে করেছি, এইজন্য যেতে পারছি না।’"},{"v":21,"ve":21,"vl":"21","bn":"“সেই গোলাম ফিরে গিয়ে তার মালিককে এই সব কথা জানাল। তাতে বাড়ীর কর্তা রাগ করে তাঁর গোলামকে বললেন, ‘তুমি তাড়াতাড়ি শহরের রাস্তায় রাস্তায় ও গলিতে গলিতে যাও এবং গরীব, নুলা, অন্ধ ও খোঁড়াদের এখানে নিয়ে এস।’"},{"v":22,"ve":22,"vl":"22","bn":"এই সব করবার পরে সেই গোলাম বলল, ‘হুজুর, আপনার হুকুম মতই সব করা হয়েছে, কিন্তু এখনও জায়গা আছে।’"},{"v":23,"ve":23,"vl":"23","bn":"এতে কর্তা গোলামকে বললেন, ‘শহরের বাইরে রাস্তায় রাস্তায় ও পথে পথে যাও এবং এখানে আসবার জন্য লোকদের জোর কর, যেন আমার বাড়ী ভরে যায়।"},{"v":24,"ve":24,"vl":"24","bn":"আমি তোমাদের বলছি, যাদের দাওয়াত করা হয়েছিল তাদের কেউই আমার এই মেজবানী খেতে পাবে না।’ ”"},{"heading":"উম্মত হবার বিষয়ে শিক্ষা","v":25,"ve":25,"vl":"25","bn":"ঈসার সংগে সংগে অনেক লোক যাচ্ছিল। ঈসা সেই লোকদের দিকে ফিরে বললেন,"},{"v":26,"ve":26,"vl":"26","bn":"“যে আমার কাছে আসবে সে যেন নিজের পিতা-মাতা, স্ত্রী ও ছেলেমেয়ে, ভাই-বোন, এমন কি, নিজেকে পর্যন্ত আমার চেয়ে কম প্রিয় মনে করে। তা না হলে সে আমার উম্মত হতে পারে না।"},{"v":27,"ve":27,"vl":"27","bn":"যে লোক নিজের ক্রুশ বয়ে নিয়ে আমার পিছনে না আসে সে আমার উম্মত হতে পারে না।"},{"v":28,"ve":28,"vl":"28","bn":"“আপনাদের মধ্যে যদি কেউ একটা উঁচু ঘর তৈরী করতে চায় তবে সে আগে বসে খরচের হিসাব করে। সে দেখতে চায়, ওটা শেষ করবার জন্য তার যথেষ্ট টাকা আছে কি না।"},{"v":29,"ve":29,"vl":"29","bn":"তা না হলে সে ভিত্তি গাঁথবার পরে যদি সেই উঁচু ঘরটা শেষ করতে না পারে, তবে যারা সেটা দেখবে তারা সবাই তাকে ঠাট্টা করবে।"},{"v":30,"ve":30,"vl":"30","bn":"তারা বলবে ‘লোকটা গাঁথতে শুরু করেছিল কিন্তু শেষ করতে পারল না।’"},{"v":31,"ve":31,"vl":"31","bn":"“যদি একজন বাদশাহ্‌ অন্য আর একজন বাদশাহ্‌র বিরুদ্ধে যুদ্ধ করতে যান তবে তিনি প্রথমে বসে চিন্তা করবেন, ‘বিশ হাজার সৈন্য নিয়ে যিনি আমার বিরুদ্ধে যুদ্ধ করতে আসছেন, মাত্র দশ হাজার সৈন্য নিয়ে আমি তাঁকে বাধা দিতে পারব কি?’"},{"v":32,"ve":32,"vl":"32","bn":"যদি তিনি তা না পারেন তবে সেই অন্য বাদশাহ্‌ দূরে থাকতেই লোক পাঠিয়ে তিনি তাঁর সংগে সন্ধির কথা আলাপ করবেন।”"},{"v":33,"ve":33,"vl":"33","bn":"শেষে ঈসা বললেন, “সেইভাবে আপনাদের মধ্যে যদি কেউ ভেবে-চিন্তে তার সব কিছু ছেড়ে না আসে তবে সে আমার উম্মত হতে পারে না।"},{"v":34,"ve":34,"vl":"34","bn":"“লবণ ভাল জিনিস, কিন্তু যদি তার স্বাদ নষ্ট হয়ে যায় তবে তা আবার কি করে নোন্‌তা করা যাবে?"},{"v":35,"ve":35,"vl":"35","bn":"তখন তা জমির জন্যও উপযুক্ত হয় না, সারের গাদার জন্যও উপযুক্ত হয় না; লোকে তা ফেলে দেয়। যার শুনবার কান আছে, সে শুনুক।”"}],"15":[{"heading":"হারানো ভেড়ার গল্প","v":1,"ve":1,"vl":"1","bn":"তখন অনেক খাজনা-আদায়কারী ও খারাপ লোকেরা ঈসার কথা শুনবার জন্য তাঁর কাছে আসল।"},{"v":2,"ve":2,"vl":"2","bn":"এতে ফরীশীরা ও আলেমেরা এই বলে বিরক্তি প্রকাশ করতে লাগলেন, “এই লোকটা খারাপ লোকদের সংগে মেলামেশা ও খাওয়া-দাওয়া করে।”"},{"v":3,"ve":3,"vl":"3","bn":"তখন ঈসা তাঁদের শিক্ষা দেবার জন্য এই কথা বললেন:"},{"v":4,"ve":4,"vl":"4","bn":"“মনে করুন, আপনাদের মধ্যে কোন একজনের একশোটা ভেড়া আছে। যদি সেই ভেড়াগুলোর মধ্যে একটা হারিয়ে যায়, তবে কি সে নিরানব্বইটা মাঠে ছেড়ে দিয়ে সেই একটাকে খুঁজে না পাওয়া পর্যন্ত তার তালাশ করে না?"},{"v":5,"ve":5,"vl":"5","bn":"সেটা খুঁজে পেলে পর সে খুশী হয়ে তাকে কাঁধে তুলে নেয়।"},{"v":6,"ve":6,"vl":"6","bn":"পরে বাড়ী গিয়ে তার বন্ধু-বান্ধব ও প্রতিবেশীকে ডেকে বলে, ‘আমার সংগে আনন্দ কর, কারণ আমার হারানো ভেড়াটা আমি খুঁজে পেয়েছি।’"},{"v":7,"ve":7,"vl":"7","bn":"আমি আপনাদের বলছি, ঠিক সেইভাবে যারা তওবা করবার দরকার মনে করে না তেমন নিরানব্বইজন ধার্মিক লোকের চেয়ে বরং একজন গুনাহ্‌গার তওবা করলে বেহেশতে আরও বেশী আনন্দ হয়।"},{"heading":"হারানো টাকার গল্প","v":8,"ve":8,"vl":"8","bn":"“আবার ধরুন, একজন স্ত্রীলোকের দশটা রূপার টাকা আছে। যদি সে তার মধ্য থেকে একটা হারিয়ে ফেলে, তবে বাতি জ্বেলে ঘর ঝাড় দিয়ে তা না পাওয়া পর্যন্ত কি ভাল করে তালাশ করতে থাকে না?"},{"v":9,"ve":9,"vl":"9","bn":"যখন সে তা খুঁজে পায় তখন তার বন্ধু-বান্ধব ও প্রতিবেশীদের ডেকে বলে, ‘আমার সংগে আনন্দ কর, কারণ যে টাকাটা হারিয়ে গিয়েছিল তা পেয়েছি।’"},{"v":10,"ve":10,"vl":"10","bn":"আমি আপনাদের বলছি, ঠিক সেইভাবে একজন গুনাহ্‌গার তওবা করলে আল্লাহ্‌র ফেরেশতাদের মধ্যে আনন্দ হয়।”"},{"heading":"হারানো ছেলের গল্প","v":11,"ve":11,"vl":"11","bn":"তারপর ঈসা বললেন, “একজন লোকের দু’টি ছেলে ছিল।"},{"v":12,"ve":12,"vl":"12","bn":"ছোট ছেলেটি তার বাবাকে বলল, ‘আব্বা, আমার ভাগের সম্পত্তি আমাকে দিন।’ তাতে সেই লোক তাঁর দুই ছেলের মধ্যে সম্পত্তি ভাগ করে দিলেন।"},{"v":13,"ve":13,"vl":"13","bn":"কিছু দিন পরে ছোট ছেলেটি তার সম্পত্তি বিক্রি করে টাকা-পয়সা নিয়ে দূর দেশে চলে গেল। সেখানে সে খারাপ ভাবে জীবন কাটিয়ে তার সব টাকা-পয়সা উড়িয়ে দিল।"},{"v":14,"ve":14,"vl":"14","bn":"যখন সে তার সব টাকা খরচ করে ফেলল তখন সেই দেশের সমস্ত জায়গায় ভীষণ দুর্ভিক্ষ দেখা দিল। তাতে সে অভাবে পড়ল।"},{"v":15,"ve":15,"vl":"15","bn":"তখন সে গিয়ে সেই দেশের একজন লোকের কাছে চাকরি চাইল। লোকটি তাকে তার শূকর চরাতে মাঠে পাঠিয়ে দিল।"},{"v":16,"ve":16,"vl":"16","bn":"শূকরে যে শুঁটি খেত সে তা খেয়ে পেট ভরাতে চাইত, কিন্তু কেউ তাকে তাও দিত না।"},{"v":17,"ve":17,"vl":"17","bn":"“পরে একদিন তার চেতনা হল। তখন সে বলল, ‘আমার বাবার কত মজুর কত বেশী খাবার পাচ্ছে, অথচ আমি এখানে খিদেতে মরছি।"},{"v":18,"ve":18,"vl":"18","bn":"আমি উঠে আমার বাবার কাছে গিয়ে বলব, আব্বা, আল্লাহ্‌ ও তোমার বিরুদ্ধে আমি গুনাহ্‌ করেছি।"},{"v":19,"ve":19,"vl":"19","bn":"কেউ যে আর আমাকে তোমার ছেলে বলে ডাকে তার যোগ্য আমি নই। তোমার মজুরদের একজনের মত করে আমাকে রাখ।’"},{"v":20,"ve":20,"vl":"20","bn":"“এই বলে সে উঠে তার বাবার কাছে গেল। সে দূরে থাকতেই তাকে দেখে তার বাবার খুব মমতা হল। তিনি দৌড়ে গিয়ে তাকে জড়িয়ে ধরে চুমু দিলেন।"},{"v":21,"ve":21,"vl":"21","bn":"তখন ছেলেটি বলল, ‘আব্বা, আমি আল্লাহ্‌ ও তোমার বিরুদ্ধে গুনাহ্‌ করেছি। কেউ যে আর আমাকে তোমার ছেলে বলে ডাকে তার যোগ্য আমি নই।’"},{"v":22,"ve":22,"vl":"22","bn":"“কিন্তু তার বাবা তার গোলামদের বললেন, ‘তাড়াতাড়ি করে সবচেয়ে ভাল জুব্বাটা এনে ওকে পরিয়ে দাও। ওর হাতে আংটি ও পায়ে জুতা দাও,"},{"v":23,"ve":23,"vl":"23","bn":"আর মোটাসোটা বাছুরটা এনে জবাই কর। এস, আমরা খাওয়া-দাওয়া করে আনন্দ করি,"},{"v":24,"ve":24,"vl":"24","bn":"কারণ আমার এই ছেলেটা মরে গিয়েছিল কিন্তু আবার বেঁচে উঠেছে; হারিয়ে গিয়েছিল পাওয়া গিয়েছে।’ তারপর তারা আমোদ-প্রমোদ করতে লাগল।"},{"v":25,"ve":25,"vl":"25","bn":"“সেই সময় তাঁর বড় ছেলেটি মাঠে ছিল। বাড়ীর কাছে এসে সে নাচ ও গান-বাজনার শব্দ শুনতে পেল।"},{"v":26,"ve":26,"vl":"26","bn":"তখন সে একজন চাকরকে ডেকে জিজ্ঞাসা করল, ‘এসব কি হচ্ছে?’"},{"v":27,"ve":27,"vl":"27","bn":"“চাকরটি তাকে জবাব দিল, ‘আপনার ভাই এসেছে। আপনার বাবা তাকে সুস্থ অবস্থায় ফিরে পেয়েছেন বলে মোটাসোটা বাছুরটা জবাই করেছেন।’"},{"v":28,"ve":28,"vl":"28","bn":"“তখন বড় ছেলেটি রাগ করে ভিতরে যেতে চাইল না। এতে তার বাবা বের হয়ে এসে তাকে ভিতরে যাবার জন্য সাধাসাধি করতে লাগলেন।"},{"v":29,"ve":29,"vl":"29","bn":"সে তার বাবাকে বলল, ‘দেখ, এত বছর ধরে আমি তোমার সেবা-যত্ন করে আসছি; একবারও আমি তোমার অবাধ্য হই নি। তবুও আমার বন্ধুদের সংগে আমোদ-প্রমোদ করবার জন্য তুমি কখনও আমাকে ছাগলের একটা বাচ্চা পর্যন্ত দাও নি।"},{"v":30,"ve":30,"vl":"30","bn":"কিন্তু তোমার এই ছেলে, যে বেশ্যাদের পিছনে তোমার টাকা-পয়সা উড়িয়ে দিয়েছে, সে যখন আসল তুমি তার জন্য মোটাসোটা বাছুরটা জবাই করলে।’"},{"v":31,"ve":31,"vl":"31","bn":"“তার বাবা তাকে বললেন, ‘বাবা, তুমি তো সব সময় আমার সংগে সংগে আছ। আমার যা কিছু আছে সবই তো তোমার।"},{"v":32,"ve":32,"vl":"32","bn":"খুশী হয়ে আমাদের আমোদ-প্রমোদ করা উচিত, কারণ তোমার এই ভাই মরে গিয়েছিল আবার বেঁচে উঠেছে; হারিয়ে গিয়েছিল আবার তাকে পাওয়া গেছে।’ ”"}],"16":[{"heading":"একজন অসৎ কর্মচারী","v":1,"ve":1,"vl":"1","bn":"ঈসা তাঁর সাহাবীদের বললেন, “কোন এক ধনী লোকের প্রধান কর্মচারীকে এই বলে দোষ দেওয়া হল যে, সে তার মালিকের ধন-সম্পত্তি নষ্ট করছে।"},{"v":2,"ve":2,"vl":"2","bn":"তখন ধনী লোকটি তাকে ডেকে জিজ্ঞাসা করলেন, ‘তোমার সম্বন্ধে আমি এ কি শুনছি? তোমার কাজের হিসাব দাও, কারণ তুমি আর প্রধান কর্মচারী থাকতে পারবে না।’"},{"v":3,"ve":3,"vl":"3","bn":"“তখন সেই কর্মচারী মনে মনে বলল, ‘আমি এখন কি করি? আমার মালিক তো আমাকে চাকরি থেকে ছাড়িয়ে দিচ্ছেন। মাটি কাটবার শক্তি আমার নেই, আবার ভিক্ষা করতেও লজ্জা লাগে।"},{"v":4,"ve":4,"vl":"4","bn":"যা হোক, চাকরি থেকে বরখাস- হলে পর লোকে যাতে আমাকে তাদের বাড়ীতে থাকতে দেয় সেইজন্য আমি কি করব তা আমি জানি।’"},{"v":5,"ve":5,"vl":"5","bn":"“এই বলে যারা তার মালিকের কাছে ধার করেছিল তাদের প্রত্যেককে সে ডাকল। তারপর সে প্রথম জনকে জিজ্ঞাসা করল, ‘আমার মালিকের কাছে তোমার ধার কত?’"},{"v":6,"ve":6,"vl":"6","bn":"সে বলল, ‘দু’হাজার চারশো লিটার তেল।’ সেই কর্মচারী তাকে বলল, ‘যে কাগজে তোমার ধারের কথা লেখা আছে সেটা নাও এবং শীঘ্র বসে এক হাজার দু’শো লেখ।’"},{"v":7,"ve":7,"vl":"7","bn":"সেই কর্মচারী তারপর আর একজনকে বলল, ‘তোমার ধার কত?’ সে বলল, ‘আঠারো টন গম।’ কর্মচারীটি বলল, ‘তোমার কাগজে সাড়ে চৌদ্দ টন লেখ।’"},{"v":8,"ve":8,"vl":"8","bn":"সেই কর্মচারী অসৎ হলেও বুদ্ধি করে কাজ করল বলে মালিক তার প্রশংসা করলেন। এতে বুঝা যায় যে, এই দুনিয়ার লোকেরা নিজেদের মত লোকদের সংগে আচার-ব্যবহারে নূরের রাজ্যের লোকদের চেয়ে বেশী বুদ্ধিমান।"},{"v":9,"ve":9,"vl":"9","bn":"আমি তোমাদের বলছি, এই খারাপ দুনিয়ার ধন দ্বারা লোকদের সংগে বন্ধুত্ব কর, যেন সেই ধন ফুরিয়ে গেলে পর চিরকালের থাকবার জায়গায় তোমাদের গ্রহণ করা হয়।"},{"v":10,"ve":10,"vl":"10","bn":"সামান্য ব্যাপারে যে বিশ্বাসযোগ্য সে বড় ব্যাপারেও বিশ্বাসযোগ্য হয়। সামান্য ব্যাপারে যাকে বিশ্বাস করা যায় না তাকে বড় ব্যাপারেও বিশ্বাস করা যায় না।"},{"v":11,"ve":11,"vl":"11","bn":"এই দুনিয়ার ধন-সম্পত্তির ব্যাপারে যদি তোমাদের বিশ্বাস করা না যায় তবে কে তোমাদের বিশ্বাস করে আসল ধন দেবে?"},{"v":12,"ve":12,"vl":"12","bn":"অন্যের অধিকারে যা আছে তা ব্যবহার করবার ব্যাপারে যদি তোমাদের বিশ্বাস করা না যায়, তবে তোমাদের নিজেদের অধিকারের জন্য কেউ কি তোমাদের কিছু দেবে?"},{"v":13,"ve":13,"vl":"13","bn":"“কোন গোলাম দু’জন কর্তার সেবা করতে পারে না, কারণ সে একজনকে ঘৃণা করবে ও অন্যজনকে ভালবাসবে, কিংবা সে একজনের প্রতি মনোযোগ দেবে ও অন্যজনকে তুচ্ছ করবে। আল্লাহ্‌ ও ধন-সম্পত্তি এই দু’য়েরই সেবা তোমরা একসংগে করতে পার না।”"},{"v":14,"ve":14,"vl":"14","bn":"এই সব কথা শুনে ফরীশীরা ঈসাকে ঠাট্টা করতে লাগলেন, কারণ তারা টাকা-পয়সা বেশী ভালবাসতেন।"},{"v":15,"ve":15,"vl":"15","bn":"তখন ঈসা তাঁদের বললেন, “আপনারা লোকদের সামনে নিজেদের ধার্মিক দেখিয়ে থাকেন, কিন্তু আল্লাহ্‌ আপনাদের মনের অবস্থা জানেন। মানুষ যা সম্মানিত মনে করে আল্লাহ্‌র চোখে তা ঘৃণার যোগ্য।"},{"v":16,"ve":16,"vl":"16","bn":"“ইয়াহিয়ার সময় পর্যন্ত তৌরাত শরীফ এবং নবীদের কিতাব চলত। তারপর থেকে আল্লাহ্‌র রাজ্যের সুসংবাদ তবলিগ করা হচ্ছে এবং সবাই আগ্রহী হয়ে জোরের সংগে সেই রাজ্যে ঢুকছে।"},{"v":17,"ve":17,"vl":"17","bn":"তবে তৌরাত শরীফের একটা বিন্দু বাদ পড়বার চেয়ে বরং আসমান ও জমীন শেষ হওয়া সহজ।"},{"v":18,"ve":18,"vl":"18","bn":"“যে কেউ নিজের স্ত্রীকে ছেড়ে দিয়ে আর একজনকে বিয়ে করে সে জেনা করে। স্বামী যাকে ছেড়ে দিয়েছে সেই রকম স্ত্রীকে যে বিয়ে করে সেও জেনা করে।"},{"heading":"লাসার ও একজন ধনী লোক","v":19,"ve":19,"vl":"19","bn":"“একজন ধনী লোক ছিল। সে বেগুনে কাপড় ও অন্যান্য দামী দামী কাপড়-চোপড় পরত। প্রত্যেক দিন খুব জাঁকজমকের সংগে সে আমোদ-প্রমোদ করত।"},{"v":20,"ve":20,"vl":"20","bn":"সেই ধনী লোকের দরজার কাছে লাসার নামে একজন ভিখারীকে প্রায়ই এনে রাখা হত। লাসারের সারা গায়ে ঘা ছিল।"},{"v":21,"ve":21,"vl":"21","bn":"সেই ধনী লোকের টেবিল থেকে যে খাবার পড়ত তা-ই খেয়ে সে পেট ভরাতে চাইত, আর কুকুরেরা তার ঘা চেটে দিত।"},{"v":22,"ve":22,"vl":"22","bn":"“একদিন সেই ভিখারীটি মারা গেল। তখন ফেরেশতারা এসে তাকে নবী ইব্রাহিমের কাছে নিয়ে গেলেন। তারপর একদিন সেই ধনী লোকটিও মারা গেল এবং তাকে দাফন করা হল।"},{"v":23,"ve":23,"vl":"23","bn":"কবরে খুব যন্ত্রণার মধ্যে থেকে সে উপরের দিকে তাকাল এবং দূর থেকে ইব্রাহিম ও তাঁর পাশে লাসারকে দেখতে পেল।"},{"v":24,"ve":24,"vl":"24","bn":"তখন সে চিৎকার করে বলল, ‘পিতা ইব্রাহিম, আমাকে দয়া করুন। লাসারকে পাঠিয়ে দিন যেন সে তার আংগুলের আগাটা পানিতে ডুবিয়ে আমার জিভ্‌ ঠাণ্ডা করে। এই আগুনের মধ্যে আমি বড়ই কষ্ট পাচ্ছি।’"},{"v":25,"ve":25,"vl":"25","bn":"“কিন্তু ইব্রাহিম বললেন, ‘মনে করে দেখ, তুমি যখন বেঁচে ছিলে তখন কত সুখ ভোগ করেছ আর লাসার কত কষ্ট ভোগ করেছে। কিন্তু এখন সে এখানে সান্ত্বনা পাচ্ছে আর তুমি কষ্ট পাচ্ছ।"},{"v":26,"ve":26,"vl":"26","bn":"এছাড়া তোমাদের ও আমাদের মধ্যে এমন একটা বিরাট ফাঁক রয়েছে যাতে ইচ্ছা করলেও কেউ এখান থেকে পার হয়ে তোমাদের কাছে যেতে না পারে এবং ওখান থেকে পার হয়ে আমাদের কাছে আসতে না পারে।’"},{"v":27,"ve":27,"vl":"27","bn":"“তখন সেই ধনী লোকটি বলল, ‘তাহলে পিতা, দয়া করে লাসারকে আমার পিতার বাড়ীতে পাঠিয়ে দিন,"},{"v":28,"ve":28,"vl":"28","bn":"যেন সে আমার পাঁচটি ভাইকে সাবধান করতে পারে; তা না হলে তারাও তো এই যন্ত্রণার জায়গায় আসবে।’"},{"v":29,"ve":29,"vl":"29","bn":"“কিন্তু ইব্রাহিম বললেন, ‘মূসা ও নবীদের লেখা কিতাব তো তাদের কাছে আছে। ওরা তাঁদের কথায় মনোযোগ দিক।’"},{"v":30,"ve":30,"vl":"30","bn":"“সেই ধনী লোকটি বলল, ‘না, না, পিতা ইব্রাহিম, মৃতদের মধ্য থেকে কেউ তাদের কাছে গেলে তারা তওবা করবে।’"},{"v":31,"ve":31,"vl":"31","bn":"“তখন ইব্রাহিম বললেন, ‘মূসা ও নবীদের কথা যদি তারা না শোনে তবে মৃতদের মধ্য থেকে কেউ উঠলেও তারা বিশ্বাস করবে না।”"}],"17":[{"heading":"গুনাহ্‌ ও বিশ্বাস সম্বন্ধে শিক্ষা","v":1,"ve":1,"vl":"1","bn":"ঈসা তাঁর সাহাবীদের বললেন, “গুনাহের পথে নিয়ে যাবার জন্য উসকানি আসবেই আসবে, কিন্তু ঘৃণ্য সেই লোক, যার মধ্য দিয়ে সেই উসকানি আসে!"},{"v":2,"ve":2,"vl":"2","bn":"এই ছোটদের মধ্যে একজনকে যদি কেউ গুনাহের পথে নিয়ে যায়, তবে তার গলায় বড় পাথর বেঁধে তাকে সাগরে ফেলে দেওয়া বরং তার পক্ষে ভাল।"},{"v":3,"ve":3,"vl":"3","bn":"“তোমরা সাবধান হও। যদি তোমার ভাই তোমার বিরুদ্ধে অন্যায় করে তাকে বকুনি দাও। যদি সে সেই অন্যায় থেকে মন ফিরায় তবে তাকে মাফ কর।"},{"v":4,"ve":4,"vl":"4","bn":"যদি দিনের মধ্যে সাতবার তোমার বিরুদ্ধে সে অন্যায় করে এবং সাতবারই এসে বলে, ‘আমি এই অন্যায় থেকে মন ফিরিয়েছি,’ তাহলে তাকে মাফ করতে হবে।”"},{"v":5,"ve":5,"vl":"5","bn":"সেই বারোজন সাহাবী হযরত ঈসাকে বললেন, “আমাদের বিশ্বাস বাড়িয়ে দিন।”"},{"v":6,"ve":6,"vl":"6","bn":"ঈসা বললেন, “একটা সরিষা-দানার মতও যদি তোমাদের বিশ্বাস থাকে তবে তোমরা এই তুঁত গাছটাকে বলতে পারবে, ‘শিকড়সুদ্ধ উঠে গিয়ে নিজেকে সাগরে পুঁতে রাখ’; তাতে সেই গাছটি তোমাদের কথা শুনবে।"},{"v":7,"ve":7,"vl":"7","bn":"“মনে কর, তোমাদের একজনের গোলাম হাল বাইছে বা ভেড়া চরাচ্ছে। যখন সেই গোলাম মাঠ থেকে আসবে তখন কি তার মালিক তাকে বলবেন, ‘তাড়াতাড়ি গিয়ে খেতে বস’?"},{"v":8,"ve":8,"vl":"8","bn":"না, তা বলবেন না, বরং বলবেন, ‘আমার খাওয়ার আয়োজন কর, আর আমি যতক্ষণ খাওয়া-দাওয়া করি ততক্ষণ কোমরে কাপড় জড়িয়ে আমার সেবা-যত্ন কর। তারপর তুমি খাওয়া-দাওয়া করবে।’"},{"v":9,"ve":9,"vl":"9","bn":"সেই গোলাম তাঁর হুকুম মত কাজ করেছে বলে কি তিনি তাকে শুকরিয়া জানাবেন?"},{"v":10,"ve":10,"vl":"10","bn":"সেইভাবে আল্লাহ্‌র হুকুম মত সমস্ত কাজ করবার পরে তোমরা বোলো, ‘আমরা অপদার্থ গোলাম; যা করা উচিত আমরা কেবল তা-ই করেছি।’ ”"},{"heading":"দশজন চর্মরোগীকে সুস্থ করা","v":11,"ve":13,"vl":"11-13","bn":"জেরুজালেমে যাবার পথে ঈসা সামেরিয়া ও গালীলের মধ্য দিয়ে যাচ্ছিলেন। তখন একটা গ্রামে ঢুকবার সময় তিনি দশজন চর্মরোগীকে দেখতে পেলেন। তারা দূরে দাঁড়িয়ে চিৎকার করে বলল, “ঈসা, হুজুর, আমাদের দয়া করুন।”"},{"v":14,"ve":14,"vl":"14","bn":"সেই রোগীদের দেখে ঈসা বললেন, “ইমামদের কাছে গিয়ে নিজেদের দেখাও।” তারা পথে যেতে যেতেই সুস্থ হয়ে গেল।"},{"v":15,"ve":16,"vl":"15-16","bn":"তাদের মধ্যে একজন যখন দেখল সে ভাল হয়ে গেছে তখন সে চিৎকার করে আল্লাহ্‌র প্রশংসা করতে করতে ফিরে আসল এবং ঈসার পায়ের কাছে উবুড় হয়ে পড়ে তাঁকে শুকরিয়া জানাল। সে ছিল সামেরিয়া প্রদেশের লোক।"},{"v":17,"ve":17,"vl":"17","bn":"তখন ঈসা বললেন, “দশজনকে কি সুস্থ করা হয় নি? তবে বাকী ন’জন কোথায়?"},{"v":18,"ve":18,"vl":"18","bn":"আল্লাহ্‌র প্রশংসা করবার জন্য এই বিদেশী লোকটি ছাড়া আর কেউ কি ফিরে আসল না?”"},{"v":19,"ve":19,"vl":"19","bn":"তারপর ঈসা লোকটিকে বললেন, “উঠে চলে যাও। বিশ্বাস করেছ বলে তুমি ভাল হয়েছ।”"},{"heading":"আল্লাহ্‌র রাজ্য আসবার বিষয়ে শিক্ষা","v":20,"ve":20,"vl":"20","bn":"কয়েকজন ফরীশী ঈসাকে জিজ্ঞাসা করলেন কবে আল্লাহ্‌র রাজ্য আসবে। জবাবে ঈসা বললেন, “আল্লাহ্‌র রাজ্য আসবার সময় কোন চিহ্ন দেখা যায় না।"},{"v":21,"ve":21,"vl":"21","bn":"কেউই বলবে না, “দেখ, আল্লাহ্‌র রাজ্য এখানে,’ বা ‘দেখ, আল্লাহ্‌র রাজ্য ওখানে,’ কারণ আপনাদের মধ্যেই তো আল্লাহ্‌র রাজ্য আছে।”"},{"v":22,"ve":22,"vl":"22","bn":"এর পরে তিনি তাঁর সাহাবীদের বললেন, “এমন দিন আসছে যখন তোমরা চাইবে যেন ইব্‌ন্তেআদমের সময়কার একটা দিন তোমরা দেখতে পাও, কিন্তু তা দেখতে পাবে না।"},{"v":23,"ve":23,"vl":"23","bn":"লোকে তোমাদের বলবে, ‘ওখানে দেখ,’ বা ‘এখানে দেখ।’ বাইরে যেয়ো না বা তাদের পিছনে দৌড়িও না।"},{"v":24,"ve":24,"vl":"24","bn":"বিদ্যুৎ চমকালে যেমন আকাশের একদিক থেকে অন্যদিক পর্যন্ত আলো হয়ে যায়, ইব্‌ন্তেআদমের আসা সেইভাবে হবে।"},{"v":25,"ve":25,"vl":"25","bn":"কিন্তু প্রথমে তাঁকে অনেক দুঃখ-কষ্ট ভোগ করতে হবে। তা ছাড়া এই কালের লোকেরা তাঁকে অগ্রাহ্য করবে।"},{"v":26,"ve":26,"vl":"26","bn":"“নূহের সময়ে যেমন হয়েছিল ইব্‌ন্তেআদমের সময়েও তেমনি হবে।"},{"v":27,"ve":27,"vl":"27","bn":"যে পর্যন্ত না নূহ্‌ জাহাজে উঠলেন এবং বন্যা এসে লোকদের সবাইকে ধ্বংস করল সেই পর্যন্ত লোকেরা খাওয়া-দাওয়া করছিল, বিয়ে করছিল ও বিয়ে দিচ্ছিল।"},{"v":28,"ve":28,"vl":"28","bn":"আবার লুতের সময়ে যেমন হয়েছিল তেমনি হবে। সেই সময়ে লোকে খাওয়া-দাওয়া, বেচা-কেনা, চাষ-বাস এবং ঘর-বাড়ী তৈরী করছিল।"},{"v":29,"ve":29,"vl":"29","bn":"কিন্তু যেদিন লুত সাদুম ছেড়ে আসলেন সেই দিন আসমান থেকে আগুন ও গন্ধকের বৃষ্টি পড়ে লোকদের সবাইকে ধ্বংস করল।"},{"v":30,"ve":30,"vl":"30","bn":"যেদিন ইব্‌ন্তেআদম প্রকাশিত হবেন সেই দিন এই রকমই হবে।"},{"v":31,"ve":31,"vl":"31","bn":"“সেই দিন ছাদের উপরে যে থাকবে সে ঘর থেকে জিনিসপত্র নেবার জন্য নীচে না নামুক। তেমনি করে ক্ষেতের মধ্যে যে থাকবে সে ফিরে না আসুক।"},{"v":32,"ve":32,"vl":"32","bn":"লুতের স্ত্রীর কথা মনে করে দেখ।"},{"v":33,"ve":33,"vl":"33","bn":"যে কেউ তার জীবন রক্ষা করতে চেষ্টা করে সে তার সত্যিকারের জীবন হারাবে, আর যে কেউ তার প্রাণ হারায় সে তার সত্যিকারের জীবন রক্ষা করবে।"},{"v":34,"ve":34,"vl":"34","bn":"আমি তোমাদের বলছি, সেই রাতে এক বিছানায় দু’জন থাকবে; একজনকে নেওয়া হবে আর অন্যজনকে ফেলে যাওয়া হবে।"},{"v":35,"ve":36,"vl":"35-36","bn":"তখন দু’জন স্ত্রীলোক একসংগে জাঁতা ঘুরাবে; একজনকে নেওয়া হবে আর অন্যজনকে ফেলে যাওয়া হবে।”"},{"v":37,"ve":37,"vl":"37","bn":"সাহাবীরা বললেন, “হুজুর, কোথায়?” জবাবে ঈসা বললেন, “লাশ যেখানে থাকে সেখানেই তো শকুন এসে জড়ো হয়।”"}],"18":[{"heading":"মুনাজাতের বিষয়ে শিক্ষা","v":1,"ve":2,"vl":"1-2","bn":"সাহাবীরা যাতে সব সময় মুনাজাত করে এবং নিরাশ না হয় সেই শিক্ষা দেবার জন্য ঈসা তাঁদের এই উদাহরণটা বললেন: “কোন এক শহরে একজন বিচারক ছিলেন। তিনি আল্লাহ্‌কে ভয় করতেন না এবং মানুষকেও গ্রাহ্য করতেন না।"},{"v":3,"ve":3,"vl":"3","bn":"সেই শহরে একজন বিধবা ছিল। সে বারবার এসে তাঁকে বলত, ‘ন্যায়বিচার করে আমার বিপক্ষের বিরুদ্ধে রায় দিন।’"},{"v":4,"ve":4,"vl":"4","bn":"সেই বিচারক কিছু দিন পর্যন্ত কিছুই করলেন না। কিন্তু শেষে তিনি মনে মনে বললেন, ‘যদিও আমি আল্লাহ্‌কে ভয় করি না এবং মানুষকেও গ্রাহ্য করি না,"},{"v":5,"ve":5,"vl":"5","bn":"তবুও এই বিধবা আমাকে বিরক্ত করছে বলে আমি তার পক্ষে ন্যায়বিচার করব। তা না হলে সে বারবার আসবে আর তাতে আমি ক্লান্ত হয়ে পড়ব।’ ”"},{"v":6,"ve":6,"vl":"6","bn":"এর পর ঈসা আরও বললেন, “ন্যায় বিচারক না হলেও তিনি কি বললেন তা ভেবে দেখ।"},{"v":7,"ve":7,"vl":"7","bn":"তাহলে যারা আল্লাহ্‌কে দিন রাত ডাকে, আল্লাহ্‌ কি তাঁর সেই বাছাই-করা বান্দাদের পক্ষে ন্যায়বিচার করবেন না? তিনি কি তা করতে দেরি করবেন?"},{"v":8,"ve":8,"vl":"8","bn":"আমি তোমাদের বলছি, তিনি তাদের পক্ষে ন্যায়বিচার করতে দেরি করবেন না। কিন্তু ইব্‌ন্তেআদম যখন আসবেন তখন কি তিনি দুনিয়াতে ঈমান দেখতে পাবেন?”"},{"heading":"ফরীশী ও খাজনা-আদায়কারী","v":9,"ve":9,"vl":"9","bn":"যারা নিজেদের ধার্মিক মনে করে অন্যদের তুচ্ছ করত তাদের শিক্ষা দেবার জন্য ঈসা এই কথা বললেন:"},{"v":10,"ve":10,"vl":"10","bn":"“দু’জন লোক মুনাজাত করবার জন্য বায়তুল-মোকাদ্দসে গেলেন। তাঁদের মধ্যে একজন ছিলেন ফরীশী ও অন্যজন খাজনা-আদায়কারী।"},{"v":11,"ve":11,"vl":"11","bn":"সেই ফরীশী দাঁড়িয়ে দাঁড়িয়ে নিজের বিষয়ে এই মুনাজাত করলেন, ‘হে আল্লাহ্‌, আমি তোমাকে শুকরিয়া জানাই যে, আমি অন্য লোকদের মত ঠগ, অসৎ ও জেনাকারী নই, এমন কি, ঐ খাজনা-আদায়কারীর মতও নই।"},{"v":12,"ve":12,"vl":"12","bn":"আমি সপ্তায় দু’বার রোজা রাখি এবং আমার সমস্ত আয়ের দশ ভাগের এক ভাগ তোমাকে দিই।’"},{"v":13,"ve":13,"vl":"13","bn":"সেই সময় সেই খাজনা-আদায়কারী কিছু দূরে দাঁড়িয়ে ছিল। আসমানের দিকে তাকাবারও তার সাহস হল না; সে বুক চাপ্‌ড়ে বলল, ‘হে আল্লাহ্‌! আমি গুনাহ্‌গার; আমার প্রতি মমতা কর।’"},{"v":14,"ve":14,"vl":"14","bn":"“আমি তোমাদের বলছি, সেই খাজনা-আদায়কারীকে আল্লাহ্‌ ধার্মিক বলে গ্রহণ করলেন আর সে বাড়ী ফিরে গেল। কিন্তু সেই ফরীশীকে তিনি ধার্মিক বলে গ্রহণ করলেন না। যে কেউ নিজেকে উঁচু করে তাকে নীচু করা হবে এবং যে নিজেকে নীচু করে তাকে উঁচু করা হবে।”"},{"heading":"হযরত ঈসা মসীহ্‌ ও ছেলেমেয়েরা","v":15,"ve":15,"vl":"15","bn":"লোকেরা ছোট ছেলেমেয়েদের ঈসার কাছে নিয়ে আসল যেন তিনি তাদের উপর হাত রাখেন। সাহাবীরা এ দেখে সেই লোকদের বকুনি দিতে লাগলেন।"},{"v":16,"ve":16,"vl":"16","bn":"কিন্তু ঈসা সেই ছেলেমেয়েদের নিজের কাছে ডেকে নিলেন। তারপর তিনি সাহাবীদের বললেন, “ছেলেমেয়েদের আমার কাছে আসতে দাও, বাধা দিও না; কারণ আল্লাহ্‌র রাজ্য এদের মত লোকদেরই।"},{"v":17,"ve":17,"vl":"17","bn":"আমি তোমাদের সত্যি বলছি, ছোট ছেলেমেয়ের মত আল্লাহ্‌র শাসন মেনে না নিলে কেউ কোনমতেই আল্লাহ্‌র রাজ্যে ঢুকতে পারবে না।”"},{"heading":"একজন ধনী লোক","v":18,"ve":18,"vl":"18","bn":"সমাজের একজন নেতা ঈসাকে জিজ্ঞাসা করলেন, “হুজুর, আপনি একজন ভাল লোক। আমাকে বলুন, কি করলে আমি অনন্ত জীবন লাভ করতে পারব?”"},{"v":19,"ve":19,"vl":"19","bn":"ঈসা তাঁকে বললেন, “আমাকে ভাল বলছেন কেন? একমাত্র আল্লাহ্‌ ছাড়া আর কেউই ভাল নয়।"},{"v":20,"ve":20,"vl":"20","bn":"আপনি তো হুকুমগুলো জানেন, ‘জেনা কোরো না, খুন কোরো না, চুরি কোরো না, মিথ্যা সাক্ষ্য দিয়ো না, তোমার পিতা-মাতাকে সম্মান কোরো।’ ”"},{"v":21,"ve":21,"vl":"21","bn":"সেই নেতা বললেন, “ছোটবেলা থেকে আমি এই সব পালন করে আসছি।”"},{"v":22,"ve":22,"vl":"22","bn":"এই কথা শুনে ঈসা তাঁকে বললেন, “এখনও একটা কাজ আপনার বাকী আছে। আপনার যা কিছু আছে বিক্রি করে গরীবদের বিলিয়ে দিন, তাহলে আপনি বেহেশতে ধন পাবেন। তারপর এসে আমার উম্মত হন।”"},{"v":23,"ve":23,"vl":"23","bn":"এই কথা শুনে সেই নেতা খুব দুঃখিত হলেন, কারণ তিনি খুব ধনী ছিলেন।"},{"v":24,"ve":24,"vl":"24","bn":"সেই নেতার দিকে তাকিয়ে ঈসা বললেন, “ধনীদের পক্ষে আল্লাহ্‌র রাজ্যে ঢোকা কত কঠিন!"},{"v":25,"ve":25,"vl":"25","bn":"ধনীর পক্ষে আল্লাহ্‌র রাজ্যে ঢুকবার চেয়ে বরং সুচের ছিদ্র দিয়ে উটের যাওয়া সহজ।”"},{"v":26,"ve":26,"vl":"26","bn":"ঈসার এই কথা যারা শুনল তারা বলল, “তাহলে কে নাজাত পেতে পারে?”"},{"v":27,"ve":27,"vl":"27","bn":"ঈসা বললেন, “মানুষের পক্ষে যা অসম্ভব আল্লাহ্‌র পক্ষে তা সম্ভব।”"},{"v":28,"ve":28,"vl":"28","bn":"তখন পিতর বললেন, “আমরা তো সব কিছু ছেড়ে দিয়ে আপনার সাহাবী হয়েছি।”"},{"v":29,"ve":29,"vl":"29","bn":"ঈসা তাঁর সাহাবীদের বললেন, “আমি তোমাদের সত্যিই বলছি, যারা আল্লাহ্‌র রাজ্যের জন্য বাড়ী-ঘর, স্ত্রী, ভাই-বোন, মা-বাবা বা ছেলেমেয়ে ছেড়ে এসেছে,"},{"v":30,"ve":30,"vl":"30","bn":"তারা প্রত্যেকে এই যুগেই অনেক বেশী পাবে এবং আগামী যুগে অনন্ত জীবন লাভ করবে।”"},{"heading":"নিজের মৃত্যুর বিষয়ে হযরত ঈসা মসীহের কথা","v":31,"ve":31,"vl":"31","bn":"ঈসা তাঁর বারোজন সাহাবীকে একপাশে ডেকে নিয়ে বললেন, “দেখ, আমরা জেরুজালেমে যাচ্ছি। ইব্‌ন্তেআদমের বিষয়ে নবীরা যা যা লিখে গেছেন তা সবই পূর্ণ হবে।"},{"v":32,"ve":32,"vl":"32","bn":"তাঁকে অ-ইহুদীদের হাতে দেওয়া হবে। লোকে তাঁকে ঠাট্টা ও অপমান করবে এবং তাঁর গায়ে থুথু দেবে।"},{"v":33,"ve":33,"vl":"33","bn":"ভীষণভাবে চাবুক মারবার পরে তারা তাঁকে হত্যা করবে, আর তৃতীয় দিনে তিনি জীবিত হয়ে উঠবেন।”"},{"v":34,"ve":34,"vl":"34","bn":"সাহাবীরা কিন্তু এই সব বিষয় কিছুৃই বুঝলেন না। সেই কথার অর্থ তাঁদের কাছে গোপন রাখা হয়েছিল বলে ঈসা যে কি বলছিলেন তা তাঁরা বুঝলেন না।"},{"heading":"অন্ধ লোকটি সুস্থ হল","v":35,"ve":35,"vl":"35","bn":"ঈসা যখন জেরিকো শহরের কাছে আসলেন তখন একজন অন্ধ লোক পথের ধারে বসে ভিক্ষা করছিল।"},{"v":36,"ve":36,"vl":"36","bn":"অনেক লোকের গলার আওয়াজ শুনে সে ব্যাপার কি তা জিজ্ঞাসা করল।"},{"v":37,"ve":37,"vl":"37","bn":"লোকেরা তাকে জানাল যে, নাসরতের ঈসা ঐ পথ দিয়ে যাচ্ছেন।"},{"v":38,"ve":38,"vl":"38","bn":"তখন সে চিৎকার করে বলল, “দাউদের বংশধর ঈসা, আমাকে দয়া করুন!”"},{"v":39,"ve":39,"vl":"39","bn":"যে লোকেরা ভিড়ের সামনে ছিল তারা তাকে ধমক দিয়ে চুপ করতে বলল। কিন্তু সে আরও চিৎকার করে বলল, “দাউদের বংশধর, আমাকে দয়া করুন।”"},{"v":40,"ve":40,"vl":"40","bn":"ঈসা থামলেন এবং সেই অন্ধকে তাঁর কাছে আনতে বললেন। সে কাছে আসলে পর তিনি বললেন,"},{"v":41,"ve":41,"vl":"41","bn":"“তুমি কি চাও? তোমার জন্য আমি কি করব?” সে বলল, “হুজুর, আমি যেন দেখতে পাই।”"},{"v":42,"ve":42,"vl":"42","bn":"ঈসা তাকে বললেন, “আচ্ছা, তা-ই হোক। তুমি বিশ্বাস করেছ বলে ভাল হয়েছ।”"},{"v":43,"ve":43,"vl":"43","bn":"লোকটি তখনই দেখতে পেল এবং আল্লাহ্‌র প্রশংসা করতে করতে ঈসার পিছনে পিছনে চলল। এ দেখে সমস্ত লোক আল্লাহ্‌র প্রশংসা করল।"}],"19":[{"heading":"সক্কেয়ের নাজাত লাভ","v":1,"ve":1,"vl":"1","bn":"ঈসা জেরিকো শহরের মধ্য দিয়ে যাচ্ছিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"সেখানে সক্কেয় নামে একজন লোক ছিলেন। তিনি ছিলেন প্রধান খাজনা-আদায়কারী এবং একজন ধনী লোক।"},{"v":3,"ve":3,"vl":"3","bn":"ঈসা কে, তা তিনি দেখতে চেষ্টা করছিলেন, কিন্তু বেঁটে ছিলেন বলে ভিড়ের জন্য তাঁকে দেখতে পাচ্ছিলেন না।"},{"v":4,"ve":4,"vl":"4","bn":"তাই তিনি ঈসাকে দেখবার জন্য সামনে দৌড়ে গিয়ে একটা ডুমুর গাছে উঠলেন, কারণ ঈসা সেই পথ দিয়েই যাচ্ছিলেন।"},{"v":5,"ve":5,"vl":"5","bn":"ঈসা সেই ডুমুর গাছের কাছে এসে উপরের দিকে তাকালেন এবং সক্কেয়কে বললেন, “সক্কেয়, তাড়াতাড়ি নেমে এস, কারণ আজ তোমার বাড়ীতে আমাকে থাকতে হবে।”"},{"v":6,"ve":6,"vl":"6","bn":"সক্কেয় তাড়াতাড়ি নেমে আসলেন এবং আনন্দের সংগে ঈসাকে গ্রহণ করলেন।"},{"v":7,"ve":7,"vl":"7","bn":"এ দেখে সবাই বক্‌বক করে বলল, “উনি একজন গুনাহ্‌গার লোকের মেহমান হতে গেলেন।”"},{"v":8,"ve":8,"vl":"8","bn":"সক্কেয় সেখানে দাঁড়িয়ে ঈসাকে বললেন, “হুজুর, আমি আমার ধন-সম্পত্তির অর্ধেক গরীবদের দিয়ে দিচ্ছি এবং যদি কাউকে ঠকিয়ে থাকি তবে তার চারগুণ ফিরিয়ে দিচ্ছি।”"},{"v":9,"ve":9,"vl":"9","bn":"তখন ঈসা বললেন, “এই বাড়ীতে আজ নাজাত আসল, কারণ এও তো ইব্রাহিমের বংশের একজন।"},{"v":10,"ve":10,"vl":"10","bn":"যারা হারিয়ে গেছে তাদের তালাশ করতে ও নাজাত করতেই ইব্‌ন্তেআদম এসেছেন।”"},{"heading":"বাদশাহ্‌ ও তাঁর দশজন গোলাম","v":11,"ve":11,"vl":"11","bn":"ঈসা তখন যেখানে ছিলেন সেখান থেকে জেরুজালেম বেশী দূরে ছিল না, আর যারা তাঁর কথা শুনছিল তারা ভাবছিল আল্লাহ্‌র রাজ্য শীঘ্রই প্রকাশ পাবে। তাই ঈসা তাদের শিক্ষা দেবার জন্য এই কথা বললেন:"},{"v":12,"ve":12,"vl":"12","bn":"“একজন উঁচু বংশের লোক রাজ-পদ নিয়ে ফিরে আসবেন বলে দূর দেশে গেলেন।"},{"v":13,"ve":13,"vl":"13","bn":"যাবার আগে তিনি তাঁর দশজন গোলামকে ডাকলেন এবং প্রত্যেক জনকে একশো দীনার করে দিয়ে বললেন, ‘আমি ফিরে না আসা পর্যন্ত এ দিয়ে ব্যবসা কর।’"},{"v":14,"ve":14,"vl":"14","bn":"“তাঁর দেশের লোকেরা কিন্তু তাঁকে ঘৃণা করত। এইজন্য তারা তাঁর পিছনে লোক পাঠিয়ে খবর দিল, ‘আমরা চাই না এই লোকটা আমাদের উপর রাজত্ব করুক।’"},{"v":15,"ve":15,"vl":"15","bn":"“তবুও তিনি বাদশাহ্‌ নিযুক্ত হয়ে ফিরে আসলেন এবং যে দশজন গোলামকে টাকা দিয়েছিলেন তাদের ডেকে আনতে হুকুম দিলেন। তিনি জানতে চাইলেন ব্যবসা করে তারা কে কত লাভ করেছে।"},{"v":16,"ve":16,"vl":"16","bn":"প্রথম জন এসে বলল, ‘হুজুর, আপনার টাকা দিয়ে আমি দশগুণ লাভ করেছি।’"},{"v":17,"ve":17,"vl":"17","bn":"“বাদশাহ্‌ তাকে বললেন, ‘শাবাশ! তুমি ভাল গোলাম। তুমি সামান্য বিষয়ে বিশ্বস্ত হয়েছ বলে আমি তোমাকে দশটা গ্রামের ভার দিলাম।’"},{"v":18,"ve":18,"vl":"18","bn":"“দ্বিতীয় গোলামটি এসে বলল, ‘হুজুর, আপনার টাকা দিয়ে আমি পাঁচগুণ লাভ করেছি।’"},{"v":19,"ve":19,"vl":"19","bn":"“তিনি সেই গোলামকে বললেন, ‘তুমি পাঁচটা গ্রামের ভার পাবে।’"},{"v":20,"ve":20,"vl":"20","bn":"“তার পরে অন্য আর একজন গোলাম এসে বলল, ‘হুজুর, আমি আপনার টাকা রুমালে বেঁধে রেখে দিয়েছিলাম।"},{"v":21,"ve":21,"vl":"21","bn":"আপনার সম্বন্ধে আমার ভয় ছিল কারণ আপনি খুব কড়া লোক; আপনি যা জমা করেন নি তা নিয়ে থাকেন এবং যা বোনেন নি তা কাটেন।’"},{"v":22,"ve":22,"vl":"22","bn":"“তখন বাদশাহ্‌ বললেন, ‘ওরে দুষ্ট গোলাম! তোর মুখের কথা দিয়েই আমি তোর বিচার করব। তুই তো জানতিস্‌ যে, আমি কড়া লোক; যা জমা করি নি তা নিয়ে থাকি এবং যা বুনি নি তা কাটি।"},{"v":23,"ve":23,"vl":"23","bn":"তবে আমার টাকা তুই মহাজনের কাছে রাখলি না কেন? তাহলে তো আমি এসে টাকাটাও পেতাম এবং সংগে কিছু সুদও পেতাম।’"},{"v":24,"ve":24,"vl":"24","bn":"“যারা বাদশাহ্‌র কাছে দাঁড়িয়ে ছিল বাদশাহ্‌ তাদের বললেন, ‘ওর কাছ থেকে ঐ একশো দীনার নিয়ে নাও এবং যার এক হাজার দীনার আছে তাকে দাও।’"},{"v":25,"ve":25,"vl":"25","bn":"“তখন সেই লোকেরা বাদশাহ্‌কে বলল, ‘হুজুর, ওর তো এক হাজার দীনার আছে।’"},{"v":26,"ve":26,"vl":"26","bn":"“বাদশাহ্‌ বললেন, ‘আমি তোমাদের বলছি, যার আছে তাকে আরও দেওয়া হবে, কিন্তু যার নেই তার যা আছে তা-ও তার কাছ থেকে নিয়ে নেওয়া হবে।"},{"v":27,"ve":27,"vl":"27","bn":"আমার শত্রুরা যারা চায় নি আমি বাদশাহ্‌ হই, তাদের এখানে নিয়ে এস এবং আমার সামনে মেরে ফেল।’ ”"},{"heading":"জেরুজালেমে প্রবেশ","v":28,"ve":28,"vl":"28","bn":"এই সব কথা বলবার পরে ঈসা তাঁদের আগে আগে জেরুজালেমের দিকে চললেন।"},{"v":29,"ve":29,"vl":"29","bn":"যখন তিনি জৈতুন পাহাড়ের গায়ে বৈৎফগী ও বেথানিয়া গ্রামের কাছে আসলেন তখন তাঁর দু’জন সাহাবীকে এই বলে পাঠিয়ে দিলেন,"},{"v":30,"ve":30,"vl":"30","bn":"“তোমরা সামনের ঐ গ্রামে যাও। সেখানে ঢুকবার সময় দেখতে পাবে একটা গাধার বাচ্চা বাঁধা আছে। ওর উপরে কেউ কখনও চড়ে নি। ওটা খুলে এখানে নিয়ে এস।"},{"v":31,"ve":31,"vl":"31","bn":"যদি কেউ জিজ্ঞাসা করে, ‘কেন ওটা খুলছ?’ তবে বোলো, ‘হুজুরের দরকার আছে।’ ”"},{"v":32,"ve":32,"vl":"32","bn":"যে সাহাবীদের পাঠানো হয়েছিল তাঁরা গিয়ে ঈসার কথামতই সব কিছু দেখতে পেলেন।"},{"v":33,"ve":33,"vl":"33","bn":"তাঁরা যখন সেই বাচ্চাটা খুলছিলেন তখন মালিকেরা তাঁদের জিজ্ঞাসা করল, “তোমরা বাচ্চাটা খুলছ কেন?”"},{"v":34,"ve":34,"vl":"34","bn":"তাঁরা বললেন, “হুজুরের দরকার আছে।”"},{"v":35,"ve":35,"vl":"35","bn":"তারপর সাহাবীরা সেই গাধার বাচ্চাটা ঈসার কাছে আনলেন এবং তার উপরে তাঁদের গায়ের চাদর পেতে দিয়ে ঈসাকে বসালেন।"},{"v":36,"ve":36,"vl":"36","bn":"তিনি যখন যাচ্ছিলেন তখন লোকেরা নিজেদের গায়ের চাদর পথে বিছিয়ে দিতে লাগল।"},{"v":37,"ve":37,"vl":"37","bn":"এইভাবে ঈসা জেরুজালেমের কাছে এসে যে রাস্তাটা জৈতুন পাহাড় থেকে নেমে গেছে সেই রাস্তায় আসলেন। ঈসার সংগে তাঁর অনেক সাহাবী ছিলেন। সেই সাহাবীরা তাঁর যে সব অলৌকিক কাজ দেখেছিলেন সেগুলোর জন্য আনন্দে চিৎকার করে আল্লাহ্‌র প্রশংসা করে বলতে লাগলেন,"},{"v":38,"ve":38,"vl":"38","bn":"“মাবুদের নামে যে বাদশাহ্‌ আসছেন তাঁর প্রশংসা হোক! বেহেশতেই শান্তি, আর সেখানে আল্লাহ্‌র মহিমা প্রকাশিত।”"},{"v":39,"ve":39,"vl":"39","bn":"ভিড়ের মধ্য থেকে কয়েকজন ফরীশী ঈসাকে বললেন, “হুজুর, আপনার সাহাবীদের চুপ করতে বলুন।”"},{"v":40,"ve":40,"vl":"40","bn":"ঈসা তাঁদের বললেন, “আমি আপনাদের বলছি, এরা যদি চুপ করে থাকে তবে পাথরগুলো চেঁচিয়ে উঠবে।”"},{"v":41,"ve":41,"vl":"41","bn":"তাঁরা যখন জেরুজালেমের কাছে আসলেন তখন ঈসা শহরটা দেখে কাঁদলেন।"},{"v":42,"ve":42,"vl":"42","bn":"তিনি বললেন, “হায়, শান্তি পাবার জন্য যা দরকার, তুমি, জ্বী তুমি যদি আজ তা বুঝতে পারতে! কিন্তু এখন তা তোমার চোখের আড়ালে রয়েছে।"},{"v":43,"ve":43,"vl":"43","bn":"এমন সময় তোমার আসবে যখন শত্রুরা তোমার বিরুদ্ধে বাধার দেয়াল তুলবে এবং তোমাকে ঘিরে রাখবে ও সমস্ত দিক থেকে তোমাকে চেপে ধরবে।"},{"v":44,"ve":44,"vl":"44","bn":"তারা তোমাকে ও তোমার ভিতরের সমস্ত লোকদের ধরে মাটিতে আছাড় মারবে এবং একটা পাথরের উপরে আর একটা পাথর রাখবে না, কারণ আল্লাহ্‌ যে সময়ে তোমার দিকে মনোযোগ দিয়েছিলেন সেই সময়টা তুমি চিনে নাও নি।”"},{"v":45,"ve":45,"vl":"45","bn":"এর পরে ঈসা বায়তুল-মোকাদ্দসে ঢুকে ব্যবসায়ীদের তাড়িয়ে দিলেন।"},{"v":46,"ve":46,"vl":"46","bn":"তিনি সেই ব্যবসায়ীদের বললেন, “পাক-কিতাবে লেখা আছে, ‘আমার ঘর মুনাজাতের ঘর হবে,’ কিন্তু তোমরা তা ডাকাতের আড্ডাখানা করে তুলেছ।”"},{"v":47,"ve":47,"vl":"47","bn":"ঈসা প্রত্যেক দিনই বায়তুল-মোকাদ্দসে গিয়ে শিক্ষা দিতে লাগলেন। প্রধান ইমামেরা, আলেমেরা এবং লোকদের নেতারা তাঁকে হত্যা করতে চাইলেন,"},{"v":48,"ve":48,"vl":"48","bn":"কিন্তু কিভাবে তা করবেন তার কোন উপায় তাঁরা খুঁজে পেলেন না, কারণ লোকেরা মন দিয়ে তাঁর প্রত্যেকটি কথা শুনত।"}],"20":[{"heading":"হযরত ঈসা মসীহ্‌ ও ধর্ম-নেতারা","v":1,"ve":2,"vl":"1-2","bn":"একদিন ঈসা বায়তুল-মোকাদ্দসে লোকদের শিক্ষা দিচ্ছিলেন এবং তবলিগ করছিলেন। এমন সময় প্রধান ইমামেরা ও আলেমেরা বৃদ্ধনেতাদের সংগে এসে ঈসাকে বললেন, “কোন্‌ অধিকারে তুমি এই সব করছ এবং কে তোমাকে এই অধিকার দিয়েছে, তা আমাদের বল।”"},{"v":3,"ve":3,"vl":"3","bn":"জবাবে ঈসা তাঁদের বললেন, “আমিও আপনাদের একটা কথা জিজ্ঞাসা করব। বলুন দেখি,"},{"v":4,"ve":4,"vl":"4","bn":"তরিকাবন্দী দেবার অধিকার ইয়াহিয়া আল্লাহ্‌র কাছ থেকে পেয়েছিলেন, না মানুষের কাছ থেকে পেয়েছিলেন?”"},{"v":5,"ve":5,"vl":"5","bn":"তখন তাঁরা নিজেদের মধ্যে এই আলোচনা করতে লাগলেন, “যদি আমরা বলি, ‘আল্লাহ্‌র কাছ থেকে,’ তবে সে বলবে, ‘তা হলে তাঁকে বিশ্বাস করেন নি কেন?’"},{"v":6,"ve":6,"vl":"6","bn":"কিন্তু যদি বলি, ‘মানুষের কাছ থেকে,’ তাহলে লোকেরা আমাদের পাথর মারবে, কারণ তারা ইয়াহিয়াকে নবী বলে বিশ্বাস করে।”"},{"v":7,"ve":7,"vl":"7","bn":"এইজন্য তাঁরা বললেন, “সেই অধিকার কোথা থেকে এসেছিল তা আমরা জানি না।”"},{"v":8,"ve":8,"vl":"8","bn":"ঈসা তাঁদের বললেন, “তবে আমিও বলব না কোন্‌ অধিকারে আমি এই সব করছি।”"},{"heading":"আংগুর-ক্ষেতের চাষীদের গল্প","v":9,"ve":9,"vl":"9","bn":"এর পরে ঈসা লোকদের শিক্ষা দেবার জন্য এই কথা বললেন: “একজন লোক একটা আংগুর-ক্ষেত করলেন এবং চাষীদের কাছে সেটা ইজারা দিয়ে অনেক দিনের জন্য বিদেশে চলে গেলেন।"},{"v":10,"ve":10,"vl":"10","bn":"পরে তিনি সেই ক্ষেতের আংগুর ফলের ভাগ পাবার জন্য সময়মতই একজন গোলামকে চাষীদের কাছে পাঠালেন। কিন্তু চাষীরা তাকে মারধর করে খালি হাতেই ফেরৎ পাঠিয়ে দিল।"},{"v":11,"ve":11,"vl":"11","bn":"তখন তিনি আর একজন গোলামকে পাঠালেন, কিন্তু চাষীরা তাকেও মারল ও অপমান করল এবং খালি হাতে পাঠিয়ে দিল।"},{"v":12,"ve":12,"vl":"12","bn":"পরে তিনি তৃতীয় গোলামকে পাঠালেন, কিন্তু চাষীরা তাকেও ভীষণ মারধর করে তাড়িয়ে দিল।"},{"v":13,"ve":13,"vl":"13","bn":"“তখন আংগুর-ক্ষেতের মালিক বললেন, ‘কি করি? আচ্ছা, আমি আমার প্রিয় পুত্রকে পাঠাব। হয়তো তারা তাকে সম্মান করবে।’"},{"v":14,"ve":14,"vl":"14","bn":"“কিন্তু চাষীরা তাঁকে দেখে একে অন্যকে বলল, ‘এ-ই তো পরে সম্পত্তির মালিক হবে। সম্পত্তিটা যেন আমাদেরই হয় সেইজন্য এস, আমরা ওকে মেরে ফেলি।’"},{"v":15,"ve":15,"vl":"15","bn":"এই বলে তারা তাঁকে ধরে ক্ষেতের বাইরে নিয়ে গিয়ে হত্যা করল। “এখন আংগুর-ক্ষেতের মালিক সেই চাষীদের কি করবেন?"},{"v":16,"ve":16,"vl":"16","bn":"তিনি এসে তাদের হত্যা করবেন এবং ক্ষেতটা অন্যদের ইজারা দেবেন।” লোকেরা ঈসার কথা শুনে বলল, “এমন না হোক।”"},{"v":17,"ve":17,"vl":"17","bn":"তখন ঈসা তাদের দিকে তাকিয়ে বললেন, “তবে এই যে কথা পাক-কিতাবের মধ্যে লেখা আছে, ‘রাজমিস্ত্রিরা যে পাথরটা বাতিল করে দিয়েছিল, সেটাই সবচেয়ে দরকারী পাথর হয়ে উঠল’- এর অর্থ কি?"},{"v":18,"ve":18,"vl":"18","bn":"যে কেউ সেই পাথরের উপরে পড়বে সে ভেংগে টুকরা টুকরা হয়ে যাবে এবং যার উপর সেই পাথর পড়বে সে চুরমার হয়ে যাবে।”"},{"v":19,"ve":19,"vl":"19","bn":"এই সময়ে আলেমেরা ও প্রধান ইমামেরা ঈসাকে ধরতে চাইলেন, কারণ তাঁরা বুঝেছিলেন যে, ঐ কথা ঈসা তাঁদের বিরুদ্ধেই বলেছেন; কিন্তু তাঁরা লোকদের ভয় পেলেন।"},{"heading":"খাজনা দেবার বিষয়ে","v":20,"ve":20,"vl":"20","bn":"আলেম ও প্রধান ইমামেরা ঈসাকে চোখে চোখে রাখলেন এবং গোয়েন্দা পাঠিয়ে দিলেন। ঈসাকে তাঁর নিজের কথার ফাঁদে ফেলবার জন্য সেই গোয়েন্দারা ভাল মানুষের ভাণ করতে লাগল, যেন তারা তাঁকে প্রধান শাসনকর্তার বিচার-ক্ষমতার অধীনে ফেলতে পারে।"},{"v":21,"ve":21,"vl":"21","bn":"সেইজন্য তারা তাঁকে বলল, “হুজুর, আমরা জানি যে, আপনি যা বলেন ও শিক্ষা দেন তা ঠিক। আপনি সবাইকে সমান চোখে দেখেন এবং সত্য ভাবেই আল্লাহ্‌র পথের বিষয়ে শিক্ষা দিয়ে থাকেন।"},{"v":22,"ve":22,"vl":"22","bn":"আচ্ছা, মূসার শরীয়ত অনুসারে রোম-সম্রাটকে কি খাজনা দেওয়া উচিত?”"},{"v":23,"ve":23,"vl":"23","bn":"ঈসা তাদের চালাকি বুঝতে পেরে বললেন,"},{"v":24,"ve":24,"vl":"24","bn":"“আমাকে একটা দীনার দেখাও। এর উপরে কার ছবি ও কার নাম আছে?” তারা বলল, “রোম-সম্রাটের।”"},{"v":25,"ve":25,"vl":"25","bn":"ঈসা তাদের বললেন, “তা হলে যা সম্রাটের তা সম্রাটকে দাও এবং যা আল্লাহ্‌র তা আল্লাহ্‌কে দাও।”"},{"v":26,"ve":26,"vl":"26","bn":"লোকদের সামনে ঈসা যা বলেছিলেন তাতে সেই গোয়েন্দারা তাঁকে তাঁর কথার ফাঁদে ফেলতে পারল না। তাঁর জবাবে আশ্চর্য হয়ে তারা চুপ হয়ে গেল।"},{"heading":"জীবিত হয়ে উঠবার বিষয়ে","v":27,"ve":27,"vl":"27","bn":"সদ্দূকীদের মধ্যে কয়েকজন ঈসার কাছে আসলেন। সদ্দূকীদের মতে মৃতদের জীবিত হয়ে উঠা বলে কিছু নেই। তাঁরা ঈসাকে জিজ্ঞাসা করলেন,"},{"v":28,"ve":28,"vl":"28","bn":"“হুজুর, মূসা আমাদের জন্য এই কথা লিখে গেছেন, সন্তানহীন অবস্থায় যদি কোন লোক তার স্ত্রীকে রেখে মারা যায়, তবে তার ভাই তার স্ত্রীকে বিয়ে করে ভাইয়ের হয়ে তার বংশ রক্ষা করবে।"},{"v":29,"ve":29,"vl":"29","bn":"খুব ভাল, ধরুন, সাতজন ভাই ছিল। প্রথম জন বিয়ে করে সন্তানহীন অবস্থায় মারা গেল।"},{"v":30,"ve":31,"vl":"30-31","bn":"পরে দ্বিতীয় ও তার পরে তৃতীয় ভাই সেই বিধবা স্ত্রীকে বিয়ে করল এবং সেই একইভাবে সাতজনই ছেলেমেয়ে না রেখে মারা গেল।"},{"v":32,"ve":32,"vl":"32","bn":"শেষে সেই স্ত্রীলোকটিও মারা গেল।"},{"v":33,"ve":33,"vl":"33","bn":"তাহলে যেদিন মৃতেরা জীবিত হয়ে উঠবে সেই দিন সে কার স্ত্রী হবে? সাতজনের প্রত্যেকেই তো তাকে বিয়ে করেছিল।”"},{"v":34,"ve":34,"vl":"34","bn":"ঈসা তাঁদের বললেন, “এই কালের লোকেরা বিয়ে করে এবং তাদের বিয়ে দেওয়া হয়।"},{"v":35,"ve":35,"vl":"35","bn":"কিন্তু মৃত্যু থেকে জীবিত হয়ে আগামী যুগে পার হয়ে যাবার যোগ্য বলে যাদের ধরা হবে, তারা বিয়ে করবে না এবং তাদের বিয়ে দেওয়াও হবে না।"},{"v":36,"ve":36,"vl":"36","bn":"তারা আর মরতে পারে না, কারণ তারা ফেরেশতাদের মত। তারা আল্লাহ্‌র সন্তান কারণ মৃত্যু থেকে তাদের জীবিত করা হয়েছে।"},{"v":37,"ve":37,"vl":"37","bn":"জ্বলন্ত ঝোপের বিষয়ে যেখানে লেখা আছে সেখানে মূসা দেখিয়ে দিয়েছেন যে, মৃতেরা সত্যিই জীবিত হয়ে ওঠে। সেখানে মূসা মাবুদকে ‘ইব্রাহিমের আল্লাহ্‌, ইসহাকের আল্লাহ্‌ ও ইয়াকুবের আল্লাহ্‌’ বলে ডেকেছেন।"},{"v":38,"ve":38,"vl":"38","bn":"কিন্তু আল্লাহ্‌ তো মৃতদের আল্লাহ্‌ নন, তিনি জীবিতদেরই আল্লাহ্‌। তাঁরই উদ্দেশ্যে সব লোক বেঁচে থাকে।”"},{"v":39,"ve":39,"vl":"39","bn":"তখন কয়েকজন আলেম বললেন, “হুজুর, আপনি ভালই বলেছেন।”"},{"v":40,"ve":40,"vl":"40","bn":"তাঁরা আর কোন কিছু ঈসাকে জিজ্ঞাসা করতে সাহস পেলেন না।"},{"heading":"আলেমদের কাছে হযরত ঈসা মসীহের প্রশ্ন","v":41,"ve":41,"vl":"41","bn":"ঈসা সেই আলেমদের বললেন, “লোকে কি করে বলে যে, মসীহ্‌ দাউদের বংশধর?"},{"v":42,"ve":43,"vl":"42-43","bn":"জবুর শরীফ কিতাবে দাউদ তো নিজেই এই কথা বলেছেন, ‘মাবুদ আমার প্রভুকে বললেন, যতক্ষণ না আমি তোমার শত্রুদের তোমার পায়ের তলায় রাখি, ততক্ষণ তুমি আমার ডানদিকে বস।’"},{"v":44,"ve":44,"vl":"44","bn":"দাউদ তো মসীহ্‌কে প্রভু বলে ডেকেছিলেন; তাহলে মসীহ্‌ কেমন করে দাউদের বংশধর হতে পারেন?”"},{"v":45,"ve":45,"vl":"45","bn":"লোকেরা যখন ঈসার কথা শুনছিল তখন ঈসা তাঁর সাহাবীদের বললেন,"},{"v":46,"ve":46,"vl":"46","bn":"“আলেমদের বিষয়ে সাবধান হও। তাঁরা লম্বা লম্বা কোর্তা পরে ঘুরে বেড়াতে চান এবং হাটে-বাজারে সম্মান পেতে ভালবাসেন। তাঁরা মজলিস-খানায় প্রধান প্রধান আসনে ও মেজবানীর সময়ে সম্মানের জায়গায় বসতে ভালবাসেন।"},{"v":47,"ve":47,"vl":"47","bn":"এক দিকে তাঁরা লোককে দেখাবার জন্য লম্বা লম্বা মুনাজাত করেন, অন্য দিকে বিধবাদের সম্পত্তি দখল করেন। এই লোকদের অনেক বেশী শাস্তি হবে।”"}],"21":[{"heading":"গরীব বিধবার দান","v":1,"ve":1,"vl":"1","bn":"এর পরে ঈসা চেয়ে দেখলেন, ধনী লোকেরা বায়তুল-মোকাদ্দসের দানের বাক্সে তাদের দান রাখছে।"},{"v":2,"ve":2,"vl":"2","bn":"তিনি দেখলেন, একজন গরীব বিধবা এসে দু’টা পয়সা রাখল।"},{"v":3,"ve":3,"vl":"3","bn":"তখন ঈসা তাঁর সাহাবীদের বললেন, “আমি তোমাদের সত্যিই বলছি, এই গরীব বিধবা অন্য সকলের চেয়ে অনেক বেশী রাখল,"},{"v":4,"ve":4,"vl":"4","bn":"কারণ অন্যেরা সবাই তাদের প্রচুর ধন থেকে দান করেছে, কিন্তু এই স্ত্রীলোকটির অভাব থাকলেও বেঁচে থাকবার জন্য তার যা ছিল সমস্তই দিয়ে দিল।”"},{"heading":"কেয়ামতের আলামত","v":5,"ve":5,"vl":"5","bn":"সাহাবীদের মধ্যে কয়েকজন বায়তুল-মোকাদ্দসের বিষয়ে আলোচনা করছিলেন। তাঁরা বলছিলেন, সুন্দর সুন্দর পাথর ও দানের জিনিস দিয়ে দালানটা কেমন সাজানো হয়েছে। তখন ঈসা বললেন,"},{"v":6,"ve":6,"vl":"6","bn":"“তোমরা তো এই সব দেখছ, কিন্তু এমন দিন আসবে যখন এর একটা পাথরের উপরে আর একটা পাথর থাকবে না; সমস্তই ভেংগে ফেলা হবে।”"},{"v":7,"ve":7,"vl":"7","bn":"সাহাবীরা ঈসাকে জিজ্ঞাসা করলেন, “হুজুর, কখন এই সব হবে এবং কোন্‌ চিহ্ন দেখে আমরা বুঝতে পারব যে, এই সব ঘটবার সময় এসেছে?”"},{"v":8,"ve":8,"vl":"8","bn":"জবাবে ঈসা বললেন, “দেখো, কেউ যেন তোমাদের না ঠকায়, কারণ অনেকে আমার নাম নিয়ে এসে বলবে, ‘আমিই মসীহ্‌’ এবং ‘সময় কাছে এসেছে।’ তাদের পিছনে যেয়ো না।"},{"v":9,"ve":9,"vl":"9","bn":"তোমরা যখন যুদ্ধের ও বিদ্রোহের খবর শুনবে তখন ভয় পেয়ো না, কারণ প্রথমে এই সব হবেই; কিন্তু তখনই যে শেষ সময় আসবে তা নয়।”"},{"v":10,"ve":10,"vl":"10","bn":"তারপর ঈসা তাঁদের বললেন, “এক জাতি আর এক জাতির বিরুদ্ধে এবং এক রাজ্য অন্য রাজ্যের বিরুদ্ধে যুদ্ধ করবে।"},{"v":11,"ve":11,"vl":"11","bn":"ভীষণ ভূমিকমপ হবে এবং ভিন্ন ভিন্ন জায়গায় দুর্ভিক্ষ ও মহামারী হবে। এছাড়া আসমানে এমন সব ঘটনা ঘটবে ও চিহ্ন দেখা যাবে যা ভীষণ ও ভয়ংকর।"},{"v":12,"ve":12,"vl":"12","bn":"“এই সব হবার আগে লোকেরা তোমাদের ধরবে এবং তোমাদের উপর জুলুম করবে। বিচারের জন্য তারা তোমাদের মজলিস-খানায় নিয়ে যাবে এবং জেলে দেবে। আমার জন্য বাদশাহ্‌দের ও শাসনকর্তাদের সামনে তোমাদের নেওয়া হবে,"},{"v":13,"ve":13,"vl":"13","bn":"আর তাতে আমার সম্বন্ধে সাক্ষ্য দেবার জন্য তোমাদের সুযোগ হবে।"},{"v":14,"ve":14,"vl":"14","bn":"তোমরা এখনই মনে মনে ঠিক করে ফেল, তখন নিজের পক্ষে কথা বলবার জন্য তোমরা আগে থেকে তৈরী হবে না,"},{"v":15,"ve":15,"vl":"15","bn":"কারণ আমি তোমাদের এমন কথা ও এমন জ্ঞান যুগিয়ে দেব যার জবাবে তোমাদের শত্রুরা কিছু বলতেও পারবে না এবং তা অস্বীকারও করতে পারবে না।"},{"v":16,"ve":16,"vl":"16","bn":"তোমাদের মা-বাবা, ভাই-বন্ধু ও আত্মীয়-স্বজনেরা তোমাদের ধরিয়ে দেবে। তারা তোমাদের কাউকে কাউকে হত্যাও করবে।"},{"v":17,"ve":17,"vl":"17","bn":"আমার জন্য সবাই তোমাদের ঘৃণা করবে,"},{"v":18,"ve":18,"vl":"18","bn":"কিন্তু কোনমতেই তোমাদের একটা চুলও ধ্বংস হবে না।"},{"v":19,"ve":19,"vl":"19","bn":"তোমরা স্থির থাকলে তোমাদের সত্যিকারের জীবন পূর্ণতা লাভ করবে।"},{"v":20,"ve":20,"vl":"20","bn":"“যখন তোমরা দেখবে জেরুজালেমকে সৈন্যেরা ঘেরাও করেছে তখন বুঝবে যে, জেরুজালেমের ধ্বংস হবার সময় কাছে এসেছে।"},{"v":21,"ve":21,"vl":"21","bn":"সেই সময় যারা এহুদিয়াতে থাকবে তারা পাহাড়ী এলাকায় পালিয়ে যাক। যারা শহরের মধ্যে থাকবে তারা শহরের বাইরে চলে যাক। যারা গ্রামের দিকে থাকবে তারা কোনমতেই শহরে না আসুক,"},{"v":22,"ve":22,"vl":"22","bn":"কারণ এই দিনগুলো হবে গজবের দিন, আর এতে পাক-কিতাবে যা লেখা আছে তা পূর্ণ হবে।"},{"v":23,"ve":23,"vl":"23","bn":"তখন যারা গর্ভবতী আর যারা সন্তানকে বুকের দুধ খাওয়ায় তাদের অবস্থা কি ভীষণই না হবে! দেশে ভীষণ কষ্ট উপস্থিত হবে এবং ইহুদী লোকদের উপরে আল্লাহ্‌র গজব নেমে আসবে।"},{"v":24,"ve":24,"vl":"24","bn":"তলোয়ার দিয়ে তাদের হত্যা করা হবে এবং সমস্ত জাতির মধ্যে তারা বন্দী হিসাবে ছড়িয়ে থাকবে। যতদিন না অ-ইহুদীদের সময় পূর্ণ হয় ততদিন পর্যন্ত অ-ইহুদীরা জেরুজালেমকে তাদের পায়ের নীচে মাড়াতে থাকবে।"},{"v":25,"ve":25,"vl":"25","bn":"“তখন সূর্য, চাঁদ ও তারাগুলোর মধ্যে অনেক চিহ্ন দেখা যাবে। দুনিয়াতে সমস্ত জাতি কষ্ট পাবে এবং সমুদ্রের গর্জন ও ঢেউয়ের জন্য তারা ভীষণ অস্থির হয়ে উঠবে।"},{"v":26,"ve":26,"vl":"26","bn":"দুনিয়াতে কি আসছে ভেবে ভয়ে লোকে অজ্ঞান হয়ে পড়বে, কারণ চাঁদ-সূর্য-তারা ইত্যাদি আর স্থির থাকবে না।"},{"v":27,"ve":27,"vl":"27","bn":"সেই সময় মহাশক্তি ও মহিমার সংগে ইব্‌ন্তেআদমকে তারা মেঘের মধ্যে আসতে দেখবে।"},{"v":28,"ve":28,"vl":"28","bn":"এই সব ঘটনা ঘটতে শুরু করলে পর তোমরা উঠে দাঁড়ায়ো এবং মুখ তুলো, কারণ তোমাদের মুক্তির সময় কাছে এসেছে।”"},{"v":29,"ve":29,"vl":"29","bn":"এর পরে ঈসা তাঁর সাহাবীদের শিক্ষা দেবার জন্য এই কথা বললেন, “ডুমুর গাছ ও অন্যান্য গাছগুলোকে লক্ষ্য কর।"},{"v":30,"ve":30,"vl":"30","bn":"পাতা বের হতে দেখলে পর তোমরা বুঝতে পার যে, গরমকাল কাছে এসেছে।"},{"v":31,"ve":31,"vl":"31","bn":"সেইভাবে যখন তোমরা এই সব ঘটতে দেখবে তখন বুঝতে পারবে যে, আল্লাহ্‌র রাজ্য কাছে এসে গেছে।"},{"v":32,"ve":32,"vl":"32","bn":"আমি তোমাদের সত্যিই বলছি, যখন এই সব হবে তখনও এই কালের কিছু লোক বেঁচে থাকবে।"},{"v":33,"ve":33,"vl":"33","bn":"আসমান ও জমীনের শেষ হবে, কিন্তু আমার কথা চিরদিন থাকবে।"},{"v":34,"ve":35,"vl":"34-35","bn":"“তোমরা সাবধান থেকো যেন তোমাদের দিল উ\"ছৃংখলতায়, মাতলামিতে ও সংসারের চিন্তার ভারে নুয়ে না পড়ে। তা না হলে ফাঁদ যেমন হঠাৎ বন্ধ হয়ে যায় তেমনি হঠাৎ সেই দিনটা তোমাদের উপরে, এমন কি, দুনিয়ার সব লোকের উপরে এসে পড়বে।"},{"v":36,"ve":36,"vl":"36","bn":"সজাগ থেকো এবং সব সময় মুনাজাত কোরো যেন যা কিছু ঘটবে তা পার হয়ে যেতে এবং ইব্‌ন্তেআদমের সামনে গিয়ে দাঁড়াতে তোমরা শক্তি পাও।”"},{"v":37,"ve":37,"vl":"37","bn":"সেই সময় ঈসা প্রত্যেক দিনই বায়তুল-মোকাদ্দসে শিক্ষা দিতেন, কিন্তু রাতের বেলা বাইরে গিয়ে জৈতুন পাহাড়ে থাকতেন।"},{"v":38,"ve":38,"vl":"38","bn":"সমস্ত লোক তাঁর কথা শুনবার জন্য খুব সকালেই বায়তুল-মোকাদ্দসে উপস্থিত হত।"}],"22":[{"heading":"হযরত ঈসা মসীহ্‌কে হত্যা করবার ষড়যন্ত্র","v":1,"ve":1,"vl":"1","bn":"সেই সময় ইহুদীদের খামিহীন রুটির ঈদ কাছে এসে গিয়েছিল। এটাকে উদ্ধার-ঈদও বলা হয়।"},{"v":2,"ve":2,"vl":"2","bn":"প্রধান ইমামেরা ও আলেমেরা ঈসাকে গোপনে হত্যা করবার উপায় খুঁজছিলেন, কারণ তাঁরা লোকদের ভয় করতেন।"},{"v":3,"ve":3,"vl":"3","bn":"এই সময় এহুদা, যাকে ইষ্কারিয়োৎ বলা হত, তার ভিতরে শয়তান ঢুকল। এই এহুদা ছিল ঈসার বারোজন সাহাবীদের মধ্যে একজন।"},{"v":4,"ve":4,"vl":"4","bn":"কেমন করে ঈসাকে প্রধান ইমামদের ও বায়তুল-মোকাদ্দসের কর্মচারীদের হাতে ধরিয়ে দেবে এই বিষয়ে সে গিয়ে তাঁদের সংগে পরামর্শ করল।"},{"v":5,"ve":5,"vl":"5","bn":"এতে তাঁরা খুব খুশী হয়ে এহুদাকে টাকা দিতে স্বীকার করলেন।"},{"v":6,"ve":6,"vl":"6","bn":"তখন এহুদা রাজী হয়ে উপযুক্ত সুযোগ খুঁজতে লাগল যাতে লোকদের অনুপস্থিতিতে ঈসাকে ধরিয়ে দিতে পারে।"},{"heading":"শেষ উদ্ধার-ঈদের মেজবানী","v":7,"ve":8,"vl":"7-8","bn":"খামিহীন রুটির ঈদের দিনে উদ্ধার-ঈদের মেজবানীর জন্য ভেড়ার বাচ্চা জবাই করা হত। সেই দিনটা উপস্থিত হলে পর ঈসা পিতর ও ইউহোন্নাকে এই বলে পাঠিয়ে দিলেন, “তোমরা গিয়ে আমাদের জন্য উদ্ধার-ঈদের মেজবানী প্রস্তুত কর যেন আমরা তা খেতে পারি।”"},{"v":9,"ve":9,"vl":"9","bn":"তাঁরা ঈসাকে জিজ্ঞাসা করলেন, “আপনি কোথায় এই মেজবানী আমাদের প্রস্তুত করতে বলেন?”"},{"v":10,"ve":11,"vl":"10-11","bn":"ঈসা বললেন, “দেখ, তোমরা যখন শহরে ঢুকবে তখন একজন পুরুষ লোককে এক কলসী পানি নিয়ে যেতে দেখবে। তার পিছন পিছন গিয়ে সে যে ঘরে ঢুকবে সেই ঘরের মালিককে বলবে, ‘হুজুর জানতে চাইছেন, তিনি সাহাবীদের সংগে যেখানে উদ্ধার-ঈদের মেজবানী খেতে পারেন সেই মেহমান্তঘরটা কোথায়?”"},{"v":12,"ve":12,"vl":"12","bn":"তখন সে তোমাদের উপরতলার একটা সাজানো বড় ঘর দেখিয়ে দেবে; সেখানেই সব কিছু প্রস্তুত কোরো।”"},{"v":13,"ve":13,"vl":"13","bn":"ঈসা তাঁদের যেমন বলেছিলেন, তাঁরা গিয়ে সব কিছু সেই রকমই দেখতে পেলেন এবং উদ্ধার-ঈদের মেজবানী প্রস্তুত করলেন।"},{"v":14,"ve":14,"vl":"14","bn":"তারপর সময় মত ঈসা সাহাবীদের সংগে খেতে বসলেন।"},{"v":15,"ve":15,"vl":"15","bn":"তিনি তাঁদের বললেন, “আমি কষ্টভোগ করবার আগে তোমাদের সংগে উদ্ধার-ঈদের এই মেজবানী খাবার আমার খুবই ইচ্ছা ছিল।"},{"v":16,"ve":16,"vl":"16","bn":"আমি তোমাদের বলছি, আল্লাহ্‌র রাজ্যে এর উদ্দেশ্য পূর্ণ না হওয়া পর্যন্ত আমি আর কখনও এই মেজবানী খাব না।”"},{"v":17,"ve":17,"vl":"17","bn":"এর পর ঈসা পেয়ালা নিলেন এবং আল্লাহ্‌কে শুকরিয়া জানিয়ে বললেন, “তোমাদের মধ্যে এটা ভাগ করে নাও,"},{"v":18,"ve":18,"vl":"18","bn":"কারণ আমি তোমাদের বলছি, এখন থেকে আল্লাহ্‌র রাজ্য না আসা পর্যন্ত আমি আর কখনও আংগুর ফলের রস খাব না।”"},{"v":19,"ve":19,"vl":"19","bn":"তারপর তিনি রুটি নিয়ে আল্লাহ্‌কে শুকরিয়া জানালেন। পরে সেই রুটি টুকরা টুকরা করে সাহাবীদের দিয়ে বললেন, “এটা আমার শরীর যা তোমাদের জন্য দেওয়া হবে। আমাকে মনে করবার জন্য এই রকম কোরো।”"},{"v":20,"ve":20,"vl":"20","bn":"খাওয়ার পরে সেইভাবে তিনি পেয়ালাটা তাঁদের দিয়ে বললেন, “আমার রক্তের দ্বারা আল্লাহ্‌র যে নতুন ব্যবস্থা বহাল করা হবে সেই ব্যবস্থার চিহ্ন হল এই পেয়ালা। আমার এই রক্ত তোমাদের জন্য দেওয়া হবে।"},{"v":21,"ve":21,"vl":"21","bn":"দেখ, যে আমাকে ধরিয়ে দেবে তার হাত আমার হাতের সংগে এই টেবিলের উপরেই আছে।"},{"v":22,"ve":22,"vl":"22","bn":"আল্লাহ্‌ যা ঠিক করে রেখেছেন সেই ভাবেই ইব্‌ন্তেআদম মারা যাবেন বটে; কিন্তু হায় সেই লোক, যে তাঁকে ধরিয়ে দেয়!”"},{"v":23,"ve":23,"vl":"23","bn":"সাহাবীরা একে অন্যকে জিজ্ঞাসা করতে লাগলেন যে, তাঁদের মধ্যে কে এমন কাজ করবেন।"},{"heading":"সাহাবীদের সংগে হযরত ঈসা মসীহের কথাবার্তা","v":24,"ve":24,"vl":"24","bn":"কাকে সবচেয়ে বড় বলা হবে এ নিয়ে সাহাবীদের মধ্যে কথা কাটাকাটি হল।"},{"v":25,"ve":25,"vl":"25","bn":"ঈসা তাঁদের বললেন, “অ-ইহুদীদের মধ্যেই বাদশাহ্‌রা প্রভুত্ব করেন আর তাদের শাসনকর্তাদের উপকারী নেতা বলা হয়,"},{"v":26,"ve":26,"vl":"26","bn":"কিন্তু তোমাদের মধ্যে এই রকম হওয়া উচিত নয়। তোমাদের মধ্যে যে সবচেয়ে বড়, সে বরং সবচেয়ে যে ছোট তারই মত হোক, আর যে নেতা, সে সেবাকারীর মত হোক।"},{"v":27,"ve":27,"vl":"27","bn":"কে বড়, যে খেতে বসে, না যে চাকর পরিবেশন করে? যে খেতে বসে, সে নয় কি? কিন্তু আমি তোমাদের মধ্যে সেবাকারীর মত হয়েছি।"},{"v":28,"ve":28,"vl":"28","bn":"“আমার সব দুঃখ-কষ্টের সময়ে তোমরা আমাকে ছেড়ে যাও নি।"},{"v":29,"ve":29,"vl":"29","bn":"আমার পিতা যেমন আমাকে শাসন্তক্ষমতা দান করেছেন তেমনি আমিও তোমাদের ক্ষমতা দান করছি।"},{"v":30,"ve":30,"vl":"30","bn":"এতে আমার রাজ্যে তোমরা আমার সংগে খাওয়া-দাওয়া করবে এবং সিংহাসনে বসে ইসরাইলের বারোটি গোষ্ঠীর বিচার করবে।"},{"v":31,"ve":31,"vl":"31","bn":"“শিমোন, শিমোন, দেখ, শয়তান তোমাদের গমের মত করে চালুনি দিয়ে চেলে দেখবার অনুমতি চেয়েছে।"},{"v":32,"ve":32,"vl":"32","bn":"কিন্তু আমি তোমার জন্য মুনাজাত করেছি যেন তোমার ঈমানে ভাংগন না ধরে। তুমি যখন আমার কাছে ফিরে আসবে তখন তোমার এই ভাইদের শক্তিশালী করে তুলো।”"},{"v":33,"ve":33,"vl":"33","bn":"পিতর ঈসাকে বললেন, “হুজুর, আপনার সংগে আমি জেলে যেতে এবং মরতেও প্রস্তুত আছি।”"},{"v":34,"ve":34,"vl":"34","bn":"জবাবে ঈসা বললেন, “পিতর, আমি তোমাকে বলছি, আজ মোরগ ডাকবার আগে তুমি তিন বার আমাকে অস্বীকার করে বলবে যে, তুমি আমাকে চেন না।”"},{"v":35,"ve":35,"vl":"35","bn":"তারপর ঈসা তাঁর সাহাবীদের বললেন, “আমি যখন তোমাদের টাকার থলি, ঝুলি ও জুতা ছাড়া পাঠিয়েছিলাম তখন কি তোমাদের কোন অভাব হয়েছিল?” সাহাবীরা বললেন, “জ্বী না, হয় নি।”"},{"v":36,"ve":36,"vl":"36","bn":"ঈসা বললেন, “কিন্তু এখন আমি বলছি, যার টাকার থলি বা ঝুলি আছে সে তা নিয়ে যাক। যার ছোরা নেই সে তার চাদর বিক্রি করে একটা ছোরা কিনুক।"},{"v":37,"ve":37,"vl":"37","bn":"পাক-কিতাবে লেখা আছে, ‘তাঁকে গুনাহ্‌গারদের সংগে গোণা হল’। আমি তোমাদের বলছি, এই কথা আমার মধ্যেই পূর্ণ হতে হবে, কারণ আমার বিষয়ে যা লেখা আছে তা পূর্ণ হতে যাচ্ছে।”"},{"v":38,"ve":38,"vl":"38","bn":"তখন সাহাবীরা বললেন, “হুজুর, দেখুন, এখানে দু’টা ছোরা আছে।” ঈসা জবাব দিলেন, “থাক্‌, আর নয়।”"},{"heading":"মুনাজাতের সময়ে হযরত ঈসা মসীহের দুঃখ প্রকাশ","v":39,"ve":39,"vl":"39","bn":"ঈসা সেই জায়গা ছেড়ে নিজের নিয়ম মত জৈতুন পাহাড়ে গেলেন। তাঁর সাহাবীরা তাঁর পিছনে পিছনে গেলেন।"},{"v":40,"ve":40,"vl":"40","bn":"ঠিক জায়গায় পৌঁছাবার পর ঈসা তাঁদের বললেন, “মুনাজাত কর যেন পরীক্ষায় না পড়।”"},{"v":41,"ve":41,"vl":"41","bn":"তারপর ঈসা সাহাবীদের কাছ থেকে কিছু দূরে গিয়ে হাঁটু পেতে মুনাজাত করতে লাগলেন,"},{"v":42,"ve":42,"vl":"42","bn":"“পিতা, যদি তুমি চাও তবে এই দুঃখের পেয়ালা আমার কাছ থেকে সরিয়ে নাও। তবুও আমার ইচ্ছামত নয়, তোমার ইচ্ছামতই হোক।”"},{"v":43,"ve":43,"vl":"43","bn":"তখন বেহেশত থেকে একজন ফেরেশতা এসে ঈসাকে শক্তি দান করলেন।"},{"v":44,"ve":44,"vl":"44","bn":"মনের কষ্টে ঈসা আরও আকুলভাবে মুনাজাত করলেন। তাঁর গায়ের ঘাম রক্তের ফোঁটার মত হয়ে মাটিতে পড়তে লাগল।"},{"v":45,"ve":46,"vl":"45-46","bn":"মুনাজাতের পরে তিনি উঠে তাঁর সাহাবীদের কাছে আসলেন। মনের দুঃখে ক্লান্ত হয়ে সাহাবীরা ঘুমিয়ে পড়েছেন দেখে ঈসা তাঁদের বললেন, “কেন ঘুমা\"ছ? উঠে মুনাজাত কর যেন পরীক্ষায় না পড়।”"},{"v":47,"ve":47,"vl":"47","bn":"ঈসা তখনও কথা বলছেন এমন সময় অনেক লোক সেখানে আসল। এহুদা নামে তাঁর বারোজন সাহাবীদের মধ্যে একজন সেই লোকদের আগে আগে আসছিল। এহুদা ঈসাকে চুমু দেবার জন্য তাঁর কাছে আসল।"},{"v":48,"ve":48,"vl":"48","bn":"তখন ঈসা তাকে বললেন, “এহুদা, চুমু দিয়ে কি ইব্‌ন্তেআদমকে ধরিয়ে দিচ্ছ?”"},{"heading":"শত্রুদের হাতে হযরত ঈসা মসীহ্‌","v":49,"ve":49,"vl":"49","bn":"যাঁরা ঈসার চারপাশে ছিলেন তাঁরা বুঝলেন কি হতে যাচ্ছে। এইজন্য তাঁরা ঈসাকে বললেন, “হুজুর, আমরা কি ছোরা দিয়ে আঘাত করব?”"},{"v":50,"ve":50,"vl":"50","bn":"সাহাবীদের মধ্যে একজন ছোরার আঘাতে মহা-ইমামের গোলামের ডান কানটা কেটে ফেললেন।"},{"v":51,"ve":51,"vl":"51","bn":"ঈসা বললেন, “থাক্‌, আর নয়।” এই বলে তিনি লোকটির কান ছুঁয়ে তাকে ভাল করলেন।"},{"v":52,"ve":52,"vl":"52","bn":"যে সব প্রধান ইমামেরা, বায়তুল-মোকাদ্দসের কর্মচারীরা এবং বৃদ্ধ নেতারা ঈসাকে ধরতে এসেছিলেন ঈসা তাঁদের বললেন, “আমি কি ডাকাত যে, আপনারা ছোরা ও লাঠি নিয়ে এসেছেন?"},{"v":53,"ve":53,"vl":"53","bn":"বায়তুল-মোকাদ্দসে দিনের পর দিন আমি আপনাদের সামনে ছিলাম, কিন্তু তখন তো আপনারা আমাকে ধরেন নি। তবে এখন অবশ্য আপনাদেরই সময়; অন্ধকারের ক্ষমতা এখন দেখা যাচ্ছে।”"},{"heading":"হযরত পিতরের অস্বীকার","v":54,"ve":54,"vl":"54","bn":"তখন তাঁরা ঈসাকে ধরে মহা-ইমামের বাড়ীতে নিয়ে গেলেন। পিতর দূরে থেকে পিছনে পিছনে যাচ্ছিলেন।"},{"v":55,"ve":55,"vl":"55","bn":"উঠানের মাঝখানে যারা আগুন জ্বেলে বসে ছিল পিতর এসে তাদের মধ্যে বসলেন।"},{"v":56,"ve":56,"vl":"56","bn":"একজন চাকরাণী সেই আগুনের আলোতে পিতরকে দেখতে পেল এবং ভাল করে তাকিয়ে দেখে বলল, “এই লোকটাও ওর সংগে ছিল।”"},{"v":57,"ve":57,"vl":"57","bn":"পিতর অস্বীকার করে বললেন, “আমি ওকে চিনি না।”"},{"v":58,"ve":58,"vl":"58","bn":"কিছুক্ষণ পরে আর একজন লোক তাঁকে দেখে বলল, “তুমিও তো ওদের একজন।” পিতর বললেন, “না, আমি নই।”"},{"v":59,"ve":59,"vl":"59","bn":"এক ঘণ্টা পরে আর একজন জোর দিয়ে বলল, “এই লোকটি নিশ্চয়ই ওর সংগে ছিল, কারণ এ তো গালীল প্রদেশের লোক।”"},{"v":60,"ve":60,"vl":"60","bn":"পিতর বললেন, “দেখ, তুমি কি বলছ আমি বুঝতে পারছি না।” পিতরের কথা শেষ হতে না হতেই একটা মোরগ ডেকে উঠল।"},{"v":61,"ve":61,"vl":"61","bn":"তখন ঈসা মুখ ফিরিয়ে পিতরের দিকে দেখলেন। এতে যে কথা ঈসা তাঁকে বলেছিলেন সেই কথা পিতরের মনে পড়ল, “আজ মোরগ ডাকবার আগে তুমি তিন বার বলবে যে, তুমি আমাকে চেন না।”"},{"v":62,"ve":62,"vl":"62","bn":"তখন পিতর বাইরে গিয়ে খুব কাঁদতে লাগলেন।"},{"heading":"মহাসভার সামনে হযরত ঈসা মসীহের বিচার","v":63,"ve":63,"vl":"63","bn":"যারা ঈসাকে পাহারা দিচ্ছিল তারা তাঁকে ঠাট্টা করতে ও মারতে লাগল।"},{"v":64,"ve":64,"vl":"64","bn":"তারা ঈসার চোখ বেঁধে দিয়ে বলল, “বল্‌ তো দেখি, কে তোকে মারল?”"},{"v":65,"ve":65,"vl":"65","bn":"এইভাবে তারা আরও অনেক কথা বলে তাঁকে অপমান করল।"},{"v":66,"ve":66,"vl":"66","bn":"সকাল হলে পর ইহুদীদের বৃদ্ধনেতারা, প্রধান ইমামেরা এবং আলেমেরা একসংগে জমায়েত হলেন এবং ঈসাকে তাঁদের মহাসভার সামনে এনে বললেন,"},{"v":67,"ve":68,"vl":"67-68","bn":"“তুমি যদি মসীহ্‌ হও তবে আমাদের বল।” ঈসা বললেন, “আমি যদি বলি তবুও আপনারা কোনমতেই বিশ্বাস করবেন না এবং আপনাদের কিছু জিজ্ঞাসা করলে জবাব দেবেন না।"},{"v":69,"ve":69,"vl":"69","bn":"কিন্তু ইব্‌ন্তেআদম এখন থেকে সর্বশক্তিমান আল্লাহ্‌র ডানপাশে বসে থাকবেন।”"},{"v":70,"ve":70,"vl":"70","bn":"তখন সকলে জিজ্ঞাসা করলেন, “তাহলে তুমি কি ইব্‌নুল্লাহ্‌?” তিনি তাঁদের বললেন, “আপনারা ঠিকই বলছেন যে, আমিই সে-ই।”"},{"v":71,"ve":71,"vl":"71","bn":"তখন নেতারা বললেন, “আমাদের আর সাক্ষ্যের কি দরকার? আমরা নিজেরাই তো ওর মুখে শুনলাম।”"}],"23":[{"heading":"পীলাতের সামনে হযরত ঈসা মসীহের বিচার","v":1,"ve":1,"vl":"1","bn":"তখন সেই সভার সকলে উঠে ঈসাকে রোমীয় প্রধান শাসনকর্তা পীলাতের কাছে নিয়ে গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তাঁরা এই বলে ঈসার বিরুদ্ধে নালিশ জানাতে লাগলেন, “আমরা দেখেছি, এই লোকটা সরকারের বিরুদ্ধে আমাদের লোকদের নিয়ে যাচ্ছে। সে সম্রাটকে খাজনা দিতে নিষেধ করে এবং বলে সে নিজেই মসীহ্‌, একজন বাদশাহ্‌।”"},{"v":3,"ve":3,"vl":"3","bn":"পীলাত ঈসাকে জিজ্ঞাসা করলেন, “তুমি কি ইহুদীদের বাদশাহ্‌?” ঈসা বললেন, “আপনি ঠিক কথাই বলছেন।”"},{"v":4,"ve":4,"vl":"4","bn":"তখন পীলাত প্রধান ইমামদের ও সমস্ত লোকদের বললেন, “আমি তো এই লোকটির কোন দোষই দেখতে পাচ্ছি না।”"},{"v":5,"ve":5,"vl":"5","bn":"কিন্তু তাঁরা জিদ করে বলতে লাগলেন, “এহুদিয়া প্রদেশের সব জায়গায় শিক্ষা দিয়ে এ লোকদের ক্ষেপিয়ে তুলছে। গালীল প্রদেশ থেকে সে শুরু করেছে, আর এখন এখানে এসেছে।”"},{"v":6,"ve":6,"vl":"6","bn":"এই কথা শুনে পীলাত জিজ্ঞাসা করলেন ঈসা গালীল প্রদেশের লোক কি না।"},{"v":7,"ve":7,"vl":"7","bn":"শাসনকর্তা হেরোদের শাসনের অধীনে যে প্রদেশ আছে, ঈসা সেই জায়গার লোক জানতে পেরে পীলাত তাঁকে হেরোদের কাছে পাঠিয়ে দিলেন। সেই সময় হেরোদও জেরুজালেমে ছিলেন।"},{"v":8,"ve":8,"vl":"8","bn":"ঈসাকে দেখে হেরোদ খুব খুশী হলেন। তিনি ঈসার সম্বন্ধে অনেক কথা শুনেছিলেন, তাই তিনি অনেক দিন ধরে তাঁকে দেখতে চাইছিলেন। হেরোদ আশা করেছিলেন ঈসা তাঁকে কোন অলৌকিক কাজ করে দেখাবেন।"},{"v":9,"ve":9,"vl":"9","bn":"তিনি ঈসাকে অনেক প্রশ্ন করলেন, কিন্তু ঈসা কোন কথারই জবাব দিলেন না।"},{"v":10,"ve":10,"vl":"10","bn":"প্রধান ইমামেরা এবং আলেমেরা সেখানে দাঁড়িয়ে চিৎকার করে ঈসাকে দোষ দিতে লাগলেন।"},{"v":11,"ve":11,"vl":"11","bn":"তখন হেরোদ ঈসাকে অপমান ও ঠাট্টা করলেন, আর তাঁর সৈন্যেরাও তা-ই করল। তার পরে ঈসাকে জমকালো একটা পোশাক পরিয়ে তিনি তাঁকে পীলাতের কাছে পাঠিয়ে দিলেন।"},{"v":12,"ve":12,"vl":"12","bn":"এর আগে হেরোদ ও পীলাতের মধ্যে শত্রুতা ছিল, কিন্তু সেই দিন থেকে তাঁদের মধ্যে বন্ধুত্ব হল।"},{"v":13,"ve":13,"vl":"13","bn":"পীলাত তখন প্রধান ইমামদের, নেতাদের এবং সাধারণ লোকদের ডেকে একত্র করে বললেন,"},{"v":14,"ve":14,"vl":"14","bn":"“আপনারা এই লোকটিকে এই দোষ দিয়ে আমার কাছে এনেছেন যে, লোকদের সে সরকারের বিরুদ্ধে নিয়ে যাচ্ছে। কিন্তু তাকে আমি আপনাদের সামনেই জেরা করেছি। আপনারা তার বিরুদ্ধে যে সব দোষ দিচ্ছেন তার একটাতেও সে দোষী বলে আমি প্রমাণ পাই নি।"},{"v":15,"ve":15,"vl":"15","bn":"হেরোদও নিশ্চয় তার কোন দোষ পান নি, কারণ তিনি তাকে আমাদের কাছে ফেরৎ পাঠিয়েছেন। আপনারা দেখতে পাচ্ছেন, হত্যা করবার মত এমন কোন অন্যায় কাজও সে করে নি।"},{"v":16,"ve":16,"vl":"16","bn":"তাই আমি তাকে শাস্তি দিয়ে ছেড়ে দেব।”"},{"v":17,"ve":17,"vl":"17","bn":"তিনি এই কথা বললেন কারণ উদ্ধার-ঈদের সময়ে প্রত্যেক বারই তাঁকে একজন কয়েদীকে ছেড়ে দিতে হত।"},{"v":18,"ve":18,"vl":"18","bn":"কিন্তু লোকেরা একসংগে চেঁচিয়ে বলতে লাগল, “ওকে দূর করুন, বারাব্বাকে আমাদের কাছে ছেড়ে দিন।”"},{"v":19,"ve":19,"vl":"19","bn":"এই বারাব্বাকে শহরের মধ্যে বিদ্রোহ ও খুনাখুনির জন্য জেলে দেওয়া হয়েছিল।"},{"v":20,"ve":20,"vl":"20","bn":"পীলাত কিন্তু ঈসাকে ছেড়ে দিতে চেয়েছিলেন, সেইজন্য তিনি লোকদের আবার সেই একই কথা বললেন।"},{"v":21,"ve":21,"vl":"21","bn":"কিন্তু লোকেরা এই বলে চেঁচাতেই থাকল, “ওকে ক্রুশে দিন, ক্রুশে দিন।”"},{"v":22,"ve":22,"vl":"22","bn":"পীলাত তৃতীয়বার লোকদের বললেন, “কেন, এই লোকটি কি দোষ করেছে? আমি তো তার কোন দোষই দেখতে পাচ্ছি না যাতে তাকে মৃত্যুর শাস্তি দেওয়া যায়। সেইজন্য তাকে আমি অন্য শাস্তি দেবার পর ছেড়ে দেব।”"},{"v":23,"ve":23,"vl":"23","bn":"কিন্তু লোকেরা ঈসাকে ক্রুশের উপরে হত্যা করবার জন্য চিৎকার করতে থাকল এবং শেষে তারা চেঁচিয়েই জয়ী হল। পীলাত লোকদের কথা মেনে নেওয়া ঠিক করলেন।"},{"v":24,"ve":25,"vl":"24-25","bn":"বিদ্রোহ ও খুনের জন্য যাকে জেলে দেওয়া হয়েছিল লোকেরা তাকেই চেয়েছিল; সেইজন্য পীলাত সেই লোককে ছেড়ে দিলেন এবং লোকদের ইচ্ছামত ঈসাকে হত্যা করবার জন্য তাদের হাতে দিলেন।"},{"heading":"ক্রুশের উপরে হযরত ঈসা মসীহ্‌","v":26,"ve":26,"vl":"26","bn":"সৈন্যেরা যখন ঈসাকে নিয়ে যাচ্ছিল তখন শিমোন নামে কুরীণী শহরের একজন লোক গ্রামের দিক থেকে আসছিল। সৈন্যেরা তাকে জোর করে ধরে ক্রুশটা তার কাঁধে তুলে দিল যেন সে ঈসার পিছনে তা বয়ে নিয়ে যেতে পারে।"},{"v":27,"ve":27,"vl":"27","bn":"অনেক লোক ঈসার পিছনে পিছনে যাচ্ছিল। তাদের মধ্যে অনেক স্ত্রীলোকও ছিল। তারা বুক চাপ্‌ড়ে কাঁদছিল।"},{"v":28,"ve":28,"vl":"28","bn":"ঈসা তাদের দিকে ফিরে বললেন, “জেরুজালেমের মেয়েরা, আমার জন্য কেঁদো না। তোমাদের নিজেদের জন্য এবং তোমাদের ছেলেমেয়েদের জন্য কাঁদ,"},{"v":29,"ve":29,"vl":"29","bn":"কারণ এমন দিন আসছে যখন লোকে বলবে, ‘যাদের কখনও ছেলেমেয়ে হয় নি এবং যারা কখনও বুকের দুধ শিশুদের খাওয়ায় নি সেই বন্ধ্যা স্ত্রীলোকেরা ধন্যা।’"},{"v":30,"ve":30,"vl":"30","bn":"সেই সময়ে লোকে বড় বড় পাহাড়কে বলবে, ‘আমাদের উপর পড়,’ আর ছোট ছোট পাহাড়কে বলবে, ‘আমাদের ঢেকে রাখ।’"},{"v":31,"ve":31,"vl":"31","bn":"গাছ সবুজ থাকতে যদি লোকে এই রকম করে তবে গাছ শুকনা হলে পর কিনা হবে!”"},{"v":32,"ve":32,"vl":"32","bn":"সৈন্যেরা দু’জন দোষী লোককেও হত্যা করবার জন্য ঈসার সংগে নিয়ে চলল।"},{"v":33,"ve":33,"vl":"33","bn":"যে জায়গাটাকে মাথার খুলি বলা হত সেখানে পৌঁছে তারা ঈসাকে ও সেই দু’জন দোষীকে ক্রুশে দিল- একজনকে ঈসার ডান দিকে ও অন্যজনকে বাঁদিকে।"},{"v":34,"ve":34,"vl":"34","bn":"তখন ঈসা বললেন, “পিতা, এদের মাফ কর, কারণ এরা কি করছে তা জানে না।” তারা গুলিবাঁট করে ঈসার কাপড়-চোপড় নিজেদের মধ্যে ভাগ করে নিল।"},{"v":35,"ve":35,"vl":"35","bn":"লোকেরা দাঁড়িয়ে দেখছিল। ধর্ম-নেতারা ঈসাকে ঠাট্টা করে বললেন, “সে তো অন্যদের রক্ষা করত। যদি সে আল্লাহ্‌র মসীহ্‌, তাঁর বাছাই-করা বান্দা হয় তবে নিজেকে রক্ষা করুক!”"},{"v":36,"ve":36,"vl":"36","bn":"সৈন্যেরাও তাঁকে ঠাট্টা করতে লাগল। তারা ঈসাকে খেতে দেবার জন্য তাঁর কাছে সিরকা নিয়ে গিয়ে বলল,"},{"v":37,"ve":37,"vl":"37","bn":"“তুমি যদি ইহুদীদের বাদশাহ্‌ হও তবে নিজেকে রক্ষা কর।”"},{"v":38,"ve":38,"vl":"38","bn":"ক্রুশে তাঁর মাথার উপরের দিকে একটা ফলকে এই কথা লেখা ছিল, “এই লোকটি ইহুদীদের বাদশাহ্‌।”"},{"v":39,"ve":39,"vl":"39","bn":"যে দু’জন দোষী লোককে সেখানে ক্রুশে টাংগানো হয়েছিল তাদের মধ্যে একজন ঈসাকে টিট্‌কারি দিয়ে বলল, “তুমি নাকি মসীহ্‌? তাহলে নিজেকে ও আমাদের রক্ষা কর।”"},{"v":40,"ve":40,"vl":"40","bn":"তখন অন্য লোকটি তাকে বকুনি দিয়ে বলল, “তুমি কি আল্লাহ্‌কে ভয় কর না? তুমি তো একই রকম শাস্তি পাচ্ছ।"},{"v":41,"ve":41,"vl":"41","bn":"আমরা উচিত শাস্তি পাচ্ছি। আমাদের যা পাওনা আমরা তা-ই পাচ্ছি, কিন্তু এই লোকটি তো কোন দোষ করে নি।”"},{"v":42,"ve":42,"vl":"42","bn":"তারপর সে বলল, “ঈসা, আপনি যখন রাজত্ব করতে ফিরে আসবেন তখন আমার কথা মনে করবেন।”"},{"v":43,"ve":43,"vl":"43","bn":"জবাবে ঈসা তাকে বললেন, “আমি তোমাকে সত্যি বলছি, তুমি আজকেই আমার সংগে জান্নাতুল-ফেরদৌসে উপস্থিত হবে।”"},{"heading":"হযরত ঈসা মসীহের মৃত্যু","v":44,"ve":45,"vl":"44-45","bn":"তখন বেলা প্রায় দুপুর। সূর্য আলো দেওয়া বন্ধ করল এবং সারা দেশ অন্ধকার হয়ে গেল। বেলা তিনটা পর্যন্ত সেই রকমই রইল। বায়তুল-মোকাদ্দসের পর্দাটা মাঝখানে চিরে দু’ভাগ হয়ে গেল।"},{"v":46,"ve":46,"vl":"46","bn":"ঈসা চিৎকার করে বললেন, “পিতা, আমি তোমার হাতে আমার রূহ্‌ তুলে দিলাম।” এই কথা বলে তিনি প্রাণত্যাগ করলেন।"},{"v":47,"ve":47,"vl":"47","bn":"এই সব দেখে রোমীয় শত-সেনাপতি আল্লাহ্‌র প্রশংসা করে বললেন, “সত্যিই লোকটি ধার্মিক ছিল।”"},{"v":48,"ve":48,"vl":"48","bn":"যে লোকেরা সেখানে জমায়েত হয়েছিল তারা এই সমস্ত ঘটনা দেখে বুক চাপ্‌ড়াতে চাপ্‌ড়াতে সেখান থেকে ফিরে গেল।"},{"v":49,"ve":49,"vl":"49","bn":"যাঁরা ঈসাকে চিনতেন এবং যে স্ত্রীলোকেরা গালীল থেকে তাঁর সংগে সংগে এসেছিলেন তাঁরা সবাই দূরে দাঁড়িয়ে সব কিছু দেখছিলেন।"},{"heading":"হযরত ঈসা মসীহের কবর","v":50,"ve":50,"vl":"50","bn":"ইউসুফ নামে একজন সৎ ও ধার্মিক লোক মহাসভার সদস্য ছিলেন। তিনি অরিমাথিয়া নামে ইহুদীদের একটা গ্রামের লোক।"},{"v":51,"ve":51,"vl":"51","bn":"ঈসার বিষয়ে সভার লোকদের সংগে তিনি একমত হতে পারেন নি। তিনি আল্লাহ্‌র রাজ্যের জন্য অপেক্ষা করছিলেন।"},{"v":52,"ve":52,"vl":"52","bn":"পীলাতের কাছে গিয়ে তিনি ঈসার লাশটি চেয়ে নিলেন।"},{"v":53,"ve":53,"vl":"53","bn":"পরে লাশটি ক্রুশ থেকে নামিয়ে কাফন দিয়ে জড়ালেন এবং পাথর কেটে তৈরী করা একটা কবরের মধ্যে দাফন করলেন। সেই কবরে আর কখনও কাউকে দাফন করা হয় নি।"},{"v":54,"ve":54,"vl":"54","bn":"সেই দিনটা ছিল বিশ্রামবারের আয়োজনের দিন। বিশ্রামবার প্রায় শুরু হয়ে গিয়েছিল।"},{"v":55,"ve":55,"vl":"55","bn":"যে স্ত্রীলোকেরা ঈসার সংগে গালীল থেকে এসেছিলেন তাঁরা ইউসুফের পিছনে পিছনে গিয়ে কবরটি দেখলেন এবং ঈসার লাশ কিভাবে দাফন করা হল তাও দেখলেন।"},{"v":56,"ve":56,"vl":"56","bn":"তারপর তাঁরা ফিরে গিয়ে তাঁর লাশের জন্য খোশবু মসলা এবং মলম তৈরী করলেন। এর পরে তাঁরা মূসার হুকুম মত বিশ্রামবারে বিশ্রাম করলেন।"}],"24":[{"heading":"মৃত্যুর উপরে জয়লাভ","v":1,"ve":1,"vl":"1","bn":"সপ্তার প্রথম দিনের খুব সকালবেলা সেই স্ত্রীলোকেরা সেই খোশবু মসলা নিয়ে কবরের কাছে গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তাঁরা দেখলেন কবরের মুখ থেকে পাথরখানা সরিয়ে রাখা হয়েছে,"},{"v":3,"ve":3,"vl":"3","bn":"কিন্তু কবরের ভিতরে গিয়ে তাঁরা হযরত ঈসার লাশ দেখতে পেলেন না।"},{"v":4,"ve":4,"vl":"4","bn":"যখন তাঁরা অবাক হয়ে সেই বিষয়ে ভাবছিলেন তখন বিদ্যুতের মত ঝক্‌ঝকে কাপড় পরা দু’জন লোক তাঁদের পাশে এসে দাঁড়ালেন।"},{"v":5,"ve":5,"vl":"5","bn":"এতে স্ত্রীলোকেরা ভয় পেয়ে মাথা নীচু করলেন। লোক দু’টি তাঁদের বললেন, “যিনি জীবিত তাঁকে মৃতদের মধ্যে তালাশ করছ কেন?"},{"v":6,"ve":6,"vl":"6","bn":"তিনি এখানে নেই; তিনি জীবিত হয়ে উঠেছেন। তিনি যখন গালীলে ছিলেন তখন তিনি তোমাদের কাছে যা বলেছিলেন তা মনে করে দেখ।"},{"v":7,"ve":7,"vl":"7","bn":"তিনি বলেছিলেন, ইব্‌ন্তেআদমকে গুনাহ্‌গার লোকদের হাতে ধরিয়ে দেওয়া হবে। তার পরে তাঁকে ক্রুশের উপরে হত্যা করা হবে এবং তৃতীয় দিনে তাঁকে আবার জীবিত হয়ে উঠতে হবে।”"},{"v":8,"ve":8,"vl":"8","bn":"তখন তাঁদের সেই কথা মনে পড়ল।"},{"v":9,"ve":9,"vl":"9","bn":"তাঁরা কবর থেকে ফিরে গিয়ে সেই এগারোজন সাহাবী এবং অন্য সকলকে এই সব কথা জানালেন।"},{"v":10,"ve":10,"vl":"10","bn":"সেই স্ত্রীলোকদের মধ্যে ছিলেন মগ্‌দলীনী মরিয়ম, যোহানা ও ইয়াকুবের মা মরিয়ম। তাঁদের সংগে আর অন্য যে স্ত্রীলোকেরা ছিলেন তাঁরাও এই সমস্ত কথা সাহাবীদের কাছে বললেন।"},{"v":11,"ve":11,"vl":"11","bn":"কিন্তু সেই সব কথা তাঁদের কাছে বাজে কথার মতই মনে হল। সেইজন্য সেই স্ত্রীলোকদের কথা তাঁরা বিশ্বাস করলেন না।"},{"v":12,"ve":12,"vl":"12","bn":"পিতর কিন্তু উঠে দৌড়ে কবরের কাছে গেলেন এবং নীচু হয়ে কেবল কাপড়গুলোই দেখতে পেলেন। যা ঘটেছে তাতে আশ্চর্য হয়ে তিনি ফিরে আসলেন।"},{"heading":"ইম্মায়ূ গ্রামের পথে","v":13,"ve":13,"vl":"13","bn":"সেই দিনেই দু’জন সাহাবী ইম্মায়ূ নামে একটা গ্রামে যাচ্ছিলেন। গ্রামটা জেরুজালেম থেকে প্রায় সাত মাইল দূরে ছিল।"},{"v":14,"ve":14,"vl":"14","bn":"যা ঘটেছে তা নিয়ে তাঁরা আলাপ-আলোচনা করছিলেন।"},{"v":15,"ve":15,"vl":"15","bn":"সেই সময় ঈসা নিজেই সেখানে উপস্থিত হয়ে তাঁদের সংগে হাঁটতে শুরু করলেন।"},{"v":16,"ve":16,"vl":"16","bn":"তাঁদের চোখ যেন বন্ধ হয়ে গিয়েছিল, তাই তাঁরা ঈসাকে চিনতে পারলেন না।"},{"v":17,"ve":17,"vl":"17","bn":"তখন ঈসা তাঁদের বললেন, “আপনারা কি কথা বলতে বলতে যাচ্ছেন?” সেই দু’জন উম্মত ম্লান মুখে দাঁড়িয়ে রইলেন।"},{"v":18,"ve":18,"vl":"18","bn":"তখন ক্লিয়পা নামে তাঁদের মধ্যে একজন ঈসাকে জিজ্ঞাসা করলেন, “আপনিই কি জেরুজালেমের একমাত্র লোক যিনি জানেন না এই কয়দিনে সেখানে কি কি ঘটছে?”"},{"v":19,"ve":19,"vl":"19","bn":"ঈসা তাঁদের বললেন, “কি কি ঘটেছে?” তাঁরা বললেন, “নাসরত গ্রামের ঈসাকে নিয়ে যা যা ঘটেছে। তিনি নবী ছিলেন। তিনি কাজে ও কথায় আল্লাহ্‌ ও সমস্ত লোকের চোখে শক্তিশালী ছিলেন।"},{"v":20,"ve":20,"vl":"20","bn":"আমাদের প্রধান ইমামেরা ও ধর্ম-নেতারা তাঁকে রোমীয়দের হাতে ধরিয়ে দিয়েছিলেন যাতে তারা তাঁর বিচার করে তাঁকে মৃত্যুর শাস্তি দেয়। পরে সেই ইহুদী নেতারা তাঁকে ক্রুশে দিয়েছিলেন।"},{"v":21,"ve":21,"vl":"21","bn":"আমরা আশা করেছিলাম তিনিই ইসরাইল জাতিকে মুক্ত করবেন। কেবল তা-ই নয়, আজ তিন দিন হল এই সব ঘটনা ঘটেছে।"},{"v":22,"ve":22,"vl":"22","bn":"আবার আমাদের দলের কয়েকজন স্ত্রীলোক আমাদের অবাক করেছেন। তাঁরা খুব সকালে ঈসার কবরে গিয়েছিলেন,"},{"v":23,"ve":23,"vl":"23","bn":"কিন্তু সেখানে তাঁর লাশ দেখতে পান নি। তাঁরা ফিরে এসে বললেন, তাঁরা ফেরেশতাদের দেখা পেয়েছেন আর সেই ফেরেশতারা তাঁদের বলেছেন যে, ঈসা বেঁচে আছেন।"},{"v":24,"ve":24,"vl":"24","bn":"তখন আমাদের সংগে যাঁরা ছিলেন তাঁদের মধ্যে কয়েকজন কবরে গিয়ে স্ত্রীলোকেরা যেমন বলেছিলেন ঠিক তেমনি দেখতে পেলেন, কিন্তু ঈসাকে দেখতে পেলেন না।”"},{"v":25,"ve":25,"vl":"25","bn":"তখন ঈসা তাঁদের বললেন, “আপনারা কিছুই বোঝেন না। আপনাদের মন এমন অসাড় যে, নবীরা যা বলেছেন তা আপনারা বিশ্বাস করেন না।"},{"v":26,"ve":26,"vl":"26","bn":"এই সমস্ত কষ্ট ভোগ করে কি মসীহের মহিমা লাভ করবার কথা ছিল না?”"},{"v":27,"ve":27,"vl":"27","bn":"এর পরে তিনি মূসার এবং সমস্ত নবীদের কিতাব থেকে শুরু করে গোটা পাক-কিতাবের মধ্যে তাঁর নিজের বিষয়ে যা যা লেখা আছে তা সবই তাঁদের বুঝিয়ে বললেন।"},{"v":28,"ve":28,"vl":"28","bn":"তাঁরা যে গ্রামে যাচ্ছিলেন সেই গ্রামের কাছাকাছি আসলে পর ঈসা আরও দূরে যাবার ভাব দেখালেন।"},{"v":29,"ve":29,"vl":"29","bn":"তখন তাঁরা খুব সাধাসাধি করে তাঁকে বললেন, “এখন বেলা গেছে, সন্ধ্যা হয়েছে। আপনি আমাদের সংগে থাকুন।” এতে তিনি তাঁদের সংগে থাকবার জন্য ঘরে ঢুকলেন।"},{"v":30,"ve":30,"vl":"30","bn":"যখন তিনি তাঁদের সংগে খেতে বসলেন তখন রুটি নিয়ে আল্লাহ্‌কে শুকরিয়া জানালেন এবং তা টুকরা করে তাঁদের দিলেন।"},{"v":31,"ve":31,"vl":"31","bn":"তখন তাঁদের চোখ খুলে গেল; তাঁরা ঈসাকে চিনতে পারলেন, কিন্তু তার সংগে সংগেই তাঁকে আর দেখা গেল না।"},{"v":32,"ve":32,"vl":"32","bn":"তখন তাঁরা একে অন্যকে বললেন, “রাস্তায় যখন তিনি আমাদের সংগে কথা বলছিলেন এবং পাক-কিতাব বুঝিয়ে দিচ্ছিলেন তখন আমাদের অন্তর কি জ্বলে জ্বলে উঠছিল না?”"},{"v":33,"ve":33,"vl":"33","bn":"তখনই সেই দু’জন উঠে জেরুজালেমে গেলেন এবং সেই এগারোজন সাহাবী ও তাঁদের সংগে অন্যদেরও এক জায়গায় দেখতে পেলেন।"},{"v":34,"ve":34,"vl":"34","bn":"হযরত ঈসা যে সত্যিই জীবিত হয়ে উঠেছেন এবং শিমোনকে দেখা দিয়েছেন তা নিয়ে তখন তাঁরা আলোচনা করছিলেন।"},{"v":35,"ve":35,"vl":"35","bn":"সেই দু’জন সাহাবী রাস্তায় যা হয়েছিল তা তাঁদের জানালেন। তাঁরা আরও জানালেন, তিনি যখন রুটি টুকরা টুকরা করছিলেন তখন কেমন করে তাঁরা তাঁকে চিনতে পেরেছিলেন।"},{"heading":"সাহাবীদের সংগে হযরত ঈসা মসীহের সাক্ষাৎ","v":36,"ve":36,"vl":"36","bn":"সেই সাহাবীরা যখন এই কথা বলছিলেন তখন ঈসা নিজে তাঁদের মধ্যে এসে দাঁড়িয়ে তাঁদের সবাইকে বললেন, “আস্‌সালামু আলাইকুম।”"},{"v":37,"ve":37,"vl":"37","bn":"তাঁরা ভূত দেখছেন ভেবে খুব ভয় পেলেন।"},{"v":38,"ve":38,"vl":"38","bn":"ঈসা তাঁদের বললেন, “কেন তোমরা অস্থির হচ্ছ আর কেনই বা তোমাদের মনে সন্দেহ জাগছে?"},{"v":39,"ve":39,"vl":"39","bn":"আমার হাত ও পা দেখ। দেখ, এ আমি। আমাকে ছুঁয়ে দেখ, কারণ ভূতের তো আমার মত হাড়-মাংস নেই।”"},{"v":40,"ve":40,"vl":"40","bn":"এই কথা বলে ঈসা তাঁর হাত ও পা তাঁদের দেখালেন।"},{"v":41,"ve":41,"vl":"41","bn":"কিন্তু তাঁরা এত আশ্চর্য ও আনন্দিত হয়েছিলেন যে, বিশ্বাস করতে পারছিলেন না। তখন ঈসা তাঁদের বললেন, “তোমাদের এখানে কি কোন খাবার আছে?”"},{"v":42,"ve":42,"vl":"42","bn":"তাঁরা তাঁকে এক টুকরা ভাজা মাছ দিলেন।"},{"v":43,"ve":43,"vl":"43","bn":"তিনি তা নিয়ে তাঁদের সামনেই খেলেন।"},{"v":44,"ve":44,"vl":"44","bn":"তারপর তিনি তাঁদের বললেন, “আমি যখন তোমাদের সংগে ছিলাম তখন বলেছিলাম, মূসার তৌরাত শরীফে, নবীদের কিতাবে ও জবুর শরীফের মধ্যে আমার বিষয়ে যে যে কথা লেখা আছে তার সব পূর্ণ হতেই হবে।”"},{"v":45,"ve":46,"vl":"45-46","bn":"পাক-কিতাব বুঝবার জন্য তিনি সাহাবীদের বুদ্ধি খুলে দিলেন এবং তাঁদের বললেন, “লেখা আছে, মসীহ্‌কে কষ্ট ভোগ করতে হবে এবং তিন দিনের দিন মৃত্যু থেকে জীবিত হয়ে উঠতে হবে।"},{"v":47,"ve":47,"vl":"47","bn":"আরও লেখা আছে, জেরুজালেম থেকে শুরু করে সমস্ত জাতির কাছে মসীহের নামে এই খবর তবলিগ করা হবে যে, তওবা করলে গুনাহের মাফ পাওয়া যায়।"},{"v":48,"ve":48,"vl":"48","bn":"তোমরাই এই সমস্ত বিষয়ের সাক্ষী।"},{"v":49,"ve":49,"vl":"49","bn":"দেখ, আমার পিতা যা দেবার ওয়াদা করেছেন তা আমি তোমাদের কাছে পাঠিয়ে দেব। বেহেশত থেকে শক্তি না পাওয়া পর্যন্ত তোমরা এই শহরেই থেকো।”"},{"heading":"হযরত ঈসা মসীহের বেহেশতে ফিরে যাওয়া","v":50,"ve":50,"vl":"50","bn":"পরে ঈসা তাঁর সাহাবীদের নিয়ে বেথানিয়া পর্যন্ত গেলেন। সেখানে তিনি হাত তুলে তাঁদের দোয়া করলেন।"},{"v":51,"ve":51,"vl":"51","bn":"দোয়া করতে করতেই তিনি তাঁদের ছেড়ে গেলেন এবং তাঁকে বেহেশতে তুলে নেওয়া হল।"},{"v":52,"ve":52,"vl":"52","bn":"তখন তাঁরা উবুড় হয়ে তাঁকে সেজদা করলেন এবং খুব আনন্দের সংগে জেরুজালেমে ফিরে গেলেন।"},{"v":53,"ve":53,"vl":"53","bn":"তাঁরা সব সময় বায়তুল-মোকাদ্দসে উপস্থিত থেকে আল্লাহ্‌র প্রশংসা করতে লাগলেন।"}]}};
